const joinedZones = computed<Zone[]>(() => {
  const joinedLocalZones = zones.value.filter(zone => zone.joined)

  const joinedGovernorateZones = joinedGovernorates.value
    .map((name, index) => {
      const area =
        availableCountryAreas.value.find(item => item.name === name) ||
        zoneAreas.find(item => item.name === name)

      if (!area) return null

      const memberText = area.members.replace(/[^0-9.]/g, '')
      const members = area.members.includes('K')
        ? Math.round(Number(memberText) * 1000)
        : Number(memberText) || 0

      return {
        id: -100000 - index,
        name: area.name,
        location: area.country + ' · ' + area.name,
        description: area.description,
        members,
        participants: 0,
        cover: area.image,
        joined: true,
        goals: [],
        suggestions: [],
        officialRoles: [],
        officialMembers: [],
        elections: [],
        roleProposals: [],
        isGovernorate: true,
        governorateCountry: area.country
      }
    })
    .filter((zone): zone is Zone => zone !== null)

  return [...joinedGovernorateZones, ...joinedLocalZones]
})

const filteredJoinedZones = computed<Zone[]>(() => {
  if (myZonesConnectionFilter.value === 'all') return joinedZones.value

  return joinedZones.value.filter(zone => {
    if (!zone.isGovernorate) return myZonesConnectionFilter.value === 'unspecified'
    const relations = governorateRelations.value[zone.name] || []
    if (myZonesConnectionFilter.value === 'unspecified') return relations.length === 0
    return relations.includes(myZonesConnectionFilter.value)
  })
})

const followedCalls = computed(() => calls.value.filter(call => call.followed))

const myNetworks = computed(() => pages.value.filter(page => page.isMyNetwork === true))

type SidebarConnection = {
  id: string
  label: string
  type: string
  avatar: string
  description: string
  action: () => void
}

const myConnections = computed<SidebarConnection[]>(() => {
  const connections: SidebarConnection[] = []

  pages.value
    .filter(page => page.connected && !page.isMyNetwork)
    .forEach(page => {
      connections.push({
        id: 'page-' + page.id,
        label: page.name,
        type: 'NETWORK',
        avatar: page.avatar,
        description: 'A network you follow or are connected to.',
        action: () => openPage(page)
      })
    })

  followedCalls.value.forEach(call => {
    connections.push({
      id: 'call-' + call.id,
      label: call.title,
      type: 'CALL',
      avatar: call.avatar,
      description: 'A Call you are following.',
      action: () => openCall(call)
    })
  })

  people.value
    .filter(person => person.followed)
    .forEach(person => {
      connections.push({
        id: 'person-' + person.id,
        label: person.name,
        type: 'PERSON',
        avatar: person.avatar,
        description: 'A person you follow.',
        action: () => openPerson(person)
      })
    })

  entities.value
    .filter(entity => entity.identified)
    .forEach(entity => {
      connections.push({
        id: 'entity-' + entity.id,
        label: entity.name,
        type: 'ENTITY',
        avatar: entity.name.slice(0, 2).toUpperCase(),
        description: 'An entity you identified.',
        action: () => openEntity(entity)
      })
    })

  return connections
})

const liveFlowDetectedConnections = computed(() => {
  const normalize = (value: string | undefined) => (value || '').trim().toLowerCase()
  const userZones = new Set(joinedZones.value.map(zone => normalize(zone.name)))
  const detected: Array<{
    id: string
    type: string
    title: string
    detail: string
    evidence: string
    relevant: boolean
    icon: string
    action: () => void
  }> = []

  // An idea and a post are connected only when they share an explicit place context.
  ideaFlowItems.value.forEach(idea => {
    posts.value.forEach(post => {
      if (!idea.zone || !post.zone || normalize(idea.zone) !== normalize(post.zone)) return
      detected.push({
        id: 'idea-post-' + idea.id + '-' + post.id,
        type: 'IDEA ↔ CONVERSATION',
        title: 'An idea and a conversation share a place',
        detail: '“' + idea.title + '” · ' + post.author + ' is also active around ' + idea.zone + '.',
        evidence: 'Shared place context: ' + idea.zone,
        relevant: userZones.has(normalize(idea.zone)),
        icon: '↔',
        action: () => navigate('home')
      })
    })
  })

  // Awareness entries can connect with posts when both refer to the same Zone.
  awarenessItems.value.forEach(item => {
    posts.value.forEach(post => {
      if (!item.zone || !post.zone || normalize(item.zone) !== normalize(post.zone)) return
      detected.push({
        id: 'awareness-post-' + item.id + '-' + post.id,
        type: 'CONCERN ↔ CONVERSATION',
        title: 'A concern meets an ongoing conversation',
        detail: '“' + item.title + '” · activity from ' + post.author + ' shares this place context.',
        evidence: 'Shared place context: ' + item.zone,
        relevant: userZones.has(normalize(item.zone)),
        icon: '⌁',
        action: () => navigate('awareness')
      })
    })
  })

  const unique = detected.filter((item, index, all) =>
    all.findIndex(candidate => candidate.id === item.id) === index
  )
  return unique
    .sort((a, b) => Number(b.relevant) - Number(a.relevant))
    .slice(0, 6)
})

const officialZoneRoles = computed(() => {
  return myOfficialZoneRoles.value.filter(item =>
    zones.value.some(zone => zone.name === item.zoneName)
  )
})

const entityContextZones = computed(() => {
  const names = new Set<string>()
  joinedZones.value.forEach(zone => names.add(zone.name))
  officialZoneRoles.value.forEach(item => names.add(item.zoneName))

  followedCalls.value.forEach(call => {
    entities.value.forEach(entity => {
      if (entity.relatedCalls.includes(call.title)) {
        entity.zoneNames.forEach(zoneName => names.add(zoneName))
      }
    })
  })

  return Array.from(names)
})

const detectedEntities = computed(() => {
  const context = new Set(entityContextZones.value)

  return entities.value
    .map(entity => {
      const matchedZones = entity.zoneNames.filter(zoneName => context.has(zoneName))
      const relatedFollowedCalls = entity.relatedCalls.filter(title =>
        followedCalls.value.some(call => call.title === title)
      )
      const connectedPages = entity.relatedPages.filter(pageName =>
        pages.value.some(page => page.name === pageName && page.connected)
      )

      let reason = 'Related to your network'
      if (matchedZones.length && relatedFollowedCalls.length) {
        reason = 'In your Zone + connected to a Call you follow'
      } else if (matchedZones.length) {
        reason = 'In a Zone you joined'
      } else if (relatedFollowedCalls.length) {
        reason = 'Connected to a Call you follow'
      } else if (connectedPages.length) {
        reason = 'Connected to a Page you follow'
      }

      return {
        ...entity,
        matchedZones,
        relatedFollowedCalls,
        connectedPages,
        reason
      }
    })
    .filter(entity =>
      entity.matchedZones.length ||
      entity.relatedFollowedCalls.length ||
      entity.connectedPages.length
    )
})

const filteredPosts = computed(() => {
  if (!search.value.trim()) return posts.value

  const q = search.value.toLowerCase()

  return posts.value.filter(
    p =>
      p.content.toLowerCase().includes(q) ||
      p.author.toLowerCase().includes(q) ||
      p.zone?.toLowerCase().includes(q)
  )
})

const publicGoals = computed(() => {
  if (!selectedZone.value) return []

  return selectedZone.value.goals.filter(goal => goal.public)
})

