const translations = {
  en: {
    home:'Home', liveFlow:'Live Flow', impactAwareness:'Impact & Awareness', learnDiscover:'Learn & Discover',
    impact:'Impact', flow:'Flow', calls:'Calls', initiatives:'Initiatives', pages:'Pages', more:'More', entities:'Entities',
    people:'People', create:'Create', administration:'Administration', systemDesign:'System Design', systems:'Systems',
    disconnect:'Disconnect', language:'Language', english:'English', arabic:'العربية', french:'French', search:'Search people, pages, posts or zones...'
  },
  ar: {
    home:'الرئيسية', liveFlow:'التدفق الحي', impactAwareness:'الأثر والوعي', learnDiscover:'تعلّم واكتشف',
    impact:'التأثير', flow:'التدفق', calls:'المكالمات', initiatives:'المبادرات', pages:'الصفحات', more:'المزيد', entities:'الكيانات',
    people:'الأشخاص', create:'إنشاء', administration:'الإدارة', systemDesign:'تصميم النظام', systems:'الأنظمة',
    disconnect:'تسجيل الخروج', language:'اللغة', english:'الإنجليزية', arabic:'العربية', french:'الفرنسية', search:'ابحث عن أشخاص أو صفحات أو منشورات أو مناطق...'
  },
  fr: {
    home:'Accueil', liveFlow:'Flux en direct', impactAwareness:'Impact et sensibilisation', learnDiscover:'Apprendre et découvrir',
    impact:'Impact', flow:'Flux', calls:'Appels', initiatives:'Initiatives', pages:'Pages', more:'Plus', entities:'Entités',
    people:'Personnes', create:'Créer', administration:'Administration', systemDesign:'Conception du système', systems:'Systèmes',
    disconnect:'Déconnexion', language:'Langue', english:'Anglais', arabic:'Arabe', french:'Français', search:'Rechercher des personnes, pages, publications ou zones...'
  }
} as const

function t(key: keyof typeof translations.en) {
  return translations[language.value][key]
}

const originalTextNodes = new WeakMap<Text, string>()
const originalAttributeValues = new WeakMap<Element, Map<string, string>>()
const translatableAttributes = ['placeholder', 'title', 'aria-label', 'aria-placeholder', 'alt'] as const

function translatePage() {
  const dictionary = language.value === 'ar' ? arabicDictionary : language.value === 'fr' ? frenchDictionary : null
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT)
  const nodes: Text[] = []
  let node: Node | null
  while ((node = walker.nextNode())) nodes.push(node as Text)

  nodes.forEach((textNode) => {
    if (!originalTextNodes.has(textNode)) originalTextNodes.set(textNode, textNode.data || '')
    const original = originalTextNodes.get(textNode) || ''
    const value = original.replace(/\\s+/g, ' ').trim()
    if (!value) return
    const translated = dictionary?.[value]
    const nextValue = translated ? original.replace(value, translated) : original
    if (textNode.data !== nextValue) textNode.data = nextValue
  })

  document.querySelectorAll<HTMLElement>('*').forEach((element) => {
    let originals = originalAttributeValues.get(element)
    if (!originals) {
      originals = new Map<string, string>()
      originalAttributeValues.set(element, originals)
    }
    translatableAttributes.forEach((attribute) => {
      if (!element.hasAttribute(attribute)) return
      if (!originals!.has(attribute)) originals!.set(attribute, element.getAttribute(attribute) || '')
      const original = originals!.get(attribute) || ''
      const value = original.replace(/\\s+/g, ' ').trim()
      const translated = dictionary?.[value]
      const nextValue = translated ? original.replace(value, translated) : original
      if (element.getAttribute(attribute) !== nextValue) element.setAttribute(attribute, nextValue)
    })
  })
}


function setLanguage(value: 'en' | 'ar' | 'fr') {
  language.value = value
  translatePage()
  showLanguageMenu.value = false
  showAccountMenu.value = false
  document.documentElement.lang = value
  document.documentElement.dir = value === 'ar' ? 'rtl' : 'ltr'
  writeStoredValue('commons-language', value)
}

function disconnect() {
  showAccountMenu.value = false
  activeView.value = 'disconnected'
  selectedZone.value = null
  selectedCall.value = null
  selectedPage.value = null
  selectedPerson.value = null
  selectedEntity.value = null
}

function getPlaceConnectionReasons(place: Entity) {
  const reasons: string[] = ['INSIDE YOUR ZONE']

  if (place.relatedCalls.length) reasons.push('CONNECTED TO A CALL')
  if (place.relatedPages.length) reasons.push('CONNECTED TO A NETWORK')
  if (place.identified) reasons.push('YOU IDENTIFIED IT')
  if (place.myReview) reasons.push('YOU REVIEWED IT')

  return reasons
}

function showJoinConfirmation(name: string) {
  joinConfirmation.value = name + ' was added to Your Zones.'

  if (joinConfirmationTimer) clearTimeout(joinConfirmationTimer)
  joinConfirmationTimer = setTimeout(() => {
    joinConfirmation.value = ''
    joinConfirmationTimer = null
  }, 3200)

  sidebarSpace.value = 'zones'
}

function setAwarenessFilter(filter: string) {
  awarenessFilter.value = filter
}

const awarenessLensExpanded = ref(false)
const awarenessTopicsExpanded = ref(false)

const awarenessImpactTypes = [
  'Environmental',
  'Social & wellbeing',
  'Economic & livelihoods',
  'Health & safety',
  'Culture & education',
  'Civic & governance'
]

const awarenessCategories = [
  'Land & soil',
  'Water & oceans',
  'Air & atmosphere',
  'Climate & energy',
  'Biodiversity & habitats',
  'Food & agriculture',
  'Cities & mobility',
  'Waste & circularity',
  'People & wellbeing',
  'Education & culture',
  'Economy & livelihoods',
  'Technology & innovation'
]

function updateSelectedImpactIssue(value: string) {
  selectedImpactIssueId.value = value ? Number(value) : null
}

function focusSelectedImpactIssue() {
  const item = allImpactingAwarenessItems.value.find(entry => entry.id === selectedImpactIssueId.value)
  if (!item) return
  awarenessCategory.value = item.category
  awarenessImpactType.value = item.sourceType === 'Zone post' || item.sourceType === 'Zone suggestion'
    ? 'ALL'
    : (item.impactType || 'ALL')
  awarenessFilter.value = 'ALL'
}

const filteredAwarenessItems = computed(() => {
  return allImpactingAwarenessItems.value.filter(item => {
    const matchesCountry = impactingCountryFilter.value === 'ALL' || item.country === impactingCountryFilter.value
    const matchesSource = impactingSourceFilter.value === 'ALL' || item.sourceKind === 'post' || item.sourceKind === 'suggestion'
    const matchesCategory = awarenessCategory.value === 'ALL' || item.category === awarenessCategory.value
    const matchesImpact = awarenessImpactType.value === 'ALL' || item.impactType === awarenessImpactType.value
    const filter = awarenessFilter.value
    const matchesSection = filter === 'ALL'
      || (filter === 'HAPPENING' && !!item.happening)
      || (filter === 'CONSEQUENCES' && !!item.ifNothingChanges)
      || (filter === 'ACTION' && !!item.whatWeCanDo)
      || filter === 'LEARN'
      || (filter === 'FUTURES' && !!item.possibleChange)
    return matchesCountry && matchesSource && matchesCategory && matchesImpact && matchesSection
  })
})

function submitAwarenessItem() {
  const draft = awarenessDraft.value
  if (!draft.title.trim() || !draft.happening.trim()) return
  awarenessItems.value.unshift({
    id: Date.now(),
    title: draft.title.trim(),
    country: draft.country || impactingCountryFilter.value,
    category: draft.category,
    impactType: draft.impactType,
    sourceType: draft.sourceType,
    sourceName: draft.sourceName.trim() || draft.sourceType,
    zone: draft.zone.trim() || 'No Zone specified',
    happening: draft.happening.trim(),
    ifNothingChanges: draft.ifNothingChanges.trim() || 'Possible consequences have not been explored yet. Add observations and reliable context before drawing conclusions.',
    whatWeCanDo: draft.whatWeCanDo.trim() || 'Invite people to discuss the issue and identify a constructive next step.',
    possibleChange: draft.possibleChange.trim() || 'A clearer shared understanding and a next step shaped by the people involved.',
    evidence: draft.evidence.trim(),
    createdAt: 'Just now'
  })
  awarenessCategory.value = 'ALL'
  awarenessImpactType.value = 'ALL'
  awarenessFilter.value = 'ALL'
  impactingCountryFilter.value = draft.country || 'Tunisia'
  selectedImpactIssueId.value = null
  showRaiseAwareness.value = false
  awarenessDraft.value = {
    title: '',
    country: 'Tunisia',
    category: 'Biodiversity & habitats',
    impactType: 'Environmental',
    sourceType: 'Person',
    sourceName: '',
    zone: '',
    happening: '',
    ifNothingChanges: '',
    whatWeCanDo: '',
    possibleChange: '',
    evidence: ''
  }
}

function releaseIdea() {
  const text = ideaFlowDraft.value.trim()
  if (!text) return
  ideaFlowItems.value.unshift({
    id: Date.now(),
    title: text.length > 100 ? text.slice(0, 97).trimEnd() + '…' : text,
    body: text,
    author: 'Your spark',
    category: 'FRESH SPARK',
    zone: 'Not specified',
    thoughts: [],
    mood: 'violet'
  })
  ideaFlowDraft.value = ''
}

function addIdeaThought(id: number) {
  const thought = (ideaFlowThoughtDrafts.value[id] || '').trim()
  if (!thought) return
  const idea = ideaFlowItems.value.find(item => item.id === id)
  if (!idea) return
  idea.thoughts.push(thought)
  ideaFlowThoughtDrafts.value[id] = ''
  ideaFlowOpenThought.value = null
}

function openIdeaFlowSpace() {
  navigate('live-flow')
  liveFlowSpace.value = 'ideas'
}

function openPlatformCircle(circle: { id: string; view: string }) {
  showCircleHome.value = false
  navigate(circle.view)
}

function openAwarenessReport() {
  if (activeView.value !== 'awareness') playNavigationPortal()
  activeView.value = 'awareness'
  showRaiseAwareness.value = true
  isReportingIssue.value = true
}

function openHomeExplore() {
  homeDisplayMode.value = 'content'
  // On mobile, Explore opens the content with the header collapsed so the
  // Explore and Show header controls stay visible in the available space.
  homeHeroHidden.value = window.matchMedia('(max-width: 760px)').matches
  homeHeaderChatOpen.value = false
  nextTick(() => window.scrollTo({ top: 0, behavior: 'smooth' }))
}

function navigate(view: string) {
  if (activeView.value !== view) playNavigationPortal()
  activeView.value = view
  liveFlowSpace.value = 'overview'
  selectedZone.value = null
  selectedCall.value = null
  selectedPage.value = null
  selectedPerson.value = null
  selectedEntity.value = null
  activeZoneTab.value = 'overview'
  liveEngagement.value = null

  // Impact always opens with its Zones submenu visible.
  if (view === 'zones' || view === 'around-zones') {
    showZonesSubnav.value = true
  }
}

function openLiveEngagement(kind: 'people' | 'action' | 'flow') {
  showWhatsGoingOn.value = false
  liveEngagement.value = kind
  activeView.value = 'live-' + kind
  selectedZone.value = null
  selectedCall.value = null
  selectedPage.value = null
  selectedPerson.value = null
  selectedEntity.value = null
  activeZoneTab.value = 'overview'
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

function openCallSpace(call: CommunityCall) {
  selectedCall.value = call
  activeView.value = 'call'
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

function openPage(page: Page) {
  selectedPage.value = page
  activeView.value = 'page'
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

function openPageByName(name: string) {
  const page = pages.value.find(item => item.name.toLowerCase() === name.toLowerCase())
  if (page) openPage(page)
}

function openPerson(person: any) {
  selectedPerson.value = person
  activeView.value = 'person'
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

function getPostInspirations(post: Post) {
  const inspirations = [
    {
      label: 'POSSIBILITY',
      title: post.zone ? 'What could this become in this place?' : 'What could this idea become?',
      text: post.zone ? 'A small local action, a new meeting place, or something people can build together.' : 'A conversation, a project, a Call, or a new question worth exploring.'
    },
    {
      label: 'CONNECTION',
      title: 'Who could take this further?',
      text: 'People, Pages, existing initiatives or local knowledge that could connect with this thought.'
    }
  ]

  if (post.id === 2) {
    inspirations[0] = {
      label: 'ACTION',
      title: 'What could this become?',
      text: 'A simple way for people to identify what needs attention around them and turn it into a shared possibility.'
    }
  }

  if (post.id === 3) {
    inspirations[0] = {
      label: 'POSSIBILITY',
      title: 'What could this become?',
      text: 'A space where different solutions can meet, be explored and eventually become practical action.'
    }
  }

  return inspirations
}

function openZone(zone: Zone) {
  selectedZone.value = zone
  activeView.value = 'zone'
  activeZoneTab.value = 'overview'
}


function selectGovernorateRegion(regionName: string) {
  selectedGovernorateRegion.value = regionName
}

function setGovernorateRelation(name: string, relation: string) {
  const current = governorateRelations.value[name] || []
  const next = current.includes(relation)
    ? current.filter(item => item !== relation)
    : [...current, relation]

  governorateRelations.value = {
    ...governorateRelations.value,
    [name]: next
  }
}

function governorateRelationLabel(name: string) {
  const selected = governorateRelations.value[name] || []
  return governorateConnectionOptions
    .filter(option => selected.includes(option.id))
    .map(option => option.title)
    .join(' · ')
}

function joinedZoneConnectionLabel(zone: Zone) {
  const connection = governorateRelationLabel(zone.name)
  return connection || 'Connection not specified'
}

function communitySignal(name: string): CommunitySignal {
  return communitySignals[name] || {
    attentionReports: 0,
    attentionUpvotes: 0,
    impactReports: 0,
    impactUpvotes: 0
  }
}

function communitySignalItems(name: string) {
  const signal = communitySignal(name)
  const items: Array<{ type: 'reported' | 'attention' | 'impact' | 'confirmed'; label: string; detail: string }> = []

  if (signal.attentionReports > 0) {
    items.push({
      type: signal.attentionUpvotes >= 3 ? 'attention' : 'reported',
      label: signal.attentionUpvotes >= 3 ? 'NEEDS ATTENTION' : 'REPORTED',
      detail: signal.attentionUpvotes >= 3
        ? `confirmed by ${signal.attentionUpvotes} upvotes`
        : `${signal.attentionReports} report${signal.attentionReports === 1 ? '' : 's'}`
    })
  }

  if (signal.impactReports > 0) {
    items.push({
      type: signal.impactUpvotes >= 3 ? 'impact' : 'reported',
      label: signal.impactUpvotes >= 3 ? 'NEEDS IMPACT' : 'REPORTED',
      detail: signal.impactUpvotes >= 3
        ? `confirmed by ${signal.impactUpvotes} upvotes`
        : `${signal.impactReports} report${signal.impactReports === 1 ? '' : 's'}`
    })
  }

  if (!items.length) {
    items.push({
      type: 'confirmed',
      label: 'NO SIGNAL YET',
      detail: 'waiting for community reports'
    })
  }

  return items
}

type SignalEvidence = {
  signal: 'attention' | 'impact'
  source: string
  excerpt: string
  votes: number
}

const signalEvidence: Record<string, SignalEvidence[]> = {
  'Tunis North': [
    { signal: 'attention', source: 'POST · local resident', excerpt: 'The public garden needs better maintenance and more usable space.', votes: 8 },
    { signal: 'attention', source: 'POST · Zone participant', excerpt: 'Several people are raising the same concern about the condition of shared streets.', votes: 6 },
    { signal: 'impact', source: 'POST · community initiative', excerpt: 'A community garden could turn an underused space into something useful for the neighborhood.', votes: 7 },
    { signal: 'impact', source: 'SUGGESTION · local action', excerpt: 'Who wants to help organize a first clean-up and planting day?', votes: 4 }
  ],
  'La Marsa': [
    { signal: 'attention', source: 'POST · resident', excerpt: 'Some coastal areas need attention after busy weekends.', votes: 4 },
    { signal: 'impact', source: 'POST · participant', excerpt: 'There is an opportunity to organize a local coastal care action.', votes: 9 }
  ],
  'Sidi Bou Said': [
    { signal: 'attention', source: 'POST · resident', excerpt: 'Traffic and pedestrian pressure are affecting this part of the area.', votes: 4 },
    { signal: 'impact', source: 'POST · cultural initiative', excerpt: 'Local cultural spaces could connect more people through shared activities.', votes: 8 }
  ],
  'Tunis': [
    { signal: 'attention', source: 'POST · resident', excerpt: 'A recurring issue was reported around public-space maintenance.', votes: 5 },
    { signal: 'impact', source: 'SUGGESTION · community member', excerpt: 'People could coordinate a small local action and measure the result.', votes: 5 }
  ],
  'Ariana': [
    { signal: 'attention', source: 'POST · local participant', excerpt: 'Several people noticed the same issue and asked others to look closer.', votes: 6 },
    { signal: 'impact', source: 'POST · initiative', excerpt: 'A local group is looking for people who want to turn this concern into action.', votes: 6 }
  ]
}

function toggleSignalEvidence(name: string) {
  showSignalEvidence.value = {
    ...showSignalEvidence.value,
    [name]: !showSignalEvidence.value[name]
  }
}

function getSignalEvidence(name: string, signalType: 'attention' | 'impact') {
  return (signalEvidence[name] || []).filter(item => item.signal === signalType)
}

function signalEvidenceSummary(name: string, signalType: 'attention' | 'impact') {
  const signal = communitySignal(name)
  const reports = signalType === 'attention' ? signal.attentionReports : signal.impactReports
  const upvotes = signalType === 'attention' ? signal.attentionUpvotes : signal.impactUpvotes
  const label = signalType === 'attention' ? 'attention' : 'impact'
  return `${reports} report${reports === 1 ? '' : 's'} → ${upvotes} community upvote${upvotes === 1 ? '' : 's'} → NEEDS ${label.toUpperCase()}`
}

function isGovernorateRelationSelected(name: string, relation: string) {
  return (governorateRelations.value[name] || []).includes(relation)
}

function isGovernorateJoined(name: string) {
  return joinedGovernorates.value.includes(name)
}

function toggleGovernorateJoin(name: string) {
  const index = joinedGovernorates.value.indexOf(name)

  if (index >= 0) {
    joinedGovernorates.value.splice(index, 1)
    return
  }

  joinedGovernorates.value.push(name)

  // Joining a governorate immediately makes it visible in YOUR ZONES.
  showJoinConfirmation(name)
}

function openMyGovernorate(name: string) {
  const area = zoneAreas.find(item => item.name === name) || availableCountryAreas.value.find(item => item.name === name)
  selectedCountry.value = area?.country || 'Tunisia'
  selectedZoneRegion.value = area?.region || ''
  selectedZoneArea.value = name
  selectedSpecificZone.value = ''
  zonePreviewName.value = ''
  zoneNavigationLevel.value = 'specific-zones'
  selectedAreaImage.value = area?.image || ''
  activeView.value = 'zones'
  sidebarSpace.value = 'zones'
  nextTick(() => window.scrollTo({ top: 0, behavior: 'smooth' }))
}
function openMyZone(zone: Zone) {
  selectedZone.value = zone
  activeView.value = 'zone'
  activeZoneTab.value = 'overview'
  sidebarSpace.value = 'zones'
  nextTick(() => window.scrollTo({ top: 0, behavior: 'smooth' }))
}


const myJoinedGovernorates = computed(() =>
  joinedGovernorates.value.map(name => ({
    name,
    relation: governorateRelationLabel(name) || 'Connection not specified'
  }))
)


function selectGovernorate(governorateName: string) {
  const governorate = availableCountryAreas.value.find(area => area.name === governorateName)

  selectedZoneRegion.value = governorate?.region || ''
  selectedZoneArea.value = governorateName
  selectedSpecificZone.value = ''
  zonePreviewName.value = ''
  zoneNavigationLevel.value = 'specific-zones'
  selectedAreaImage.value = governorate?.image || ''

  nextTick(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' })
  })
}

function backToGovernorates() {
  selectedZoneArea.value = ''
  selectedSpecificZone.value = ''
  zonePreviewName.value = ''
  zoneNavigationLevel.value = 'governorates'
  selectedAreaImage.value = selectedZoneRegion.value
    ? zoneRegions.find(region => region.name === selectedZoneRegion.value)?.image || ''
    : ''
}

async function openSpecificZone(zoneName: string) {
  selectedSpecificZone.value = zoneName
  zonePreviewName.value = zoneName

  // The selected zone behaves like a new page: render it first, then
  // move the user to the top so the zone header is immediately visible.
  await nextTick()
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

const showSpecificZones = ref(false)

function toggleSpecificZones() {
  showSpecificZones.value = !showSpecificZones.value

  if (showSpecificZones.value) {
    nextTick(() => {
      document.querySelector('.specific-zone-list')?.scrollIntoView({
        behavior: 'smooth',
        block: 'start'
      })
    })
  }
}

function closeZonePreview() {
  zonePreviewName.value = ''
  selectedSpecificZone.value = ''
}

function enterPreviewedZone() {
  const zoneName = zonePreviewName.value
  if (!zoneName) return

  let zone = zones.value.find(item => item.name.toLowerCase() === zoneName.toLowerCase())

  if (!zone) {
    const directoryZone = specificZones.find(item => item.name === zoneName)

    zone = {
      id: 1000 + (directoryZone?.id || Date.now()),
      name: zoneName,
      location: directoryZone?.location || zoneName + ', Tunisia',
      description: 'A local community space for people connected to this place.',
      members: 0,
      participants: 0,
      cover: selectedAreaImage.value,
      joined: false,
      goals: [],
      suggestions: [],
      officialRoles: [],
      officialMembers: [],
      elections: [],
      roleProposals: []
    }

    zones.value.push(zone)
  }

  zonePreviewName.value = ''
  selectedSpecificZone.value = ''
  openZone(zone)
  window.scrollTo({ top: 0, behavior: 'smooth' })
}


function setZoneTab(tab: string) {
  activeZoneTab.value = tab
}

/* =====================================================
   SOCIAL ACTIONS
   ===================================================== */

function toggleFollow(page: Page) {
  page.connected = !page.connected
}

function togglePersonFollow(person: any) {
  person.followed = !person.followed
}

function likePost(post: Post) {
  post.liked = !post.liked
  post.likes += post.liked ? 1 : -1
}

function participate(zone: Zone) {
  zone.joined = !zone.joined

  if (zone.joined) {
    zone.participants++
    // Keep the personal Zone layer synchronized immediately after joining.
    showJoinConfirmation(zone.name)
  } else {
    zone.participants = Math.max(0, zone.participants - 1)
  }
}

function voteSuggestion(suggestion: Suggestion) {
  suggestion.voted = !suggestion.voted
  suggestion.votes += suggestion.voted ? 1 : -1
}

/* =====================================================
   CREATION ACTIONS
   ===================================================== */

function createPost() {
  if (!postText.value.trim()) return

  posts.value.unshift({
    id: Date.now(),
    author: 'You',
    handle: '@you',
    avatar: 'YO',
    time: 'now',
    content: postText.value,
    likes: 0,
    comments: 0,
    liked: false
  })

  postText.value = ''
  showCreatePost.value = false
}

function openCreateChoice(type: 'page' | 'call' = 'page') {
  createType.value = type
  showCreateChoice.value = true
}

function closeCreateChoice() {
  showCreateChoice.value = false
}

function createPage() {
  if (!newPageName.value.trim()) return

  const page: Page = {
    id: Date.now(),
    name: newPageName.value.trim(),
    handle: newPageHandle.value.trim() || '@' + newPageName.value.trim().toLowerCase().replace(/[^a-z0-9]+/g, ''),
    description: newPageDescription.value.trim() || 'A new Page created to bring people, ideas and action together.',
    followers: '0',
    avatar: newPageName.value.trim().slice(0, 2).toUpperCase(),
    color: '#5b8def',
    connected: true,
    category: newPageCategory.value,
    isMyNetwork: true
  }

  pages.value.unshift(page)
  pageSearch.value = ''
  pageCategory.value = 'All'

  newPageName.value = ''
  newPageHandle.value = ''
  newPageCategory.value = 'Community'
  newPageDescription.value = ''
  showCreateChoice.value = false
}

function createCall() {
  if (!newCallTitle.value.trim() || !newCallMessage.value.trim()) return

  const call: CommunityCall = {
    id: Date.now(),
    title: newCallTitle.value.trim(),
    launchedBy: 'You',
    handle: '@you',
    avatar: 'YO',
    category: 'COMMUNITY CALL',
    status: 'OPEN',
    time: 'Launched just now',
    headline: newCallMessage.value.trim(),
    description: 'An open call created to gather questions, ideas, connections and possible actions around one shared possibility.',
    participants: 1,
    ideas: 0,
    interactions: 0,
    location: newCallLocation.value.trim() || 'Open community space',
    followed: true,
    interactionsList: []
  }

  calls.value.unshift(call)

  newCallTitle.value = ''
  newCallMessage.value = ''
  newCallLocation.value = ''
  showCreateChoice.value = false
}


function openEntity(entity: Entity) {
  selectedEntity.value = entity
  activeView.value = 'entity'
  entityReviewText.value = entity.myReview
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

function identifyEntity(entity: Entity) {
  entity.identified = !entity.identified
}

function createEntity() {
  if (newEntityType.value === 'PLACE' && !newEntityZone.value && selectedZone.value) {
    newEntityZone.value = selectedZone.value.name
  }
  if (!newEntityName.value.trim()) return

  const entity: Entity = {
    id: Date.now(),
    name: newEntityName.value.trim(),
    type: newEntityType.value,
    description: newEntityDescription.value.trim() || 'A new entity identified by the community.',
    location: newEntityLocation.value.trim() || 'Local area',
    zoneNames: newEntityZone.value ? [newEntityZone.value] : [],
    relatedPages: [],
    relatedCalls: [],
    identified: true,
    reviews: 0,
    rating: 0,
    myReview: ''
  }

  entities.value.unshift(entity)
  selectedEntity.value = entity

  newEntityName.value = ''
  newEntityType.value = 'PLACE'
  newEntityDescription.value = ''
  newEntityLocation.value = ''
  newEntityZone.value = ''
  showCreateEntity.value = false
  activeView.value = 'entity'
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

function submitEntityReview() {
  if (!selectedEntity.value || !entityReviewText.value.trim()) return

  const wasEmpty = !selectedEntity.value.myReview
  selectedEntity.value.myReview = entityReviewText.value.trim()
  if (wasEmpty) selectedEntity.value.reviews++
  entityReviewText.value = selectedEntity.value.myReview
}

function attachEntityToZone(entity: Entity, zoneName: string) {
  if (!zoneName || entity.zoneNames.includes(zoneName)) return
  entity.zoneNames.push(zoneName)
}

function handleEntityZoneChange(entity: Entity | null, event: Event) {
  if (!entity) return
  const target = event.target as HTMLSelectElement | null
  attachEntityToZone(entity, target?.value || '')
}

function createZone() {
  if (!newZoneName.value.trim()) return

  const zone: Zone = {
    id: Date.now(),
    name: newZoneName.value,
    location: newZoneLocation.value || 'Local zone',
    description:
      newZoneDescription.value ||
      'A new community zone created by its members.',
    members: 1,
    participants: 1,
    cover:
      'https://images.unsplash.com/photo-1444723121867-7a241cacace9?auto=format&fit=crop&w=1400&q=80',
    joined: true,
    goals: [],
    suggestions: [],
      officialRoles: [],
  officialMembers: [],
  elections: [],
  roleProposals: []

  }

  zones.value.unshift(zone)

  newZoneName.value = ''
  newZoneLocation.value = ''
  newZoneDescription.value = ''
  showCreateZone.value = false

  openZone(zone)
}

function createSuggestion() {
  if (!selectedZone.value || !suggestionText.value.trim()) return

  selectedZone.value.suggestions.unshift({
    id: Date.now(),
    author: 'You',
    avatar: 'YO',
    text: suggestionText.value,
    votes: 0,
    voted: false,
    answers: 0,
    status: 'Open'
  })

  suggestionText.value = ''
  showCreateSuggestion.value = false
}

/* =====================================================
   ZONE GOVERNANCE
   ===================================================== */

function createOfficialRole() {
  if (!selectedZone.value || !newRoleName.value.trim()) return

  selectedZone.value.officialRoles.push({
    id: Date.now(),
    name: newRoleName.value.trim(),
    description:
      newRoleDescription.value.trim() ||
      'A role created by the Zone to support its community work.',
    elected: true
  })

  newRoleName.value = ''
  newRoleDescription.value = ''
  showCreateRole.value = false
}

function voteElection(election: Election, candidate: ElectionCandidate) {
  if (election.status !== 'Open') return

  const previous = election.candidates.find(item => item.voted)

  if (previous && previous.id !== candidate.id) {
    previous.voted = false
    previous.votes--
  }

  candidate.voted = !candidate.voted
  candidate.votes += candidate.voted ? 1 : -1
}

function voteRoleProposal(proposal: RoleProposal, choice: 'yes' | 'no') {
  if (proposal.voted) return

  if (choice === 'yes') {
    proposal.yesVotes++
  } else {
    proposal.noVotes++
  }

  proposal.voted = true
}
onMounted(() => {
  updateImpactDiscoveryLayout()
  impactDiscoveryMediaQuery?.addEventListener('change', handleImpactDiscoveryLayoutChange)
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches
  platformOpeningTimer = setTimeout(() => {
    showPlatformOpening.value = false
    platformOpeningTimer = null
  }, prefersReducedMotion ? 80 : 2550)

  const savedSidebarShortcuts = readStoredValue('commons-mobile-sidebar-shortcuts')
  if (savedSidebarShortcuts) {
    try {
      const parsed = JSON.parse(savedSidebarShortcuts)
      if (Array.isArray(parsed)) {
        mobileSidebarShortcuts.value = parsed.filter((item): item is MobileSidebarShortcut =>
          !!item && typeof item.id === 'string' && typeof item.label === 'string' &&
          typeof item.mark === 'string' && typeof item.view === 'string' &&
          mobileSidebarDestinations.some(destination => destination.id === item.id && destination.view === item.view)
        )
      }
    } catch { /* Ignore invalid saved shortcut data and keep the default navigation. */ }
  }
  const savedLiveSong = readStoredValue('commons-live-flow-song')
  if (savedLiveSong) loadLiveSong(savedLiveSong)
  const savedLiveQueue = readStoredValue('commons-live-flow-video-queue')
  if (savedLiveQueue) loadLiveQueue(savedLiveQueue)
  window.addEventListener('storage', handleLiveSongStorage)
  const savedLanguage = readStoredValue('commons-language')
  if (savedLanguage === 'ar' || savedLanguage === 'en' || savedLanguage === 'fr') language.value = savedLanguage
  document.documentElement.lang = language.value
  document.documentElement.dir = language.value === 'ar' ? 'rtl' : 'ltr'
  translatePage()
  languageObserver = new MutationObserver(() => {
    if (language.value === 'ar' || language.value === 'fr') translatePage()
  })
  languageObserver.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['placeholder', 'title', 'aria-label', 'aria-placeholder', 'alt'] })
  liveMovingChatTimer = setInterval(pushLiveMovingSampleMessage, 12000)
  heroTimer = setInterval(() => {
    activeHero.value = (activeHero.value + 1) % heroes.length
  }, 8000)
})

onBeforeUnmount(() => {
  impactDiscoveryMediaQuery?.removeEventListener('change', handleImpactDiscoveryLayoutChange)
  impactDiscoveryMediaQuery = null
  if (platformOpeningTimer) {
    clearTimeout(platformOpeningTimer)
    platformOpeningTimer = null
  }
  if (navigationPortalTimer) {
    clearTimeout(navigationPortalTimer)
    navigationPortalTimer = null
  }
  window.removeEventListener('storage', handleLiveSongStorage)
  languageObserver?.disconnect()
  languageObserver = null
  if (liveMovingChatTimer) {
    clearInterval(liveMovingChatTimer)
    liveMovingChatTimer = null
  }
  if (heroTimer) {
    clearInterval(heroTimer)
    heroTimer = null
  }
})

</script>

