      </span>
      <span class="join-confirmation-arrow" aria-hidden="true">→</span>
      <button type="button" @click="joinConfirmation = ''" aria-label="Dismiss confirmation">×</button>
    </div>

    <!-- SIDEBAR -->
    <aside class="sidebar">

      <div class="brand" :class="{ 'brand-portal-active': showNavigationPortal }" @click="navigate('home')" role="button" tabindex="0" @keydown.enter="navigate('home')" aria-label="Nfas home">

