          </div>
          <div class="home-chat-rooms" aria-label="Example conversations">
            <button v-for="room in (homeConnectionPanel === 'initiatives' ? homeChatRooms.filter(room => ['tunis-green', 'local-possibilities', 'ideas-lab'].includes(room.id)) : homeChatRooms)" :key="room.id" type="button"
              class="home-chat-room" :class="['chat-room-' + room.color, { active: homeActiveChatRoom === room.id }]"
              @click="joinHomeChatRoom(room.id)">
              <span class="home-chat-room-mark" aria-hidden="true">{{ room.mark }}</span>
              <span class="home-chat-room-copy"><strong>{{ room.name }}</strong><small>{{ room.topic }}</small><em>{{ room.members }}</em></span>
              <span class="home-chat-room-join">{{ homeJoinedChatRooms.includes(room.id) ? (homeActiveChatRoom === room.id ? 'Open ✓' : 'Joined') : 'Join +' }}</span>
            </button>
          </div>
          <p v-if="!homeActiveChatRoom" class="home-chat-select-prompt">Choose a conversation above to open its messages.</p>
          <template v-else>
            <div class="home-header-chat-active-room">
              <span class="home-connection-kicker">CURRENT CONVERSATION</span>
              <strong>{{ homeChatRooms.find(room => room.id === homeActiveChatRoom)?.name }}</strong>
            </div>
            <div class="home-header-chat-messages" aria-live="polite">
              <article v-for="message in homeHeaderChatMessages.filter(item => item.room === homeActiveChatRoom)" :key="message.id"
                class="home-header-chat-message" :class="{ 'is-you': message.author === 'YOU' }">
                <div class="home-header-chat-message-meta"><strong>{{ message.author }}</strong><span>{{ message.time }}</span></div>
                <p>{{ message.text }}</p>
              </article>
            </div>
            <form class="home-header-chat-composer" @submit.prevent="sendHomeHeaderChatMessage">
              <input v-model="homeHeaderChatDraft" type="text" maxlength="500"
                placeholder="Write a message or question…" aria-label="Write a chat message" />
              <button type="submit" :disabled="!homeHeaderChatDraft.trim()">Send <span aria-hidden="true">↗</span></button>
            </form>
            <p class="home-header-chat-note">This preview is stored in this page session; it is not yet a shared live chat.</p>
          </template>
        </section>
        <div v-if="!homeHeroHidden && !homeHeaderChatOpen" class="hero-stage">
          <transition name="hero-fade" mode="out-in">
            <div :key="activeHero" class="hero hero-rotating">
              <div class="hero-copy">
                <span class="hero-label hero-initiatives-label">INITIATIVES · ACTION</span>
                <span class="hero-label hero-community-tagline" aria-label="Your place, your people, your impact">
                  <span class="hero-tag-place">YOUR PLACE</span>
                  <span class="hero-tag-separator"> · </span>
                  <span class="hero-tag-people">YOUR PEOPLE</span>
                  <span class="hero-tag-separator"> · </span>
                  <span class="hero-tag-voice">YOUR IMPACT</span>
                </span>

                <div v-if="activeHero !== 0" class="hero-zone-label">
                  <span class="hero-zone-label-text">Your Zone</span>
                </div>

                <h1>
                  <span v-if="activeHero === 0" class="hero-heading-white-home"><span class="hero-heading-ideas-gradient">Ideas</span> <span class="hero-heading-white-shadow">become</span></span>
                  <br v-if="activeHero === 0" />
                  <span
                    v-if="activeHero === 0"
                    class="hero-accent-blue hero-accent-blue-home"
                  >
                    {{ heroes[activeHero].titleAccent }}
                  </span>
                  <span v-else class="hero-place-change">a place for change.</span>
                  <br v-if="activeHero !== 0" />
                  <template v-if="heroes[activeHero].titleAfter">
                    <span class="hero-accent-impact">{{ heroes[activeHero].titleAfter }}</span>
                    <span class="hero-accent-white hero-where-you-are">
                      {{ heroes[activeHero].secondAccent }}
                    </span>
                  </template>
                </h1>

                <p>{{ heroes[activeHero].description }}</p>
              </div>

              <!-- Keep the original animated visual: only the hero copy changes. -->
              <div
                class="hero-orbit"
                :class="{ 'hero-orbit-original': activeHero === 0 }"
                aria-hidden="true"
              >
                <div class="orbit-ring ring-one"></div>
                <div class="orbit-ring ring-two"></div>
                <button
                  v-if="activeHero === 0"
                  type="button"
                  class="orbit-core orbit-core-action"
                  aria-label="Open Idea Flow"
                  title="Explore ideas in Live Flow"
                  @click="openIdeaFlowSpace"
                >
                  <span>AC</span>
                </button>
                <div v-else class="orbit-core">
                  <span>ZONE</span>
                </div>
                <div class="orbit-node node-a"></div>
                <div class="orbit-node node-b"></div>
                <div class="orbit-node node-c"></div>
              </div>
            </div>
          </transition>

          <div class="hero-progress">
            <button
              v-for="(_, index) in heroes"
              :key="index"
              type="button"
              :aria-label="`Show hero ${index + 1}`"
              :class="{ active: index === activeHero }"
              @click="activeHero = index"
            ></button>
          </div>
        </div>


