      </section>

      <section v-if="activeView === 'live-flow'" class="content live-engagement-content">
        <nav class="live-flow-space-nav" aria-label="Live Flow views">
          <button type="button" :class="{ active: liveFlowSpace === 'overview' }" :aria-pressed="liveFlowSpace === 'overview'" @click="liveFlowSpace = 'overview'">
            <svg class="live-flow-line-point-icon" viewBox="0 0 18 18" width="18" height="18" aria-hidden="true" focusable="false"><path d="M2 9H16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/><circle cx="9" cy="9" r="2.2" fill="currentColor"/></svg> Live Flow
          </button>
          <button type="button" :class="{ active: liveFlowSpace === 'feed' }" :aria-pressed="liveFlowSpace === 'feed'" @click="liveFlowSpace = 'feed'">
            <svg class="live-flow-feed-lines-icon" viewBox="0 0 18 18" width="18" height="18" aria-hidden="true" focusable="false"><path d="M2 4H16M2 9H16M2 14H16" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round"/><circle cx="6" cy="4" r="1.7" fill="currentColor"/><circle cx="11.5" cy="9" r="1.7" fill="currentColor"/><circle cx="8" cy="14" r="1.7" fill="currentColor"/></svg> Feed
          </button>
        </nav>
      <section v-if="liveFlowSpace === 'feed'" class="content live-flow-feed-content">
        <div class="section-heading">

          <div>
            <span class="eyebrow">LIVE FLOW</span>
            <h2>From people you follow</h2>
          </div>

          <button class="ghost-btn" type="button" @click="liveFlowSpace = 'overview'">
            Back to Live Flow →
          </button>

        </div>

        <div class="feed-layout">

          <div class="feed">

            <article
              v-for="post in filteredPosts"
              :key="post.id"
              class="post-card"
            >

              <div class="post-head">

                <button
                  class="avatar-button"
                  type="button"
                  @click="post.page ? openPageByName(post.page) : openPerson(people.find(person => person.name === post.author) || { name: post.author, username: post.handle, avatar: post.avatar, reason: 'From the Live Flow', mutual: 0, followed: false })"
                >
                  <span class="avatar blue">{{ post.avatar }}</span>
                </button>

                <button
                  class="post-author post-author-button"
                  type="button"
                  @click="post.page ? openPageByName(post.page) : openPerson(people.find(person => person.name === post.author) || { name: post.author, username: post.handle, avatar: post.avatar, reason: 'From the Live Flow', mutual: 0, followed: false })"
                >
                  <strong>{{ post.author }}</strong>
                  <span>
                    {{ post.handle }}
                    <i>•</i>
                    {{ post.time }}
                  </span>
                </button>

                <button class="more">•••</button>

              </div>

              <p class="post-content">
                {{ post.content }}
              </p>

              <div
                v-if="post.zone"
                class="post-zone"
                @click="
                  openZone(
                    zones.find(z => z.name === post.zone) || zones[0]
                  )
                "
              >
                <span>◉</span>
                {{ post.zone }}
              </div>

              <div class="post-inspiration">
                <div class="post-inspiration-heading">
                  <span class="eyebrow">GET INSPIRED</span>
                  <strong>What could this become?</strong>
                </div>
                <div class="post-inspiration-grid">
                  <button
                    v-for="inspiration in getPostInspirations(post)"
                    :key="inspiration.label"
                    type="button"
                    class="post-inspiration-card"
                    @click="openCreateChoice('call')"
                  >
                    <span>{{ inspiration.label }}</span>
                    <strong>{{ inspiration.title }}</strong>
                    <small>{{ inspiration.text }}</small>
                  </button>
                </div>
              </div>

              <div class="post-actions">

                <button
                  :class="{ liked: post.liked }"
                  @click="likePost(post)"
                >
                  ♡ {{ post.likes }}
                </button>

                <button>
                  ◌ {{ post.comments }}
                </button>

                <button>
                  ↗ Share
                </button>

                <button class="save">
                  ♢
                </button>

              </div>

            </article>

          </div>

