          <div
            v-for="person in people"
            :key="person.id"
            class="person-card"
          >

            <div class="person-card-top">

              <div class="large-avatar purple">
                {{ person.avatar }}
              </div>

              <span class="connection-score">
                {{ person.mutual }} shared
              </span>

            </div>

            <h3>{{ person.name }}</h3>
            <span class="username">{{ person.username }}</span>

