  top: 0;
  bottom: 0;
  left: 0;
  z-index: 20;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 3px 9px 30px;
  cursor: pointer;
}

.brand strong {
  display: block;
