  font-size: 8px;
  letter-spacing: .1em;
}

.brand-orbit {
  width: 34px;
  height: 34px;
  border: 1px solid #51678d;
  border-radius: 50%;
  position: relative;
}

.brand-orbit::before,
.brand-orbit::after {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1px solid rgba(99, 143, 219, .55);
  border-radius: 50%;
}

.brand-orbit span {
  width: 7px;
  height: 7px;
  position: absolute;
  top: -3px;
  right: 4px;
  background: #67a4ff;
  border-radius: 50%;
  box-shadow: 0 0 12px rgba(103,164,255,.7);
}

/* Blue signal extends from the orbit into the Anfas wordmark, making them one identity */
.brand-orbit span::after {
  content: "";
  position: absolute;
  width: 36px;
  height: 1px;
  left: 5px;
  top: 5px;
  transform: none;
  transform-origin: left center;
  background: linear-gradient(90deg, rgba(103,164,255,.9), rgba(103,164,255,.65) 45%, rgba(220,230,244,.08));
  box-shadow: 0 0 5px rgba(103,164,255,.28);
}

.main-nav {
