.idea-flow-card-meta span{padding:5px 7px;border:1px solid rgba(255,255,255,.065);border-radius:5px;background:rgba(255,255,255,.025);color:var(--idea-accent);font-size:7px;font-weight:850;letter-spacing:.1em}
