@media(max-width:650px){.live-flow-idea-entry{align-items:flex-start;flex-direction:column;padding:18px}}


.impact-section-line {
  height: 1px;
  margin: 4px 13px 7px;
  background: rgba(255,255,255,.08);
}

.impact-subnav-line {
  position: relative;
}

.impact-subnav-line::after {
  content: '';
  display: block;
  height: 1px;
  margin: 5px 13px 2px;
  background: rgba(255,255,255,.06);
}

/* Subtle animated Zone navigation */
.zone-space-button{display:flex;align-items:center;gap:7px;width:100%;min-height:28px;padding:4px 9px;border:1px solid transparent;border-radius:7px;background:transparent;color:#77869a;font-size:7px;font-weight:700;text-align:left;cursor:pointer;transition:.2s ease}
.zone-space-button:hover,.zone-space-button.active{background:rgba(74,120,194,.045);color:#a9bdd5}
.zone-space-button.active{border-color:rgba(103,164,255,.09)}
.zone-orbit{position:relative;flex:0 0 auto;width:16px;height:16px;border-radius:50%}
.zone-orbit-large{width:20px;height:20px}.zone-orbit-small{width:15.5px;height:12px;border-radius:50%/42%}
.zone-orbit-core{position:absolute;left:50%;top:50%;width:3px;height:3px;margin:-1.5px;border-radius:50%;background:#8fbdf0}
.zone-orbit-ring{position:absolute;inset:2px;border:1px solid rgba(128,171,224,.16);border-radius:50%}
.zone-orbit-ring-two,.zone-orbit-node-two{display:none}
.zone-space-button-around .zone-orbit::before,
.zone-space-button-around .zone-orbit::after,
.zone-space-button-mine .zone-orbit::before,
.zone-space-button-mine .zone-orbit::after{content:'';position:absolute;left:50%;top:50%;width:28px;height:1px;background:linear-gradient(90deg,transparent,rgba(126,184,255,.28),rgba(126,184,255,.55),rgba(126,184,255,.28),transparent);transform-origin:center;pointer-events:none}
.zone-space-button-around .zone-orbit::before,
.zone-space-button-mine .zone-orbit::before{transform:translate(-50%,-50%) rotate(28deg)}
.zone-space-button-around .zone-orbit::after,
.zone-space-button-mine .zone-orbit::after{display:none}
.zone-space-button-around .zone-orbit{overflow:visible}
.zone-space-button-around .zone-orbit-ring-one{display:block;inset:2px;border:1px solid rgba(126,184,255,.12);border-radius:50%;box-shadow:0 0 4px rgba(126,184,255,.04)}
.zone-space-button-around.active .zone-orbit-ring-one{display:block;border-color:rgba(255,212,90,.78);box-shadow:0 0 8px rgba(255,212,90,.18)}
.zone-space-button-around .zone-orbit::before,
.zone-space-button-around .zone-orbit::after{background:linear-gradient(90deg,transparent,rgba(255,212,90,.22),rgba(255,212,90,.5),rgba(255,212,90,.22),transparent)}
.zone-space-button-mine .zone-orbit::before,
.zone-space-button-mine .zone-orbit::after{background:linear-gradient(90deg,transparent,rgba(103,164,255,.2),rgba(255,212,90,.45),rgba(103,164,255,.2),transparent)}
.zone-orbit-node-one{position:absolute;width:3px;height:3px;left:2px;top:2px;border-radius:50%;background:#ffd45a;box-shadow:0 0 7px rgba(255,212,90,.45)}
.zone-space-button.active .zone-orbit-ring-one{display:none}
.zone-space-button-around .zone-orbit-node-one{background:#6fa8ff;box-shadow:0 0 7px rgba(111,168,255,.5);animation-duration:3.64s}\n.zone-space-button-mine .zone-orbit-node-one{background:#6fa8ff;box-shadow:0 0 7px rgba(111,168,255,.5)}
.zone-space-button-around .zone-orbit-node-two{display:none}

/* Zones Around — richer, restrained purple space background */
.zone-space-button-around{
  position:relative;
  isolation:isolate;
  overflow:hidden;
  border-color:rgba(181,108,255,.13);
  background:
    radial-gradient(ellipse at 8% 50%,rgba(181,108,255,.16),transparent 54%),
    linear-gradient(105deg,rgba(91,57,139,.15),rgba(26,31,54,.2) 58%,rgba(15,22,38,.12));
}
.zone-space-button-around::before{
  content:'';
  position:absolute;
  inset:1px;
  z-index:-1;
  border-radius:6px;
  background:linear-gradient(115deg,rgba(181,108,255,.035),transparent 48%,rgba(103,164,255,.035));
  pointer-events:none;
}
.zone-space-button-around:hover{
  border-color:rgba(181,108,255,.3);
  background:
    radial-gradient(ellipse at 8% 50%,rgba(181,108,255,.22),transparent 58%),
    linear-gradient(105deg,rgba(91,57,139,.22),rgba(26,31,54,.27) 58%,rgba(15,22,38,.18));
  color:#e4d1ff;
}
.zone-space-button-around.active{
  border-color:rgba(181,108,255,.34);
  background:
    radial-gradient(ellipse at 10% 50%,rgba(181,108,255,.25),transparent 60%),
    linear-gradient(105deg,rgba(92,54,143,.27),rgba(37,35,66,.34) 62%,rgba(17,24,42,.24));
  color:#f0e4ff;
  box-shadow:inset 2px 0 0 rgba(181,108,255,.8),0 0 14px rgba(133,79,196,.06);
}
.zone-space-button-around .zone-orbit-core{background:#c49aff;box-shadow:0 0 6px rgba(181,108,255,.35)}
.zone-space-button-around .zone-orbit-ring-one{border-color:rgba(181,108,255,.32)}
.zone-space-button-around.active .zone-orbit-ring-one{border-color:rgba(207,164,255,.85);box-shadow:0 0 8px rgba(181,108,255,.2)}

.zone-space-button-around::after{content:'';position:absolute;width:3px;height:3px;left:19px;top:8px;border-radius:50%;background:#9b7bea;box-shadow:0 0 7px rgba(155,123,234,.5);animation:zone-orbit-node-three 4s linear infinite;transform-origin:-5px 2px}
.zone-space-button.active .zone-orbit-node-one{animation:zone-orbit-node 2.8s linear infinite;transform-origin:6px 6px}
.zone-space-button-mine.active .zone-orbit-ring-one{animation-duration:5s;transform:rotate(-18deg)}
.zone-space-button-mine.active .zone-orbit-node-one{width:2px;height:2px;animation-duration:4s;transform-origin:5px 5px}

/* The two Zone spaces react to each other */
.zone-space-button-around.active ~ .impact-subnav-line .zone-space-button-mine .zone-orbit-ring-one,
.zone-space-button-around.active ~ .impact-subnav-line .zone-space-button-mine .zone-orbit-node-one,
.zone-space-button-mine.active ~ .impact-subnav-line .zone-space-button-around .zone-orbit-ring-one,
.zone-space-button-mine.active ~ .impact-subnav-line .zone-space-button-around .zone-orbit-node-one{animation-play-state:running}

.zone-space-button-around.active .zone-orbit-core{animation:none;transform:scale(1.1)}
.zone-space-button-mine.active .zone-orbit-core{animation:zone-core-mine 3.4s ease-in-out infinite;transform:scale(1.1)}
.zone-space-button-mine.active .zone-orbit-ring-one{display:block;inset:1px;border:1px solid rgba(143,189,240,.7);border-radius:50%;box-shadow:0 0 7px rgba(143,189,240,.16);animation:none;transform:rotate(-18deg)}

@keyframes zone-core-around{0%,100%{transform:scale(1)}50%{transform:scale(1.45)}}
@keyframes zone-core-mine{0%,100%{transform:scale(1)}50%{transform:scale(1.25)}}
@keyframes zone-mine-yellow-ring{0%{opacity:.58;border-color:rgba(143,189,240,.7);box-shadow:0 0 7px rgba(143,189,240,.16);transform:rotate(-18deg) scale(.96)}48%{opacity:1;border-color:rgba(255,212,90,.82);box-shadow:0 0 9px rgba(255,212,90,.22);transform:rotate(12deg) scale(1.04)}100%{opacity:.62;border-color:rgba(103,164,255,.78);box-shadow:0 0 8px rgba(103,164,255,.18);transform:rotate(42deg) scale(.98)}}
@keyframes impact-red-orb-travel{0%{left:5%;top:18%;opacity:.35;transform:scale(.8)}20%{left:34%;top:10%;opacity:.9;transform:scale(1)}43%{left:82%;top:28%;opacity:.55;transform:scale(.9)}66%{left:58%;top:64%;opacity:.9;transform:scale(1.05)}84%{left:16%;top:82%;opacity:.45;transform:scale(.82)}100%{left:5%;top:18%;opacity:.35;transform:scale(.8)}}
@keyframes zone-orbit-spin{to{transform:rotate(360deg)}}
@keyframes zone-orbit-node{from{transform:rotate(0deg) translateX(5px)}to{transform:rotate(360deg) translateX(5px)}}
@keyframes zone-orbit-node-two{from{transform:rotate(0deg) translateX(6px)}to{transform:rotate(360deg) translateX(6px)}}
@keyframes zone-orbit-node-three{from{transform:rotate(0deg) translateX(4px)}to{transform:rotate(360deg) translateX(4px)}}
@media(prefers-reduced-motion:reduce){
  .impact-red-orb{animation:none}
.zone-space-button.active .zone-orbit-ring-one,.zone-space-button.active .zone-orbit-node-one,.zone-space-button.active .zone-orbit-core{animation:none}}

