.live-moving-location-filters{position:relative;z-index:1;margin:13px 0 0}
.live-moving-type-filters{position:relative;z-index:1;display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:9px 0 12px}
.live-moving-filter-label{margin-right:2px;color:#6f839d;font-size:7px;font-weight:800;letter-spacing:.12em}
.live-moving-type-filter{padding:6px 9px;border:1px solid rgba(255,255,255,.08);border-radius:20px;background:rgba(255,255,255,.025);color:#a6b6ca;font-size:8px;font-weight:700;cursor:pointer;transition:background .18s,border-color .18s,color .18s}
.live-moving-type-filter:hover,.live-moving-type-filter.active{border-color:rgba(105,174,231,.42);background:rgba(61,131,190,.18);color:#e5f2ff}
.live-moving-result-count{margin-left:auto;color:#71839a;font-size:8px}
.live-moving-empty-state{display:flex;flex-direction:column;gap:5px;padding:18px;border:1px dashed rgba(135,165,205,.22);border-radius:12px;color:#aabbd0;font-size:11px}
.live-moving-empty-state span{color:#71839a;font-size:9px}

.live-network-identity-event{position:relative;overflow:hidden;border-color:color-mix(in srgb,var(--entity-color) 25%,rgba(255,255,255,.05));background:linear-gradient(100deg,color-mix(in srgb,var(--entity-color) 7%,rgba(255,255,255,.018)),rgba(255,255,255,.018) 62%);animation:liveEntityDrift 8s ease-in-out var(--entity-delay,0s) infinite}
.live-network-identity-event:before{content:"";position:absolute;left:0;top:13px;bottom:13px;width:2px;border-radius:0 3px 3px 0;background:var(--entity-color);opacity:.9;box-shadow:0 0 12px color-mix(in srgb,var(--entity-color) 35%,transparent)}
.live-network-identity-event .live-network-event-icon{background:color-mix(in srgb,var(--entity-color) 15%,rgba(12,20,33,.9));color:var(--entity-color);border:1px solid color-mix(in srgb,var(--entity-color) 30%,transparent);box-shadow:inset 0 0 14px color-mix(in srgb,var(--entity-color) 7%,transparent)}
.live-network-identity-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}
.live-network-identity-event .live-network-event-type{color:var(--entity-color);font-size:7px;font-weight:800}
.live-network-entity-mark{display:inline-flex;align-items:center;gap:4px;color:#71839a;font-size:6px;letter-spacing:.1em}
.live-network-entity-mark i{width:4px;height:4px;border-radius:50%;background:var(--entity-color);opacity:.9}
.live-network-identity-event .live-network-entity-name{color:var(--entity-color);font-weight:800;letter-spacing:-.01em}
.live-network-identity-event .live-network-event-body small{color:#8293a9}
.live-moving-chat-toolbar{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:12px}
.live-moving-chat-status{display:inline-flex;align-items:center;gap:7px;color:#8ba0b9;font-size:8px}
.live-moving-chat-status i{width:6px;height:6px;border-radius:50%;background:#68dcb3;box-shadow:0 0 0 3px rgba(104,220,179,.1)}
.live-moving-stream-toggle{border:1px solid rgba(255,255,255,.1);border-radius:18px;background:rgba(255,255,255,.035);color:#a9bad0;padding:6px 9px;font-size:8px;cursor:pointer}
.live-moving-chat-message{width:100%;text-align:left;align-items:flex-start;position:relative;cursor:pointer;transition:border-color .18s,background .18s,transform .18s}
.live-moving-chat-message:hover{border-color:color-mix(in srgb,var(--entity-color) 55%,rgba(255,255,255,.12));transform:translateY(-1px);background:linear-gradient(100deg,color-mix(in srgb,var(--entity-color) 12%,rgba(255,255,255,.025)),rgba(255,255,255,.025) 70%)}
.live-moving-chat-message-new{animation:liveMovingMessageIn .45s ease-out both}
.live-moving-chat-avatar{width:31px;height:31px;flex:0 0 31px;display:grid;place-items:center;border-radius:10px;color:var(--entity-color);background:color-mix(in srgb,var(--entity-color) 13%,rgba(10,18,30,.95));border:1px solid color-mix(in srgb,var(--entity-color) 35%,transparent);font-size:14px}
.live-moving-chat-message .live-network-event-body{flex:1}
.live-moving-chat-open{align-self:center;color:var(--entity-color);font-size:15px;opacity:.65}
.live-moving-chat-message:hover .live-moving-chat-open{opacity:1}
.live-moving-chat-overlay{position:fixed;inset:0;z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(3,8,16,.76);backdrop-filter:blur(12px)}
.live-moving-chat-dialog{width:min(560px,100%);max-height:min(760px,90vh);display:flex;flex-direction:column;overflow:hidden;border:1px solid color-mix(in srgb,var(--entity-color) 30%,rgba(255,255,255,.12));border-radius:18px;background:linear-gradient(150deg,rgba(17,28,44,.99),rgba(8,14,24,.99));box-shadow:0 28px 100px rgba(0,0,0,.45)}
.live-moving-chat-dialog-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px;border-bottom:1px solid rgba(255,255,255,.07)}
.live-moving-chat-dialog-identity{display:flex;align-items:center;gap:11px;min-width:0}
.live-moving-chat-dialog-identity small{color:var(--entity-color);font-size:8px;font-weight:800;letter-spacing:.07em;text-transform:uppercase}
.live-moving-chat-dialog-identity h2{margin:4px 0 0;color:#edf4ff;font-size:16px;overflow-wrap:anywhere}
.live-moving-chat-close{width:32px;height:32px;border:1px solid rgba(255,255,255,.1);border-radius:50%;background:rgba(255,255,255,.04);color:#dce7f5;font-size:21px;cursor:pointer}
.live-moving-chat-thread{display:flex;flex-direction:column;gap:12px;overflow:auto;padding:18px;min-height:190px}
.live-moving-chat-day{align-self:center;color:#71839a;font-size:8px;font-weight:800;letter-spacing:.14em}
.live-moving-chat-bubble{align-self:flex-start;max-width:90%;padding:12px 14px;border:1px solid color-mix(in srgb,var(--entity-color) 22%,rgba(255,255,255,.06));border-radius:4px 14px 14px 14px;background:color-mix(in srgb,var(--entity-color) 7%,rgba(255,255,255,.025))}
.live-moving-chat-bubble-author{color:var(--entity-color);font-size:9px;font-weight:800}
.live-moving-chat-bubble p{margin:7px 0;color:#e1eaf7;font-size:12px;line-height:1.6;overflow-wrap:anywhere}
.live-moving-chat-bubble small{color:#8293a9;font-size:8px;line-height:1.5}
.live-moving-chat-bubble-own{align-self:flex-end;border-color:rgba(106,163,226,.24);border-radius:14px 4px 14px 14px;background:rgba(64,112,164,.13)}
.live-moving-chat-bubble-own .live-moving-chat-bubble-author{color:#9ccaff}
.live-moving-chat-hint{padding:10px 12px;border:1px dashed rgba(255,255,255,.09);border-radius:10px;color:#8192a8;font-size:10px;line-height:1.6}
.live-moving-chat-compose{display:flex;gap:8px;padding:12px 14px;border-top:1px solid rgba(255,255,255,.07)}
.live-moving-chat-compose input{min-width:0;flex:1;border:1px solid rgba(255,255,255,.1);border-radius:22px;outline:none;background:rgba(255,255,255,.04);padding:11px 14px;color:#eaf2ff;font-size:11px}
.live-moving-chat-compose input:focus{border-color:color-mix(in srgb,var(--entity-color) 55%,rgba(255,255,255,.1))}
.live-moving-chat-compose button{width:38px;height:38px;border:0;border-radius:50%;background:var(--entity-color);color:#091321;font-size:16px;cursor:pointer}
.live-moving-chat-compose button:disabled{opacity:.35;cursor:not-allowed}
.live-moving-chat-demo-note{margin:0;padding:0 16px 13px;color:#6f829a;font-size:8px;text-align:center}
@keyframes liveMovingMessageIn{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:640px){.live-moving-chat-overlay{padding:10px}.live-moving-chat-dialog{max-height:94vh}.live-moving-chat-dialog-head{padding:14px}.live-moving-chat-thread{padding:14px}.live-moving-chat-toolbar{align-items:flex-start;flex-direction:column}}
@media(prefers-reduced-motion:reduce){.live-moving-chat-message-new{animation:none}.live-moving-chat-message{transition:none}}

@keyframes liveMovingPulse{0%,100%{opacity:.65;transform:scale(.88)}50%{opacity:1;transform:scale(1.12)}}
@keyframes liveEntityDrift{0%,100%{transform:translateX(0)}50%{transform:translateX(2px)}}
@media(prefers-reduced-motion:reduce){.live-moving-pulse i,.live-network-identity-event{animation:none}}

.live-network-side{display:flex;flex-direction:column;gap:10px;position:sticky;top:16px}
.live-network-summary{padding:17px;border:1px solid rgba(255,255,255,.07);border-radius:13px;background:rgba(255,255,255,.025)}
.live-network-summary strong{display:block;margin:7px 0;color:#edf2f8;font-size:15px}
.live-network-summary p{margin:0;color:#8794a7;font-size:10px;line-height:1.6}
.live-network-stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:15px}
.live-network-stats div{padding-top:9px;border-top:1px solid rgba(255,255,255,.07)}
.live-network-stats strong{margin:0;font-size:16px}
.live-network-stats span{display:block;margin-top:3px;color:#718096;font-size:7px}
.live-network-stat-detail{display:block;margin-top:4px;font-size:7px;line-height:1.35;font-weight:600;letter-spacing:.02em}
.live-network-stat-detail.stat-sparks{color:#9aaab5}
.live-network-stat-detail.stat-explore{color:#a19faa}
.live-network-stat-detail.stat-opportunities{color:#a99aa4}
.live-network-stat-detail.stat-needs{color:#aaa28f}

@media(max-width:900px){.live-network-layout{grid-template-columns:1fr}.live-network-side{position:static}}

/* LIVE ENGAGEMENT DESTINATIONS */
.live-engagement-content{max-width:1120px}
.live-engagement-back{margin-bottom:18px}
.live-engagement-hero{display:flex;align-items:flex-end;justify-content:space-between;gap:28px;padding:4px 0 22px;border-bottom:1px solid rgba(255,255,255,.06)}
.live-engagement-hero h1{margin:7px 0 8px;color:#edf3fb;font-size:32px;line-height:1.08}
.live-engagement-hero h1 span{color:#7fa9dc}
.live-engagement-hero p{max-width:650px;margin:0;color:#748297;font-size:10px;line-height:1.7}
.live-engagement-signal{min-width:150px;padding:13px 15px;border:1px solid rgba(103,164,255,.13);border-radius:12px;background:rgba(74,120,194,.045);text-align:right}
.live-engagement-signal strong{display:block;color:#b9d2ef;font-size:12px}.live-engagement-signal small{display:block;margin-top:4px;color:#627188;font-size:7px}.live-signal-dot{display:inline-block;width:6px;height:6px;margin-right:5px;border-radius:50%;background:#75b8e8;box-shadow:0 0 9px rgba(117,184,232,.6)}
.live-engagement-grid{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:14px;margin-top:16px}
.live-conversation-card,.live-context-card,.forming-action-card{border:1px solid rgba(255,255,255,.065);border-radius:14px;background:linear-gradient(145deg,rgba(24,32,45,.7),rgba(10,15,23,.9));box-shadow:0 16px 35px rgba(0,0,0,.16)}
.live-conversation-card{padding:19px}.live-card-top{display:flex;justify-content:space-between;gap:12px}.live-card-status{color:#78aeda;font-size:6px;font-weight:800;letter-spacing:.12em}.live-conversation-card h2,.forming-action-card h2{margin:10px 0 8px;color:#e8f0fa;font-size:19px;line-height:1.3}.live-conversation-card>p,.forming-action-main>p{color:#758398;font-size:9px;line-height:1.6}
.conversation-preview{display:grid;gap:8px;margin:16px 0}.conversation-message{display:grid;grid-template-columns:27px 1fr;gap:8px;padding:9px;border:1px solid rgba(255,255,255,.045);border-radius:9px;background:rgba(255,255,255,.018)}.conversation-avatar{width:27px;height:27px;display:grid;place-items:center;border-radius:8px;background:rgba(74,120,194,.16);color:#9dc3ec;font-size:6px;font-weight:800}.conversation-avatar.purple{background:rgba(130,104,191,.16);color:#baa6e8}.conversation-message strong{color:#a9bdd5;font-size:7px}.conversation-message p{margin:3px 0;color:#6d7b8f;font-size:7px;line-height:1.45}.conversation-message small{color:#4f5d70;font-size:5px}.live-card-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.live-card-actions .primary-btn,.live-card-actions .ghost-btn{font-size:7px}
.live-context-card{padding:17px;height:max-content}.live-context-row{display:flex;justify-content:space-between;gap:10px;padding:12px 0;border-bottom:1px solid rgba(255,255,255,.045)}.live-context-row:last-child{border-bottom:0}.live-context-row span{color:#56657a;font-size:6px}.live-context-row strong{color:#aabed6;font-size:7px;text-align:right}
.forming-action-card{display:grid;grid-template-columns:minmax(0,1fr) 230px;margin-top:16px;overflow:hidden}.forming-action-main{padding:22px}.action-path{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:18px;color:#759bc7;font-size:6px;font-weight:800;letter-spacing:.1em}.action-path span{padding:6px 8px;border:1px solid rgba(103,164,255,.1);border-radius:6px;background:rgba(74,120,194,.035)}.action-path i{color:#4d6079;font-style:normal}.forming-action-side{display:grid;align-content:start;gap:0;padding:19px;border-left:1px solid rgba(255,255,255,.055);background:rgba(255,255,255,.012)}.forming-action-side div{padding:10px 0;border-bottom:1px solid rgba(255,255,255,.045)}.forming-action-side strong{display:block;color:#d2deed;font-size:17px}.forming-action-side span{display:block;margin-top:2px;color:#5d6d82;font-size:6px}.forming-action-side .follow-btn{margin-top:14px}
.network-flow-stage{display:flex;align-items:center;justify-content:center;gap:12px;margin-top:18px;padding:28px 18px;border:1px solid rgba(255,255,255,.06);border-radius:14px;background:radial-gradient(circle at center,rgba(54,83,124,.09),rgba(8,13,21,.65) 62%);overflow:auto}.flow-column{display:grid;gap:7px;min-width:105px}.flow-label{margin-bottom:2px;color:#56677d;font-size:6px;font-weight:800;letter-spacing:.13em;text-align:center}.flow-node{padding:9px 8px;border:1px solid rgba(255,255,255,.055);border-radius:8px;background:rgba(255,255,255,.018);color:#8495aa;font-size:7px;text-align:center;white-space:nowrap;animation:live-flow-node 3.2s ease-in-out infinite}.flow-node.highlighted{border-color:rgba(103,164,255,.16);background:rgba(74,120,194,.07);color:#a9c8ea}.flow-arrow{color:#506782;font-size:16px;animation:live-flow-arrow 2.2s ease-in-out infinite}.flow-footer{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.flow-footer>div{padding:13px 15px;border:1px solid rgba(255,255,255,.05);border-radius:10px;background:rgba(255,255,255,.015)}.flow-footer span{display:block;color:#56677d;font-size:5px;font-weight:800;letter-spacing:.12em}.flow-footer strong{display:block;margin-top:5px;color:#9badc2;font-size:8px;font-weight:600}.flow-signal{min-width:180px}
@keyframes live-flow-node{0%,100%{transform:translateY(0);opacity:.82}50%{transform:translateY(-2px);opacity:1}}@keyframes live-flow-arrow{0%,100%{opacity:.4;transform:translateX(0)}50%{opacity:1;transform:translateX(3px)}}
@media(max-width:800px){.live-engagement-hero{align-items:flex-start;flex-direction:column}.live-engagement-signal{width:100%;text-align:left}.live-engagement-grid,.forming-action-card{grid-template-columns:1fr}.forming-action-side{border-left:0;border-top:1px solid rgba(255,255,255,.055)}.network-flow-stage{justify-content:flex-start}.flow-footer{grid-template-columns:1fr}}

/* Compact Your Zones connection filter */
.my-zones-filter-row{
  display:flex;
  align-items:center;
  gap:8px;
  margin:10px 0 12px;
}
.my-zones-filter{
  display:flex;
  align-items:center;
  gap:7px;
  padding:4px 7px;
  border:1px solid rgba(255,255,255,.07);
  border-radius:7px;
  background:rgba(255,255,255,.018);
}
.my-zones-filter span{
  color:#66768b;
  font-size:5px;
  font-weight:800;
  letter-spacing:.12em;
  white-space:nowrap;
}
.my-zones-filter select{
  max-width:145px;
  padding:3px 20px 3px 4px;
  border:0;
  outline:0;
  border-radius:4px;
  background:#111a27;
  color:#9eb2ca;
  font-size:7px;
  font-weight:700;
  cursor:pointer;
}
.my-zones-filter select:focus{box-shadow:0 0 0 1px rgba(103,164,255,.25)}
.my-zones-filter-count{
  color:#56677d;
  font-size:6px;
  font-weight:700;
  letter-spacing:.06em;
}
.my-zones-filter-empty{margin-top:12px}
@media(max-width:600px){
  .my-zones-filter-row{margin-top:8px}
  .my-zones-filter{max-width:100%}
  .my-zones-filter select{max-width:125px}
}


.my-zone-connection{
  display:flex;
  align-items:center;
  gap:5px;
  margin-top:4px;
  color:#7f94ad;
  font-size:6px;
  font-weight:700;
  letter-spacing:.07em;
  text-transform:uppercase;
}
.my-zone-connection-dot{
  color:#79aef0;
  font-size:5px;
  text-shadow:0 0 6px rgba(121,174,240,.35);
}

/* Zones Around: join control lives on the image */
.zone-around-card{overflow:hidden}
.zone-around-image{position:relative;min-height:150px;background-position:center;background-size:cover;background-repeat:no-repeat}
.zone-around-image-overlay{position:absolute;inset:0;background:linear-gradient(180deg,rgba(4,8,15,.2),rgba(4,8,15,.68))}
.zone-around-image-location{position:absolute;left:12px;bottom:10px;z-index:1;color:#d7e2f0;font-size:7px;font-weight:700;letter-spacing:.05em;text-shadow:0 1px 8px rgba(0,0,0,.55)}
.zone-around-join-btn{position:absolute;top:10px;right:10px;z-index:2}
.zone-around-join-btn.following{border-color:rgba(103,164,255,.24);background:rgba(7,14,24,.72);color:#a9c9ec}
.zone-around-card-body{padding:13px 14px 14px}
.zone-around-joined-note{color:#79aef0!important;font-size:6px!important;font-weight:800!important;letter-spacing:.08em}


.community-signal-list{
  display:flex;
  flex-wrap:wrap;
  gap:4px;
  margin-top:7px;
}
.community-signal-list.compact{margin-top:4px}
.community-signal-list.detail{margin-top:8px}
.community-signal{
  display:inline-flex;
  align-items:center;
  gap:4px;
  padding:3px 6px;
  border:1px solid rgba(255,255,255,.08);
  border-radius:999px;
  background:rgba(7,14,24,.58);
  white-space:nowrap;
}
.community-signal{
  cursor:pointer;
}
.community-signal b{
  font-size:5px;
  font-weight:900;
  letter-spacing:.07em;
}
.community-signal:hover{background:rgba(12,24,40,.82);transform:translateY(-1px)}
.signal-evidence{
  display:grid;
  gap:7px;
  margin-top:6px;
  padding:8px;
  border:1px solid rgba(121,174,240,.1);
  border-radius:8px;
  background:rgba(5,11,19,.55);
}
.signal-evidence-head{display:grid;gap:2px}
.signal-evidence-head span{color:#7189a4;font-size:5px;font-weight:900;letter-spacing:.12em}
.signal-evidence-head strong{color:#aebed0;font-size:6px;letter-spacing:.05em}
.signal-evidence-summary{margin:0;color:#f0a45d;font-size:6px;font-weight:800;letter-spacing:.04em}
.signal-evidence-flow{display:flex;align-items:center;gap:5px;flex-wrap:wrap;color:#7d91a9;font-size:6px;line-height:1.4}
.signal-evidence-flow span{padding:4px 5px;border:1px solid rgba(255,255,255,.06);border-radius:5px;background:rgba(255,255,255,.018)}
.signal-evidence-flow i{color:#f0a45d;font-style:normal}
.signal-evidence-list{display:grid;gap:5px}
.signal-evidence-item{padding:6px;border-left:2px solid rgba(240,164,93,.35);background:rgba(255,255,255,.015)}
.signal-evidence-source{display:block;color:#8da5c1;font-size:5px;font-weight:900;letter-spacing:.07em}
.signal-evidence-item p{margin:3px 0;color:#aab8c9;font-size:6px;line-height:1.45}
.signal-evidence-item small{color:#6d8096;font-size:5px}
.signal-evidence-note{color:#596b80;font-size:5px;line-height:1.45}
.community-signal small{
  color:#687a90;
  font-size:5px;
  font-weight:700;
}
.community-signal.signal-reported{border-color:rgba(240,109,97,.24)}
.community-signal.signal-reported b{color:#f06d61}
.community-signal.signal-attention{border-color:rgba(240,164,93,.28)}
.community-signal.signal-attention b{color:#f0a45d}
.community-signal.signal-impact{border-color:rgba(121,199,161,.24)}
.community-signal.signal-impact b{color:#79c7a1}
.community-signal.signal-confirmed{border-color:rgba(121,174,240,.16)}
.community-signal.signal-confirmed b{color:#7896b7}
/* Impacting: governorate Join action appears after opening the governorate */
.governorate-detail-cover{position:relative}
.governorate-detail-join-stack{position:absolute;top:14px;right:14px;z-index:5;display:flex;flex-direction:column;align-items:center;gap:4px}
.governorate-detail-joined-count{display:inline-flex;align-items:center;gap:5px;min-height:17px;padding:0 8px;border:1px solid rgba(121,174,240,.28);border-radius:999px;background:rgba(7,16,28,.62);color:#d9e9f8;font-size:6px;font-weight:800;letter-spacing:.04em;text-shadow:0 1px 8px rgba(0,0,0,.65);white-space:nowrap;box-shadow:0 3px 12px rgba(0,0,0,.25),inset 0 1px 0 rgba(255,255,255,.07)}
@keyframes governorate-presence-shift{0%,100%{color:#f0a45d;text-shadow:0 0 7px rgba(240,164,93,.55)}50%{color:#79c7a1;text-shadow:0 0 8px rgba(121,199,161,.62)}}
.governorate-detail-joined-count::before{content:'●';font-size:6px;animation:governorate-presence-shift 3s ease-in-out infinite}
.governorate-detail-image-join{
  position:relative;
  top:auto;
  right:auto;
  z-index:5;
  min-width:92px;
  padding:7px 11px;
  border:1px solid rgba(210,224,244,.32);
  border-radius:7px;
  background:#0a1220;
  color:#eef5ff;
  font-size:7px;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
  cursor:pointer;
  box-shadow:0 6px 18px rgba(0,0,0,.42),0 0 0 1px rgba(0,0,0,.18);
  transition:.2s ease;
}
.governorate-detail-image-join:hover{
  background:#111d2d;
  border-color:rgba(151,190,236,.58);
  color:#ffffff;
  transform:translateY(-1px);
}
.governorate-detail-image-join:active{transform:translateY(0)}
.governorate-detail-image-join.joined{
  border-color:rgba(103,164,255,.42);
  background:#0b1a2b;
  color:#b9d7f7;
}


.join-confirmation{
  position:fixed;
  top:18px;
  left:50%;
  z-index:1000;
  transform:translateX(-50%);
  display:flex;
  align-items:center;
  gap:8px;
  min-width:260px;
  max-width:min(420px,calc(100vw - 28px));
  padding:10px 11px;
  border:1px solid rgba(121,199,161,.28);
  border-radius:9px;
  background:rgba(7,16,28,.94);
  color:#c9d9e9;
  font-size:8px;
  font-weight:700;
  box-shadow:0 10px 30px rgba(0,0,0,.38),0 0 18px rgba(121,199,161,.06);
  backdrop-filter:blur(12px);
  animation:join-confirmation-in .32s cubic-bezier(.2,.8,.2,1);
}
.join-confirmation-flow{
  position:relative;
  width:48px;
  height:24px;
  flex:0 0 48px;
  overflow:visible;
}
.join-confirmation-flow::before{
  content:'';
  position:absolute;
  left:7px;
  right:7px;
  top:50%;
  height:1px;
  background:linear-gradient(90deg,rgba(240,164,93,.18),rgba(121,174,240,.3),rgba(121,199,161,.34));
  transform:translateY(-50%);
}
.join-confirmation-source,
.join-confirmation-destination{
  position:absolute;
  top:50%;
  display:grid;
  place-items:center;
  width:16px;
  height:16px;
  transform:translateY(-50%);
}
.join-confirmation-source{left:0}
.join-confirmation-destination{right:0}
.join-confirmation-source-orbit,
.join-confirmation-destination-orbit{
  position:absolute;
  width:15px;
  height:15px;
  border:1px solid rgba(240,164,93,.45);
  border-radius:50%;
}
.join-confirmation-destination-orbit{
  border-color:rgba(121,199,161,.48);
}
.join-confirmation-source-orbit{
  transform:rotate(22deg) scaleY(.58);
}
.join-confirmation-destination-orbit{
  transform:rotate(-22deg) scaleY(.58);
}
.join-confirmation-source-core,
.join-confirmation-destination-core{
  position:relative;
  z-index:2;
  display:grid;
  place-items:center;
  width:7px;
  height:7px;
  border-radius:50%;
}
.join-confirmation-source-core{
  background:#f0a45d;
  box-shadow:0 0 7px rgba(240,164,93,.55);
}
.join-confirmation-destination-core{
  width:15px;
  height:15px;
  border:1px solid rgba(121,199,161,.35);
  background:rgba(121,199,161,.09);
  color:#79c7a1;
  font-size:8px;
  animation:join-confirmation-destination-pop .45s ease-out;
}
.join-confirmation-travel{
  position:absolute;
  left:4px;
  top:50%;
  width:11px;
  height:11px;
  transform:translateY(-50%);
  animation:join-confirmation-travel 1.05s cubic-bezier(.45,.05,.2,1) both;
}
.join-confirmation-travel-orbit{
  position:absolute;
  inset:0;
  border:1px solid rgba(126,184,255,.72);
  border-radius:50%;
  transform:rotate(24deg) scaleY(.58);
  box-shadow:0 0 7px rgba(126,184,255,.18);
}
.join-confirmation-travel::after{
  content:'';
  position:absolute;
  width:4px;
  height:4px;
  left:3px;
  top:3px;
  border-radius:50%;
  background:#79aef0;
  box-shadow:0 0 7px rgba(121,174,240,.6);
}
.join-confirmation-copy{
  display:grid;
  gap:2px;
  min-width:0;
}
.join-confirmation-copy strong{
  color:#79c7a1;
  font-size:7px;
  letter-spacing:.1em;
}
.join-confirmation-copy span{
  color:#c9d9e9;
  font-size:8px;
  font-weight:600;
}
.join-confirmation-arrow{
  color:#f0a45d;
  font-size:12px;
  animation:join-confirmation-arrow .55s ease-out;
}
.join-confirmation button{
  margin-left:auto;
  padding:0 2px;
  border:0;
  background:transparent;
  color:#617389;
  font-size:13px;
  line-height:1;
  cursor:pointer;
}
.join-confirmation button:hover{color:#aebed0}
@keyframes join-confirmation-in{
  from{opacity:0;transform:translate(-50%,-8px) scale(.96)}
  to{opacity:1;transform:translate(-50%,0) scale(1)}
}
@keyframes join-confirmation-travel{
  0%{left:4px;opacity:0;transform:translateY(-50%) scale(.7)}
  12%{opacity:1}
  72%{opacity:1}
  100%{left:33px;opacity:0;transform:translateY(-50%) scale(1)}
}
@keyframes join-confirmation-destination-pop{
  0%{transform:scale(.72);opacity:.45}
  65%{transform:scale(1.18)}
  100%{transform:scale(1);opacity:1}
}
@keyframes join-confirmation-arrow{
  0%{transform:translateX(-5px);opacity:0}
  100%{transform:translateX(0);opacity:1}
}
@media(prefers-reduced-motion:reduce){
  .join-confirmation,.join-confirmation-travel,.join-confirmation-destination-core,.join-confirmation-arrow{animation:none}
}
@media(max-width:600px){.join-confirmation{top:10px;min-width:0;width:calc(100vw - 20px)}}

/* INITIATIVES */
.initiatives-page{max-width:1180px}
.initiative-hero{position:relative;overflow:hidden}
.initiative-hero .commons-hero-copy{position:relative;z-index:2}
.initiative-hero-orbit{position:absolute;right:54px;top:18px;width:125px;height:125px;border:1px solid rgba(159,143,255,.16);border-radius:50%;opacity:.8}
.initiative-hero-orbit::before{content:'';position:absolute;inset:19px;border:1px solid rgba(115,185,201,.2);border-radius:50%;transform:rotate(28deg) scaleY(.58)}
.initiative-hero-orbit span{position:absolute;width:42px;height:42px;left:41px;top:41px;border:1px solid rgba(159,143,255,.28);border-radius:50%;box-shadow:0 0 28px rgba(159,143,255,.08)}
.initiative-hero-orbit i,.initiative-hero-orbit b,.initiative-hero-orbit em{position:absolute;display:block;border-radius:50%;font-style:normal}
.initiative-hero-orbit i{width:7px;height:7px;left:8px;top:45px;background:#9f8fff;box-shadow:0 0 12px rgba(159,143,255,.42)}
.initiative-hero-orbit b{width:6px;height:6px;right:12px;top:24px;background:#73b9c9}
.initiative-hero-orbit em{width:5px;height:5px;left:28px;bottom:12px;background:#d6d46a}
.home-view-switch{display:flex;justify-content:flex-end;gap:3px;width:max-content;margin:0 0 12px auto;padding:3px;border:1px solid rgba(137,160,190,.14);border-radius:9px;background:rgba(8,14,23,.72)}
.home-view-switch button{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border:1px solid transparent;border-radius:6px;background:transparent;color:#788ba2;font:inherit;font-size:9px;font-weight:800;cursor:pointer;transition:background .18s ease,border-color .18s ease,color .18s ease}
.home-view-switch button span{font-size:12px;line-height:1}
.home-view-switch button:hover{color:#dce8f5}
.home-view-switch button.active{border-color:rgba(115,185,201,.22);background:linear-gradient(110deg,rgba(115,185,201,.13),rgba(159,143,255,.1));color:#d7edf2;box-shadow:inset 0 1px 0 rgba(255,255,255,.035)}
.home-discovery-view,.home-feed-view{min-width:0}
.initiative-home-intro{margin:0 0 10px;padding:14px 16px 4px}
.initiative-home-intro h2{margin:4px 0 6px;color:#e6edf7;font-size:20px;letter-spacing:-.025em}
.initiative-home-intro h2 span{color:#73b9c9}
.initiative-home-intro p{max-width:760px;margin:0;color:#748196;font-size:9px;line-height:1.65}
.initiative-flow-step .initiative-explore-icon{float:right;margin:0 2px 5px 10px}
.initiative-explore-btn{display:inline-flex;align-items:center;gap:8px}
.initiative-explore-icon{position:relative;width:18px;height:18px;display:inline-block;border:1px solid rgba(115,185,201,.3);border-radius:50%;animation:initiative-icon-pulse 3.2s ease-in-out infinite}
.initiative-explore-icon::before{content:'';position:absolute;inset:4px;border:1px solid rgba(159,143,255,.5);border-radius:50%}
.initiative-explore-icon i,.initiative-explore-icon b,.initiative-explore-icon em{position:absolute;display:block;border-radius:50%;font-style:normal}
.initiative-explore-icon i{width:4px;height:4px;left:1px;top:7px;background:#d6d46a;animation:initiative-icon-orbit 2.8s linear infinite}
.initiative-explore-icon b{width:3px;height:3px;right:2px;top:3px;background:#73b9c9}
.initiative-explore-icon em{width:3px;height:3px;left:6px;bottom:1px;background:#9f8fff}
@keyframes initiative-icon-pulse{50%{transform:scale(1.08);opacity:.78}}
@keyframes initiative-icon-orbit{to{transform:rotate(360deg) translateX(6px) rotate(-360deg)}}
.initiative-flow-path{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:0 0 18px}
.initiative-flow-step{position:relative;min-width:0;text-align:left;padding:14px 15px;border:1px solid rgba(255,255,255,.06);border-radius:13px;background:linear-gradient(145deg,rgba(18,27,40,.82),rgba(8,13,21,.9));transition:border-color .25s ease,transform .25s ease,background .25s ease}
.initiative-flow-step:hover,.initiative-flow-step:focus-within{border-color:rgba(115,185,201,.2);background:linear-gradient(145deg,rgba(23,34,49,.9),rgba(9,14,22,.94))}

/* Home cards work as one connected path: explore → impact → what's happening */
.initiative-flow-path{position:relative;isolation:isolate;column-gap:10px}
.initiative-flow-step{z-index:1;overflow:visible;border-color:rgba(115,185,201,.12);box-shadow:inset 0 1px 0 rgba(255,255,255,.018),0 8px 24px rgba(0,0,0,.08)}
.initiative-flow-step::before{content:'';position:absolute;top:0;left:14px;right:14px;height:1px;border-radius:1px;background:linear-gradient(90deg,transparent,var(--home-flow-accent),transparent);opacity:.58;pointer-events:none}
.initiative-flow-step::after{content:'';position:absolute;z-index:2;right:-11px;top:22px;width:11px;height:1px;background:linear-gradient(90deg,var(--home-flow-accent),rgba(159,143,255,.45));pointer-events:none}
.initiative-flow-step:not(.going-around)::after{box-shadow:0 0 5px color-mix(in srgb,var(--home-flow-accent) 45%,transparent)}
.initiative-flow-step.people-do{--home-flow-accent:#73b9c9;background:radial-gradient(ellipse at 0% 0%,rgba(66,164,184,.13),transparent 62%),linear-gradient(145deg,rgba(16,36,47,.91),rgba(8,15,24,.95));border-color:rgba(115,185,201,.2)}
.initiative-flow-step.make-impact{--home-flow-accent:#d6d46a;background:radial-gradient(ellipse at 0% 0%,rgba(170,173,74,.12),transparent 62%),linear-gradient(145deg,rgba(35,36,31,.88),rgba(10,16,24,.95));border-color:rgba(214,212,106,.18)}
.initiative-flow-step.going-around{--home-flow-accent:#9f8fff;background:radial-gradient(ellipse at 0% 0%,rgba(132,95,203,.15),transparent 62%),linear-gradient(145deg,rgba(29,26,47,.9),rgba(9,14,24,.96));border-color:rgba(159,143,255,.2)}
.initiative-flow-step.going-around::after{display:none}
.initiative-flow-step.people-do:hover,.initiative-flow-step.people-do:focus-within{border-color:rgba(115,185,201,.4);background:radial-gradient(ellipse at 0% 0%,rgba(66,164,184,.18),transparent 65%),linear-gradient(145deg,rgba(20,44,55,.94),rgba(9,16,25,.97))}
.initiative-flow-step.make-impact:hover,.initiative-flow-step.make-impact:focus-within{border-color:rgba(214,212,106,.38);background:radial-gradient(ellipse at 0% 0%,rgba(170,173,74,.17),transparent 65%),linear-gradient(145deg,rgba(42,43,35,.93),rgba(10,16,24,.97))}
.initiative-flow-step.going-around:hover,.initiative-flow-step.going-around:focus-within{border-color:rgba(159,143,255,.4);background:radial-gradient(ellipse at 0% 0%,rgba(132,95,203,.2),transparent 65%),linear-gradient(145deg,rgba(35,31,55,.94),rgba(9,14,24,.97))}
@media(max-width:900px){
  .initiative-flow-step::after{display:none}
  .initiative-flow-step::before{left:12px;right:12px}
}

.initiative-flow-kicker{display:block;margin-bottom:6px;font-size:7px;letter-spacing:.16em;font-weight:900}
.initiative-flow-step>strong{display:block;color:#dce6f2;font-size:12px;line-height:1.35}
.initiative-flow-step>small{display:block;margin-top:6px;color:#9aa9bb;font-size:8px;line-height:1.45}
.initiative-example-options{display:flex;flex-wrap:wrap;gap:5px;margin-top:12px}
.initiative-example-options button{padding:6px 8px;border:1px solid rgba(130,164,190,.18);border-radius:7px;background:rgba(255,255,255,.025);color:#b7c7d8;font:inherit;font-size:8px;line-height:1.2;cursor:pointer;transition:background .18s ease,border-color .18s ease,color .18s ease}
.initiative-example-options button:hover,.initiative-example-options button:focus-visible{background:rgba(115,185,201,.12);border-color:rgba(115,185,201,.48);color:#fff;outline:none}
.initiative-card-action{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;margin-top:11px;padding:8px 0 0;border:0;border-top:1px solid rgba(255,255,255,.07);background:transparent;color:#9cc9d6;font:inherit;font-size:9px;font-weight:800;text-align:left;cursor:pointer}
.initiative-card-action:hover,.initiative-card-action:focus-visible{color:#fff;outline:none}
.initiative-card-action span{font-size:14px;transition:transform .18s ease}
.initiative-card-action:hover span{transform:translateX(3px)}
.people-doing-category-list{display:flex;gap:8px;overflow-x:auto;overscroll-behavior-x:contain;margin-top:10px;padding:2px 1px 8px;scroll-snap-type:x proximity;scrollbar-width:thin;scrollbar-color:rgba(115,185,201,.35) transparent}
.people-doing-category{display:flex;flex:0 0 148px;flex-direction:column;align-items:flex-start;min-height:142px;padding:10px;border:1px solid rgba(115,185,201,.16);border-radius:10px;background:linear-gradient(145deg,rgba(115,185,201,.07),rgba(255,255,255,.018));scroll-snap-align:start}
.people-doing-category-type{margin-bottom:7px;color:#73b9c9;font-size:7px;font-weight:850;letter-spacing:.12em}
.people-doing-category strong{color:#dce7f2;font-size:10px;line-height:1.35}
.people-doing-category p{margin:5px 0 10px;color:#8191a5;font-size:8px;line-height:1.5}
.people-doing-category button{display:flex;align-items:center;justify-content:space-between;gap:5px;width:100%;margin-top:auto;padding:7px 0 0;border:0;border-top:1px solid rgba(255,255,255,.07);background:transparent;color:#a9d9e3;font:inherit;font-size:8px;font-weight:800;text-align:left;cursor:pointer}
.people-doing-category button:hover,.people-doing-category button:focus-visible{color:#fff;outline:none}
.people-doing-category button span{font-size:12px}

.people-do .initiative-flow-kicker{color:#73b9c9}
.make-impact .initiative-flow-kicker{color:#d6d46a}
.going-around .initiative-flow-kicker{color:#9f8fff}
.impact-category-picker{grid-column:1/-1;display:flex;flex-direction:column;align-items:center;gap:10px;padding:2px 0 5px}
.impact-category-toggle{display:inline-flex;align-items:center;gap:10px;padding:8px 12px;border:0;border-bottom:1px solid rgba(115,185,201,.35);background:transparent;color:#a8c5d2;font:inherit;font-size:10px;font-weight:750;cursor:pointer;transition:color .18s ease,border-color .18s ease}
.impact-category-toggle:hover,.impact-category-toggle:focus-visible{color:#fff;border-color:#73b9c9;outline:none}
.impact-category-toggle-icon{display:inline-flex;align-items:center;justify-content:center;width:17px;height:17px;border:1px solid rgba(115,185,201,.3);border-radius:50%;font-size:13px;line-height:1}
.impact-category-options{display:flex;justify-content:center;flex-wrap:wrap;gap:7px;max-width:900px;animation:initiative-story-in .2s ease both}
.impact-category-options button{display:inline-flex;align-items:center;gap:7px;padding:8px 10px;border:1px solid rgba(255,255,255,.08);border-radius:9px;background:rgba(17,29,42,.78);color:#c2d0df;font:inherit;font-size:9px;cursor:pointer;transition:background .18s ease,border-color .18s ease,transform .18s ease}
.impact-category-options button:hover,.impact-category-options button:focus-visible{background:rgba(115,185,201,.1);border-color:rgba(115,185,201,.4);color:#fff;transform:translateY(-1px);outline:none}
.impact-category-options button span{font-size:13px}
.initiative-hover-story{grid-column:1/-1;display:none;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;padding:12px;border:1px solid rgba(115,185,201,.14);border-radius:13px;background:linear-gradient(120deg,rgba(17,29,42,.96),rgba(10,16,26,.97));animation:initiative-story-in .22s ease both}
.initiative-flow-path:has(.people-do:hover, .story-people-do:hover) .story-people-do,
.initiative-flow-path:has(.people-do:focus-visible, .story-people-do:focus-within) .story-people-do,
.initiative-flow-path:has(.make-impact:hover, .story-make-impact:hover) .story-make-impact,
.initiative-flow-path:has(.make-impact:focus-visible, .story-make-impact:focus-within) .story-make-impact,
.initiative-flow-path:has(.going-around:hover, .story-going-around:hover) .story-going-around,
.initiative-flow-path:has(.going-around:focus-visible, .story-going-around:focus-within) .story-going-around{display:grid}
.initiative-hover-story-heading{grid-column:1/-1;display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;padding:0 2px 3px}
.initiative-hover-story-heading .initiative-flow-kicker{margin:0;color:#73b9c9}
.initiative-hover-story-heading>strong{color:#dce6f2;font-size:10px}
.initiative-hover-story-step{display:block;width:100%;min-width:0;padding:9px;text-align:left;font:inherit;color:inherit;border:1px solid rgba(255,255,255,.055);border-radius:9px;background:rgba(255,255,255,.018);cursor:pointer;transition:background .18s ease,border-color .18s ease,transform .18s ease}.initiative-hover-story-step:hover,.initiative-hover-story-step:focus-visible{background:rgba(115,185,201,.09);border-color:rgba(115,185,201,.4);transform:translateY(-2px);outline:none}.initiative-step-action{display:block;margin-top:9px;color:#9cc9d6;font-size:8px;font-weight:800;letter-spacing:.04em}.initiative-hover-story-step:focus-visible .initiative-step-action{color:#fff}
.initiative-hover-story-step>span{display:block;margin-bottom:7px;font-size:7px;font-weight:900;letter-spacing:.09em}
.initiative-hover-story-step>strong{display:block;color:#dce6f2;font-size:10px;line-height:1.4}
.initiative-hover-story-step>small{display:block;margin-top:5px;color:#8090a4;font-size:8px;line-height:1.45}
.story-idea>span{color:#e8c66d}.story-people>span{color:#8ec9ff}.story-place>span{color:#a99aff}.story-action>span{color:#e6b36f}.story-impact>span{color:#83d6a5}
@keyframes initiative-story-in{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:translateY(0)}}
@media (max-width:900px){.initiative-flow-path{grid-template-columns:1fr}.initiative-hover-story{grid-template-columns:repeat(2,minmax(0,1fr))}.initiative-hover-story-heading{grid-column:1/-1}.initiative-hero-orbit{right:18px;opacity:.5}}
@media (max-width:520px){.initiative-hover-story{grid-template-columns:1fr}.initiative-hover-story-heading{display:block}.initiative-hover-story-heading>strong{display:block;margin-top:6px}}
.initiatives-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 14px;padding:10px 12px;border:1px solid rgba(255,255,255,.06);border-radius:12px;background:linear-gradient(110deg,rgba(18,27,40,.88),rgba(9,14,22,.8))}
.initiatives-toolbar-copy{display:flex;flex-direction:column;gap:3px}
.initiatives-toolbar-copy strong{color:#cbd8e6;font-size:9px}
.initiatives-toolbar-copy strong b{color:#c8b9ff;font-size:15px;margin-right:4px}
.initiatives-toolbar-copy span{color:#687b91;font-size:6px}
.initiatives-filters{display:flex;gap:5px;overflow-x:auto}
.initiatives-filters button{flex:0 0 auto;padding:6px 8px;border:1px solid rgba(255,255,255,.06);border-radius:7px;background:rgba(255,255,255,.015);color:#72849a;font-size:6px;font-weight:800;cursor:pointer}
.initiatives-filters button:hover,.initiatives-filters button.active{border-color:rgba(159,143,255,.24);background:rgba(159,143,255,.07);color:#cfc2ff}
.initiative-card-grid{grid-template-columns:repeat(3,minmax(0,1fr))}
.initiative-card{position:relative;min-height:225px;padding:17px;border:1px solid rgba(255,255,255,.065);border-radius:14px;background:linear-gradient(145deg,rgba(24,32,45,.68),rgba(10,15,23,.92));box-shadow:0 14px 30px rgba(0,0,0,.13);overflow:hidden}
.initiative-card::after{content:'';position:absolute;right:-35px;bottom:-45px;width:110px;height:110px;border:1px solid rgba(115,185,201,.07);border-radius:50%;pointer-events:none}
.initiative-card-top{display:flex;align-items:center;justify-content:space-between;gap:8px}
.initiative-topic{color:#8295ab;font-size:6px;font-weight:900;letter-spacing:.11em}
.initiative-status{padding:4px 6px;border:1px solid rgba(121,199,161,.13);border-radius:5px;color:#79a991;background:rgba(121,199,161,.025);font-size:5px;font-weight:900;letter-spacing:.08em}
.initiative-orb{position:absolute;right:17px;top:45px;width:28px;height:28px;border:1px solid rgba(159,143,255,.17);border-radius:50%;display:grid;place-items:center}
.initiative-orb span{width:7px;height:7px;border-radius:50%;background:#9f8fff;box-shadow:0 0 10px rgba(159,143,255,.34)}
.initiative-card h2{margin:28px 40px 8px 0;color:#e1e9f3;font-size:15px;line-height:1.35}
.initiative-card p{margin:0;color:#74869c;font-size:8px;line-height:1.6;min-height:50px}
.initiative-context{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}
.initiative-context span{padding:5px 6px;border:1px solid rgba(255,255,255,.05);border-radius:5px;color:#65788f;background:rgba(255,255,255,.012);font-size:5px}
.initiative-card-footer{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:15px;padding-top:10px;border-top:1px solid rgba(255,255,255,.05)}
.initiative-card-footer>span{color:#596d84;font-size:5px;font-weight:900;letter-spacing:.08em}
.initiative-card-footer .follow-btn{font-size:6px}
.initiative-bottom-note{display:flex;align-items:center;gap:11px;margin-top:13px;padding:12px 14px;border:1px solid rgba(255,255,255,.055);border-radius:11px;background:rgba(13,19,28,.72)}
.initiative-bottom-note>div{flex:1}
.initiative-bottom-note strong{color:#b8c7d7;font-size:8px}
.initiative-bottom-note p{margin:3px 0 0;color:#687a90;font-size:6px}
.initiative-bottom-orbit{width:25px;height:25px;display:grid;place-items:center;border:1px solid rgba(159,143,255,.2);border-radius:50%;color:#a895ef;font-size:10px}
@media(max-width:900px){.initiative-card-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.initiative-hero-orbit{right:15px;opacity:.45}}
@media(max-width:650px){.initiative-card-grid{grid-template-columns:1fr}.initiatives-toolbar{align-items:flex-start;flex-direction:column}.initiatives-filters{width:100%}.initiative-bottom-note{align-items:flex-start;flex-wrap:wrap}}

/* Sidebar hierarchy accents */
.sidebar-section-label{color:#e1b84d!important}
.impact-zone-label{color:#9f8fff!important;font-weight:900;text-shadow:0 0 9px rgba(159,143,255,.18),0 0 16px rgba(120,255,220,.10)}
.zone-around-label{color:#73b9c9;font-weight:900;text-shadow:0 0 7px rgba(115,185,201,.16)}
.your-zones-label{color:#c66cff;font-weight:900;text-shadow:0 0 11px rgba(198,108,255,.24),0 0 15px rgba(181,108,255,.03)}
.flow-more-nested{margin-top:2px}
.flow-more-button{display:flex;align-items:center;gap:7px;width:100%;padding:6px 8px 6px 13px;border:0;background:transparent;color:#718197;font-size:7px;text-align:left;cursor:pointer}
.flow-more-button:hover,.flow-more-button[aria-expanded="true"]{color:#a9b9cc}
.flow-more-button .subnav-chevron{margin-left:auto;font-size:8px}
.flow-more-subnav{margin:1px 0 3px 12px;padding-left:8px;border-left:1px solid rgba(181,108,255,.18)}
.flow-more-subnav button{display:flex;align-items:center;gap:7px;width:100%;padding:6px 8px;border:0;border-radius:5px;background:transparent;color:#68788d;font-size:7px;text-align:left;cursor:pointer}
.flow-more-subnav button:hover,.flow-more-subnav button.active{background:rgba(181,108,255,.08);color:#d09cff}

/* IMPACT & AWARENESS */
.awareness-nav-button{display:flex;align-items:center;gap:13px;width:100%;padding:11px 13px;border:0;border-radius:9px;background:transparent;color:#858fa1;font-size:inherit;font-weight:inherit;letter-spacing:normal;text-align:left;cursor:pointer;transition:.2s}
.awareness-nav-button:hover{color:#e9eef8;background:rgba(255,255,255,.035)}
.awareness-nav-button.active{color:#f4f7fc;background:linear-gradient(90deg,rgba(72,103,163,.2),rgba(72,103,163,.05))}
.awareness-nav-button.active .icon{color:#70a8ff}
.awareness-section-line{height:1px;margin:4px 13px 7px;background:rgba(255,255,255,.08)}
/* Compact circular navigation for learning, awareness and impact */
.sidebar-orbit-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px;margin:7px 7px 10px;padding:8px 5px;border:1px solid rgba(255,255,255,.055);border-radius:14px;background:linear-gradient(145deg,rgba(24,34,49,.52),rgba(9,14,22,.36))}
.sidebar-orbit-button{display:flex;min-width:0;flex-direction:column;align-items:center;justify-content:flex-start;gap:6px;padding:5px 1px 7px;border:1px solid rgba(115,151,211,.14);border-radius:11px;background:linear-gradient(155deg,rgba(28,42,65,.62),rgba(10,16,28,.72));box-shadow:inset 0 1px 0 rgba(255,255,255,.035),0 3px 10px rgba(0,0,0,.08);color:#9eacc1;font-size:7px;font-weight:700;line-height:1.3;text-align:center;cursor:pointer;transition:background .18s ease,border-color .18s ease,color .18s ease,box-shadow .18s ease}
.sidebar-orbit-button>span:last-child{max-width:100%;overflow-wrap:anywhere}
.sidebar-orbit-icon{display:grid;place-items:center;width:35px;height:35px;flex:0 0 35px;border:1px solid rgba(142,166,197,.23);border-radius:50%;background:radial-gradient(circle at 35% 25%,rgba(255,255,255,.09),rgba(255,255,255,.015) 68%);font-size:17px;box-shadow:inset 0 0 12px rgba(255,255,255,.025)}
.sidebar-orbit-button:hover{background:linear-gradient(155deg,rgba(39,58,87,.78),rgba(15,25,41,.9));border-color:rgba(115,151,211,.28);color:#e5edf8;box-shadow:inset 0 1px 0 rgba(255,255,255,.045),0 4px 12px rgba(0,0,0,.12)}
.sidebar-orbit-button.active{background:linear-gradient(155deg,rgba(38,59,91,.88),rgba(16,29,48,.94));border-color:rgba(112,168,255,.3);box-shadow:inset 0 1px 0 rgba(255,255,255,.05),inset 0 0 0 1px rgba(112,168,255,.035),0 4px 12px rgba(0,0,0,.12);color:#f1f6ff}
.sidebar-orbit-learn .sidebar-orbit-icon{color:#c4b5fd;border-color:rgba(105,166,224,.43);background:radial-gradient(circle at 35% 25%,rgba(105,166,224,.2),rgba(35,72,112,.08) 72%)}
.sidebar-orbit-awareness .sidebar-orbit-icon{color:#9bc9f5;border-color:rgba(157,135,239,.43);background:radial-gradient(circle at 35% 25%,rgba(157,135,239,.2),rgba(76,59,122,.08) 72%)}
.sidebar-orbit-impact .sidebar-orbit-icon{color:#8ee0bf;border-color:rgba(99,185,155,.43);background:radial-gradient(circle at 35% 25%,rgba(99,185,155,.2),rgba(25,83,66,.08) 72%)}
.sidebar-orbit-learn.active{border-color:rgba(157,135,239,.22);color:#d4c8ff}
.sidebar-orbit-awareness.active{border-color:rgba(105,166,224,.22);color:#b9dcff}
.sidebar-orbit-impact.active{border-color:rgba(99,185,155,.22);color:#b7f1d9}
.rtl-mode .sidebar-orbit-button{text-align:center}

.learn-discover-content{max-width:1120px}
.learn-discover-title{margin-bottom:16px}
.learn-discover-title h1{max-width:820px}
.learn-discover-title p{max-width:760px}
.learn-discover-path{display:flex;align-items:center;gap:7px;margin:0 0 16px;padding:11px 13px;border:1px solid rgba(255,255,255,.055);border-radius:12px;background:rgba(12,18,27,.7);overflow:auto}
.learn-path-step{display:grid;grid-template-columns:auto 1fr;gap:2px 7px;min-width:150px;opacity:.68}
.learn-path-step span{grid-row:1 / 3;color:#62748a;font-size:6px;font-weight:900}
.learn-path-step strong{color:#8596ab;font-size:7px;letter-spacing:.1em}
.learn-path-step small{color:#56677b;font-size:6px;line-height:1.35}
.learn-path-step.active{opacity:1}
.learn-path-step.active strong{color:#d7b96a}
.learn-discover-path>i{color:#4e6178;font-style:normal;font-size:10px}
.learn-discover-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.learn-feature-card,.learn-topic-card,.learn-question-card,.learn-zone-card,.learn-closing-card{border:1px solid rgba(255,255,255,.065);border-radius:14px;background:linear-gradient(145deg,rgba(24,32,45,.68),rgba(10,15,23,.92));box-shadow:0 14px 30px rgba(0,0,0,.13)}
.learn-feature-card{grid-column:1 / -1;padding:20px;position:relative;overflow:hidden;background:radial-gradient(circle at 82% 15%,rgba(159,143,255,.09),rgba(10,15,23,.92) 42%)}
.learn-card-orbit{position:absolute;right:25px;top:18px;width:42px;height:42px;border:1px solid rgba(159,143,255,.28);border-radius:50%;display:grid;place-items:center;color:#b59cff;font-size:15px;box-shadow:0 0 22px rgba(159,143,255,.08)}
.learn-kicker{color:#73869d;font-size:6px;font-weight:900;letter-spacing:.12em}
.learn-feature-card h2,.learn-question-card h2,.learn-zone-card h2{margin:10px 0 8px;color:#e5edf7;font-size:18px;line-height:1.3;max-width:720px}
.learn-feature-card p,.learn-question-card p,.learn-zone-card p{margin:0;color:#7d8ea3;font-size:9px;line-height:1.65;max-width:760px}
.learn-tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:14px}
.learn-tags span,.learn-reading{padding:5px 7px;border:1px solid rgba(255,255,255,.055);border-radius:6px;color:#71849a;background:rgba(255,255,255,.015);font-size:6px;font-weight:800;letter-spacing:.08em}
.learn-discover-link,.learn-mini-link{margin-top:15px;padding:0;border:0;background:transparent;color:#9abde5;font-size:6px;font-weight:900;letter-spacing:.1em;cursor:pointer}
.learn-discover-link:hover,.learn-mini-link:hover{color:#d3e4f5}
.learn-topic-card{padding:17px;min-height:178px;display:flex;flex-direction:column}
.learn-topic-head{display:flex;align-items:center;gap:9px}
.learn-topic-icon{width:24px;height:24px;border:1px solid rgba(159,143,255,.2);border-radius:50%;display:grid;place-items:center;color:#a992e8;font-size:10px}
.learn-topic-card h3{margin:12px 0 7px;color:#dfe8f2;font-size:14px;line-height:1.35}
.learn-topic-card p{margin:0;color:#718298;font-size:8px;line-height:1.6}
.learn-reading{margin-top:auto;align-self:flex-start;padding:5px 6px;color:#63768b;background:rgba(255,255,255,.012)}
.learn-mini-link{align-self:flex-start;margin-top:11px}
.learn-question-card{grid-column:1 / -1;padding:18px;background:radial-gradient(circle at 15% 50%,rgba(114,201,107,.055),rgba(10,15,23,.9) 55%)}
.learn-question-flow{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:14px}
.learn-question-flow span{padding:6px 8px;border:1px solid rgba(121,199,161,.09);border-radius:6px;color:#7ea590;background:rgba(121,199,161,.02);font-size:6px;font-weight:900;letter-spacing:.08em}
.learn-question-flow i{color:#50657a;font-style:normal}
.learn-zone-card{grid-column:1 / -1;padding:18px;display:grid;grid-template-columns:1fr 180px;gap:20px;align-items:center}
.learn-zone-visual{height:130px;position:relative;border:1px solid rgba(115,185,201,.08);border-radius:11px;background:radial-gradient(circle,rgba(115,185,201,.07),rgba(10,15,23,.2) 60%)}
.learn-zone-visual span,.learn-zone-visual i,.learn-zone-visual b,.learn-zone-visual em{position:absolute;display:block;border-radius:50%;font-style:normal}
.learn-zone-visual span{width:52px;height:52px;left:62px;top:38px;border:1px solid rgba(115,185,201,.35);box-shadow:0 0 22px rgba(115,185,201,.08)}
.learn-zone-visual i{width:8px;height:8px;left:28px;top:30px;background:#9f8fff;box-shadow:0 0 12px rgba(159,143,255,.3)}
.learn-zone-visual b{width:7px;height:7px;right:30px;top:68px;background:#d6d46a;box-shadow:0 0 11px rgba(214,212,106,.22)}
.learn-zone-visual em{width:6px;height:6px;left:46px;bottom:23px;background:#73b9c9}
.learn-closing-card{grid-column:1 / -1;padding:14px 17px;display:flex;align-items:center;gap:13px;flex-wrap:wrap;background:rgba(14,20,29,.72)}
.learn-closing-card strong{color:#c5d2df;font-size:9px}
.learn-closing-card>span:last-child{color:#68798d;font-size:7px}
@media(max-width:800px){.learn-discover-grid{grid-template-columns:1fr}.learn-feature-card,.learn-question-card,.learn-zone-card,.learn-closing-card{grid-column:auto}.learn-zone-card{grid-template-columns:1fr}.learn-zone-visual{display:none}.learn-discover-path{align-items:flex-start}.learn-path-step{min-width:130px}}

.awareness-content{max-width:1120px;position:relative;padding-top:88px}
.awareness-title{margin-bottom:15px}
.awareness-content .awareness-filters{
  position:absolute;
  left:-165px;
  top:18px;
  width:calc(100% + 165px);
  z-index:2;
  padding:7px 10px;
  margin:0;
  border:1px solid rgba(255,255,255,.055);
  border-radius:9px;
  background:rgba(8,13,21,.72);
  box-shadow:0 8px 22px rgba(0,0,0,.16);
  backdrop-filter:blur(10px);
}
.awareness-title h1{max-width:760px}
.awareness-title p{max-width:760px}
.awareness-filters{display:flex;align-items:center;justify-content:flex-start;gap:6px;width:100%;min-width:0;flex-wrap:nowrap;white-space:nowrap;margin:0 0 16px;overflow-x:auto;overflow-y:hidden;padding:0 0 3px;scrollbar-width:thin}
.awareness-filter{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;white-space:nowrap;padding:7px 9px;border:1px solid rgba(255,255,255,.07);border-radius:7px;background:rgba(255,255,255,.018);color:#78899e;font-size:6px;font-weight:800;letter-spacing:.08em;cursor:pointer}
.awareness-filter:hover,.awareness-filter.active{border-color:rgba(121,174,240,.22);background:rgba(74,120,194,.07);color:#c4d8ee}
.awareness-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.awareness-card,.awareness-principle-card{border:1px solid rgba(255,255,255,.065);border-radius:14px;background:linear-gradient(145deg,rgba(24,32,45,.66),rgba(10,15,23,.9));box-shadow:0 14px 30px rgba(0,0,0,.13)}
.awareness-card{padding:18px}
.awareness-card-head{display:flex;align-items:center;justify-content:space-between;gap:10px}
.awareness-kicker{color:#71869f;font-size:6px;font-weight:900;letter-spacing:.12em}
.awareness-live-dot{color:#79c7a1;font-size:6px;font-weight:900;letter-spacing:.1em}
.awareness-card h2{margin:10px 0 8px;color:#e5edf7;font-size:17px;line-height:1.3}
.awareness-card p{margin:0;color:#7c8da2;font-size:9px;line-height:1.65}
.awareness-source-row{display:flex;gap:6px;flex-wrap:wrap;margin-top:14px}
.awareness-source-row span{padding:5px 7px;border:1px solid rgba(255,255,255,.055);border-radius:6px;background:rgba(255,255,255,.015);color:#6e8097;font-size:6px}
.awareness-link{margin-top:15px;padding:0;border:0;background:transparent;color:#91b9e6;font-size:6px;font-weight:900;letter-spacing:.1em;cursor:pointer}
.awareness-link:hover{color:#c8ddf3}
.awareness-impact-mark,.awareness-action-mark,.awareness-learn-mark,.awareness-future-mark{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;font-size:10px}
.awareness-impact-mark{border:1px solid rgba(240,164,93,.25);color:#f0a45d;background:rgba(240,164,93,.05)}
.awareness-action-mark{border:1px solid rgba(121,199,161,.2);color:#79c7a1;background:rgba(121,199,161,.05)}
.awareness-learn-mark{border:1px solid rgba(121,174,240,.2);color:#8eb7e7;background:rgba(121,174,240,.05)}
.awareness-future-mark{border:1px solid rgba(174,146,221,.2);color:#b69be0;background:rgba(174,146,221,.05)}
.awareness-chain{display:flex;align-items:center;gap:5px;flex-wrap:wrap;margin:14px 0}
.awareness-chain span{padding:7px 8px;border:1px solid rgba(240,164,93,.09);border-radius:7px;background:rgba(240,164,93,.025);color:#a89178;font-size:6px;line-height:1.35}
.awareness-chain i,.awareness-future-path i{color:#65768c;font-style:normal;font-size:10px}
.awareness-note{font-size:7px!important;color:#68798e!important}
.awareness-actions{display:grid;gap:7px;margin-top:13px}
.awareness-actions div{display:grid;grid-template-columns:23px 1fr;gap:7px;align-items:center;padding:7px 8px;border:1px solid rgba(121,199,161,.07);border-radius:7px;background:rgba(121,199,161,.018)}
.awareness-actions strong{color:#6f9b86;font-size:6px}
.awareness-actions span{color:#91a398;font-size:7px}
.awareness-meta{margin-top:14px;color:#5e7188;font-size:6px;font-weight:800;letter-spacing:.1em}
.awareness-future-path{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:14px}
.awareness-future-path span{padding:6px 7px;border:1px solid rgba(174,146,221,.09);border-radius:6px;color:#8d7ba9;background:rgba(174,146,221,.025);font-size:6px;font-weight:800;letter-spacing:.08em}
.awareness-principle-card{grid-column:1 / -1;padding:16px 18px;display:grid;grid-template-columns:auto 1fr;gap:9px 20px;align-items:center;background:radial-gradient(circle at 20% 50%,rgba(74,120,194,.07),rgba(10,15,23,.88) 60%)}
.awareness-principle-card .eyebrow{grid-column:1 / -1}
.awareness-principle{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
.awareness-principle strong{color:#a9bfd8;font-size:6px;letter-spacing:.08em}
.awareness-principle i{color:#51667f;font-style:normal;font-size:9px}
.awareness-principle-card p{margin:0;color:#718297;font-size:8px;line-height:1.55;max-width:540px}
@media(max-width:800px){.awareness-grid{grid-template-columns:1fr}.awareness-principle-card{grid-column:auto;grid-template-columns:1fr}.awareness-principle-card p{max-width:none}}


/* Shared Impact & Awareness composer and category navigation */
.awareness-category-panel{margin:18px 0 16px;padding:15px;border:1px solid rgba(255,255,255,.06);border-radius:12px;background:linear-gradient(135deg,rgba(28,42,59,.45),rgba(10,15,23,.62))}
.awareness-category-panel>div:first-child p{margin:6px 0 12px;color:#7c8da2;font-size:9px;line-height:1.6}
.awareness-category-chips{display:flex;flex-wrap:wrap;gap:6px}
.awareness-category-chips .awareness-filter{font-size:8px;letter-spacing:.02em;text-transform:none;padding:7px 10px}
.awareness-create-card{margin:16px 0;grid-column:1/-1}
.awareness-form-label{display:flex;flex:1;flex-direction:column;gap:6px;margin:12px 0;color:#9aacc1;font-size:9px;font-weight:700}
.awareness-form-label input,.awareness-form-label select,.awareness-form-label textarea{width:100%;box-sizing:border-box;border:1px solid rgba(255,255,255,.1);border-radius:8px;background:rgba(5,10,17,.72);color:#dce7f5;padding:10px 11px;font:inherit;font-size:10px;outline:none}
.awareness-form-label input:focus,.awareness-form-label select:focus,.awareness-form-label textarea:focus{border-color:rgba(121,174,240,.48);box-shadow:0 0 0 2px rgba(74,120,194,.08)}
.awareness-form-label textarea{resize:vertical;min-height:58px;line-height:1.55}
.awareness-form-row{display:flex;gap:12px}
.awareness-form-actions,.awareness-item-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:12px}
.awareness-submit-button{border:1px solid rgba(121,174,240,.24);border-radius:8px;padding:9px 12px;background:rgba(74,120,194,.13);color:#c4d8ee;font-size:8px;font-weight:900;letter-spacing:.06em;cursor:pointer}
.awareness-submit-button:hover{background:rgba(74,120,194,.22)}
.awareness-shared-item{min-width:0}
.awareness-story-section{margin-top:14px;padding-top:12px;border-top:1px solid rgba(255,255,255,.055)}
.awareness-story-section .awareness-kicker{display:block;margin-bottom:7px;color:#8fa9c6}
.awareness-story-section p{font-size:10px;line-height:1.7;color:#a1b0c2}
.awareness-item-actions{gap:8px}
.awareness-item-actions .awareness-link{margin-top:5px}
.awareness-empty-state{grid-column:1/-1}
.awareness-note{margin-top:12px!important;font-size:8px!important;color:#687b92!important}
@media(max-width:760px){.awareness-form-row{flex-direction:column;gap:0}.awareness-grid{grid-template-columns:minmax(0,1fr)}.awareness-content{padding-top:96px}.awareness-content .awareness-filters{left:0;width:100%;box-sizing:border-box}.awareness-category-panel{margin-top:14px}}

/* White, readable awareness examples; keep the surrounding platform dark. */
.awareness-category-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 14px;padding:0 0 10px;border-bottom:1px solid rgba(255,255,255,.08)}
.awareness-category-heading .eyebrow{color:#9ab4d3}
.awareness-category-panel{margin:0 0 18px;background:rgba(9,15,24,.7)}
.awareness-category-panel{display:flex;flex-direction:column;gap:12px}
.awareness-category-panel.awareness-category-compact{padding:12px 14px}
.awareness-category-group{display:flex;flex-direction:column;gap:8px}
.awareness-category-compact .awareness-category-chips{gap:5px}
.awareness-category-compact .awareness-category-chips .awareness-filter{padding:6px 9px;font-size:8px}
.awareness-category-compact .awareness-more-filter{border-style:dashed;border-color:rgba(139,167,198,.35);color:#a9c9ed;background:rgba(121,174,240,.06)}
.awareness-category-compact .awareness-more-filter:hover{border-color:rgba(121,174,240,.65);background:rgba(74,120,194,.14)}
.awareness-category-group+.awareness-category-group{padding-top:15px;border-top:1px solid rgba(255,255,255,.08)}
.awareness-category-group>.awareness-kicker{font-size:10px;letter-spacing:.14em;font-weight:800;color:#9ab4d3}
