/* The idea mark in the first home hero is an accessible entry into Idea Flow. */
.orbit-core-action {
  appearance: none;
  border: 0;
  padding: 0;
  color: inherit;
  font: inherit;
  cursor: pointer;
  transition: transform .22s ease, box-shadow .22s ease, border-color .22s ease;
}
.orbit-core-action:hover {
  transform: scale(1.08);
  box-shadow: 0 0 24px rgba(90, 174, 255, .28), inset 0 0 18px rgba(112, 130, 255, .16);
}
.orbit-core-action:focus-visible {
  outline: 2px solid rgba(130, 199, 255, .95);
  outline-offset: 5px;
}
@media (prefers-reduced-motion: reduce) {
  .orbit-core-action { transition: none; }
}



/* A slim luminous seam between the main platform and the Circles dimension. */
.dimension-portal-trigger {
  position: relative;
  align-self: center;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 100% !important;
  height: 34px;
  min-height: 34px;
  margin: 5px 0 7px;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  color: #b7caff;
  cursor: pointer;
  overflow: visible;
}
.dimension-portal-line {
  position: relative;
  display: block;
  width: 2px;
  height: 27px;
  border-radius: 50%;
  background: linear-gradient(180deg, transparent, #709cff 18%, #d7e5ff 50%, #8e7dff 82%, transparent);
  box-shadow: 0 0 5px rgba(107, 157, 255, .85), 0 0 13px rgba(102, 125, 255, .62), 0 0 24px rgba(117, 105, 255, .28);
  transition: height .25s ease, width .25s ease, filter .25s ease;
  animation: dimension-seam-pulse 3.2s ease-in-out infinite;
}
.dimension-portal-line::before,
.dimension-portal-line::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  width: 13px;
  height: 13px;
  border: 1px solid rgba(151, 179, 255, .45);
  border-radius: 50%;
  transform: translate(-50%, -50%) scale(.65);
  opacity: 0;
  pointer-events: none;
}
.dimension-portal-line::after {
  width: 23px;
  height: 23px;
  border-color: rgba(143, 123, 255, .3);
}
.dimension-portal-trigger:hover .dimension-portal-line,
.dimension-portal-trigger:focus-visible .dimension-portal-line {
  height: 32px;
  width: 3px;
  filter: brightness(1.4);
}
.dimension-portal-trigger:hover .dimension-portal-line::before,
.dimension-portal-trigger:focus-visible .dimension-portal-line::before {
  animation: dimension-ripple 1.15s ease-out infinite;
}
.dimension-portal-trigger:hover .dimension-portal-line::after,
.dimension-portal-trigger:focus-visible .dimension-portal-line::after {
  animation: dimension-ripple 1.15s ease-out .22s infinite;
}
.dimension-portal-trigger:focus-visible {
  outline: 1px solid rgba(157, 190, 255, .75);
  outline-offset: 2px;
}
@keyframes dimension-seam-pulse {
  0%, 100% { opacity: .62; filter: brightness(.85); }
  50% { opacity: 1; filter: brightness(1.3); }
}
@keyframes dimension-ripple {
  0% { opacity: .8; transform: translate(-50%, -50%) scale(.55); }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.9); }
}
@media (prefers-reduced-motion: reduce) {
  .dimension-portal-line { animation: none; }
  .dimension-portal-line::before,
  .dimension-portal-line::after { animation: none !important; }
}
.platform-circles-stage {
  position: fixed;
  inset: 0;
  z-index: 9999;
  width: 100vw;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: auto;
  padding: 28px;
  background:
    radial-gradient(ellipse at center, rgba(38, 58, 105, .16), transparent 47%),
    #080d18;
}
.platform-circles-row {
  width: min(100%, 1180px);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(12px, 2vw, 30px);
}
.platform-circle-node {
  position: relative;
  flex: 0 1 150px;
  width: clamp(94px, 11vw, 150px);
  height: clamp(94px, 11vw, 150px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 12px;
  border: 1px solid rgba(157, 184, 239, .35);
  border-radius: 50%;
  color: #edf2ff;
  background: radial-gradient(circle at 34% 24%, rgba(39, 57, 93, .98), rgba(9, 16, 30, .98) 75%);
  box-shadow: inset 0 0 28px rgba(129, 159, 226, .07), 0 12px 42px rgba(0, 0, 0, .2);
  cursor: pointer;
  transition: transform .24s ease, border-color .24s ease, box-shadow .24s ease;
}
.platform-circle-node::before {
  content: '';
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(153, 183, 244, .12);
  border-radius: 50%;
  pointer-events: none;
}
.platform-circle-node:hover {
  transform: translateY(-5px) scale(1.04);
  border-color: rgba(195, 213, 255, .85);
  box-shadow: 0 0 34px rgba(117, 152, 229, .18);
}
.platform-circle-node:focus-visible {
  outline: 2px solid #a8c4ff;
  outline-offset: 5px;
}
.platform-circle-mark {
  font-size: clamp(23px, 2.8vw, 34px);
  line-height: 1;
}
.platform-circle-name {
  max-width: 100%;
  font-size: clamp(9px, .9vw, 12px);
  line-height: 1.2;
  text-align: center;
}
.platform-circle-tone-violet { border-color: rgba(183, 161, 255, .37); }
.platform-circle-tone-violet .platform-circle-mark { color: #c6b7ff; }
.platform-circle-tone-gold { border-color: rgba(232, 197, 139, .38); }
.platform-circle-tone-gold .platform-circle-mark { color: #ebd2a5; }
.platform-circle-tone-mint { border-color: rgba(126, 218, 195, .35); }
.platform-circle-tone-mint .platform-circle-mark { color: #a0e5d2; }
@media (max-width: 760px) {
  .platform-circles-stage { padding: 28px 20px; }
  .platform-circles-row { width: min(100%, 500px); flex-wrap: wrap; gap: 20px; }
  .platform-circle-node {
    flex: 0 0 clamp(105px, 27vw, 135px);
    width: clamp(105px, 27vw, 135px);
    height: clamp(105px, 27vw, 135px);
  }
}
@media (max-width: 390px) {
  .platform-circles-row { gap: 14px; }
  .platform-circle-node { flex-basis: 112px; width: 112px; height: 112px; }
}
@media (prefers-reduced-motion: reduce) {
  .platform-circle-node { transition: none; }
}

/* Home and Live Flow share one visual navigation language; the dimension seam remains distinct. */
.main-nav .primary-space-nav-button,
.main-nav .primary-space-nav-button .icon {
  color: #aebbd0;
}
.main-nav .primary-space-nav-button:hover {
  color: #eaf2ff;
  background: rgba(104, 151, 226, .09);
}
.main-nav .primary-space-nav-button.active {
  color: #f1f6ff;
  background: linear-gradient(90deg, rgba(83, 132, 213, .22), rgba(83, 132, 213, .055));
  box-shadow: inset 2px 0 0 rgba(112, 168, 255, .82);
}
.main-nav .primary-space-nav-button.active .icon {
  color: #8ebaff;
}
.main-nav .primary-space-nav-button:not(.active) .icon {
  color: #8b9fbd;
}


/* Home, the dimension seam and Live Flow form one connected navigation object. */
.main-nav .primary-navigation-portal {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 1px 0 7px;
  padding: 4px;
  border: 1px solid rgba(115, 151, 211, .16);
  border-radius: 13px;
  background: linear-gradient(155deg, rgba(28, 42, 65, .62), rgba(10, 16, 28, .72));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.035), 0 5px 18px rgba(0,0,0,.12);
  overflow: visible;
}
.main-nav .primary-navigation-portal .primary-space-nav-button {
  width: 100%;
  min-height: 39px;
  border-radius: 8px;
  background: transparent;
}
.main-nav .primary-navigation-portal .primary-space-nav-button.active {
  background: linear-gradient(90deg, rgba(83, 132, 213, .22), rgba(83, 132, 213, .045));
  box-shadow: inset 2px 0 0 rgba(112, 168, 255, .82);
}

/* Keep the left active rail fixed; let a blue-violet signal travel on the right. */
.main-nav .primary-navigation-portal .primary-space-nav-button {
  position: relative;
  overflow: hidden;
}
.main-nav .primary-navigation-portal .primary-space-nav-button.active::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 6px;
  width: 3px;
  height: 17px;
  border-radius: 999px;
  opacity: .95;
  pointer-events: none;
  transform: translateY(-50%);
  background: linear-gradient(180deg, #a78bfa 0%, #7b78ff 38%, #4d8dff 72%, #6fc8ff 100%);
  background-size: 100% 220%;
  box-shadow: 0 0 6px rgba(126, 105, 255, .7), 0 0 13px rgba(77, 141, 255, .42);
  animation: navBlueVioletSignal 2.4s ease-in-out infinite;
}
@keyframes navBlueVioletSignal {
  0%, 100% { background-position: 0 0%; height: 10px; opacity: .72; box-shadow: 0 0 5px rgba(126, 105, 255, .55), 0 0 9px rgba(77, 141, 255, .28); }
  50% { background-position: 0 100%; height: 23px; opacity: 1; box-shadow: 0 0 8px rgba(167, 139, 250, .8), 0 0 16px rgba(77, 141, 255, .55); }
}
@media (prefers-reduced-motion: reduce) {
  .main-nav .primary-navigation-portal .primary-space-nav-button.active::after {
    animation: none;
    height: 16px;
    background-position: 0 50%;
  }
}
.main-nav .primary-navigation-portal .dimension-portal-trigger {
  height: 19px;
  min-height: 19px;
  margin: 0;
  border-radius: 0 !important;
}
.main-nav .primary-navigation-portal .dimension-portal-line {
  height: 13px;
  box-shadow: 0 0 5px rgba(107,157,255,.8), 0 0 12px rgba(102,125,255,.5);
}
.main-nav .primary-navigation-portal .dimension-portal-trigger:hover .dimension-portal-line,
.main-nav .primary-navigation-portal .dimension-portal-trigger:focus-visible .dimension-portal-line {
  height: 17px;
}


/* Final override: keep each navigation label on one line and prevent legacy
   diagonal-orbit button rules from pushing text across the sidebar. */
.main-nav .primary-spaces-cluster {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-rows: auto auto;
  gap: 0 5px;
  padding: 4px 0;
}
.main-nav .primary-spaces-cluster > .primary-navigation-portal {
  display: block;
  min-width: 0;
  width: 100%;
  margin: 0;
  padding: 0;
}
.main-nav .primary-spaces-cluster > .primary-navigation-portal:nth-child(1) { grid-column: 2; grid-row: 1; }
.main-nav .primary-spaces-cluster > .primary-navigation-portal:nth-child(2) { grid-column: 2; grid-row: 2; }
.main-nav .primary-spaces-cluster > .primary-navigation-portal:nth-child(3) { grid-column: 1; grid-row: 1; }
.main-nav .primary-spaces-cluster > .primary-navigation-portal:nth-child(4) { grid-column: 1; grid-row: 2; }
.main-nav .primary-spaces-cluster > .primary-navigation-portal .primary-space-nav-button {
  display: flex;
  position: relative;
  width: 100%;
  min-width: 0;
  min-height: 39px;
  margin: 0;
  padding: 7px 5px 7px 8px;
  gap: 6px;
  align-items: center;
  justify-content: flex-start;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  overflow-wrap: normal;
  word-break: normal;
  font-size: 10px;
  line-height: 1.2;
  border-radius: 7px;
}
.main-nav .primary-spaces-cluster > .primary-navigation-portal .primary-space-nav-button > span:not(.icon) {
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.main-nav .primary-spaces-cluster > .primary-navigation-portal .primary-space-nav-button .icon {
  flex: 0 0 14px;
  width: 14px;
  text-align: center;
}
@media (max-width: 1100px) {
  .main-nav .primary-spaces-cluster > .primary-navigation-portal .primary-space-nav-button {
    padding-left: 5px;
    padding-right: 4px;
    gap: 4px;
    font-size: 9px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .main-nav .primary-spaces-cluster > .primary-navigation-portal .primary-space-nav-button {
    transition: none;
  }
}

/* Zones Around and Your Zones are two sides of one connected space. */
.zones-subnav .zones-connected-pair {
