}


/* Put Home and Live Flow on one shared row, with the portal as their fine separator. */
.main-nav .primary-navigation-portal {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 16px minmax(0, 1fr);
  align-items: center;
  gap: 2px;
  padding: 4px;
}
.main-nav .primary-navigation-portal .primary-space-nav-button {
  min-width: 0;
  min-height: 37px;
  justify-content: flex-start;
  gap: 7px;
  padding: 9px 8px;
  white-space: nowrap;
  font-size: 11px;
}
.main-nav .primary-navigation-portal .primary-space-nav-button .icon {
  flex: 0 0 auto;
}
.main-nav .primary-navigation-portal .dimension-portal-trigger {
  width: 16px !important;
  height: 32px;
  min-height: 32px;
  margin: 0;
  border-left: 1px solid rgba(142, 166, 210, .16) !important;
}
.main-nav .primary-navigation-portal .dimension-portal-line {
  height: 18px;
  width: 2px;
}
.main-nav .primary-navigation-portal .dimension-portal-trigger:hover .dimension-portal-line,
.main-nav .primary-navigation-portal .dimension-portal-trigger:focus-visible .dimension-portal-line {
  height: 24px;
}
@media (max-width: 1100px) {
  .main-nav .primary-navigation-portal .primary-space-nav-button {
    gap: 5px;
    padding-left: 6px;
    padding-right: 6px;
    font-size: 10px;
  }
}


/* One planet, three connected navigation points — avoid the appearance of three separate cards. */
.main-nav .primary-navigation-portal {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 18px minmax(0, 1fr);
  align-items: center;
  gap: 0;
  margin: 2px 0 8px;
  padding: 4px;
  border: 1px solid rgba(116, 157, 221, .22);
  border-radius: 999px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(91, 131, 202, .18), transparent 65%),
    linear-gradient(115deg, rgba(27, 43, 68, .94), rgba(12, 21, 37, .96) 52%, rgba(24, 34, 59, .94));
  box-shadow: inset 0 1px 0 rgba(224, 236, 255, .07), inset 0 -7px 18px rgba(2, 8, 18, .28), 0 5px 17px rgba(0, 0, 0, .16);
  overflow: visible;
}
.main-nav .primary-navigation-portal::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 3px;
  border: 1px solid rgba(133, 169, 226, .09);
  border-radius: 999px;
  pointer-events: none;
}
.main-nav .primary-navigation-portal .primary-space-nav-button {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 35px;
  width: 100%;
  gap: 6px;
  padding: 7px 5px;
  border: 1px solid transparent !important;
  border-radius: 999px;
  background: transparent !important;
  box-shadow: none;
  color: #aebbd0;
  white-space: nowrap;
  font-size: 10px;
  transition: color .2s ease, background .2s ease, box-shadow .2s ease;
}
.main-nav .primary-navigation-portal .primary-space-nav-button:hover {
  background: rgba(123, 164, 235, .08) !important;
  box-shadow: inset 0 0 0 1px rgba(137, 174, 239, .12);
  color: #edf4ff;
}
.main-nav .primary-navigation-portal .primary-space-nav-button.active {
  border-color: rgba(131, 172, 244, .15) !important;
  background: linear-gradient(180deg, rgba(107, 157, 235, .18), rgba(70, 112, 182, .08)) !important;
  box-shadow: inset 0 1px 0 rgba(220, 234, 255, .08), 0 0 13px rgba(79, 133, 224, .08);
  color: #f1f6ff;
}
.main-nav .primary-navigation-portal .primary-space-nav-button .icon {
  flex: 0 0 auto;
  color: #8ebaff;
}
.main-nav .primary-navigation-portal .dimension-portal-trigger {
  position: relative;
  z-index: 2;
  width: 18px !important;
  height: 31px;
  min-height: 31px;
  margin: 0;
  padding: 0 !important;
  border: 0 !important;
  border-left: 1px solid rgba(142, 166, 210, .19) !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}
.main-nav .primary-navigation-portal .dimension-portal-line {
  height: 18px;
  width: 2px;
}
.main-nav .primary-navigation-portal .dimension-portal-trigger:hover .dimension-portal-line,
.main-nav .primary-navigation-portal .dimension-portal-trigger:focus-visible .dimension-portal-line {
  height: 24px;
}
@media (max-width: 1100px) {
  .main-nav .primary-navigation-portal .primary-space-nav-button {
    gap: 4px;
    padding-left: 3px;
    padding-right: 3px;
    font-size: 9px;
  }
}


/* Tilt the three navigation points into a diagonal orbit: between a row and a stack. */
.main-nav .primary-navigation-portal {
  grid-template-columns: minmax(0, 1fr) 18px minmax(0, 1fr);
  grid-template-rows: 31px 31px;
  align-items: center;
  column-gap: 0;
  row-gap: 0;
  padding: 5px 7px;
  border-radius: 23px 15px 23px 15px;
  background:
    radial-gradient(ellipse at 24% 15%, rgba(91, 131, 202, .18), transparent 58%),
    linear-gradient(135deg, rgba(27, 43, 68, .94), rgba(12, 21, 37, .96) 52%, rgba(24, 34, 59, .94));
}
.main-nav .primary-navigation-portal .primary-space-nav-button {
  min-height: 29px;
  padding: 5px 7px;
  font-size: 10px;
}
.main-nav .primary-navigation-portal .primary-space-nav-button:first-child {
  grid-column: 1 / 3;
  grid-row: 1;
  justify-self: start;
  width: auto;
  min-width: 76px;
  padding-left: 10px;
  padding-right: 12px;
  justify-content: flex-start;
}
.main-nav .primary-navigation-portal .dimension-portal-trigger {
  grid-column: 2;
  grid-row: 1 / 3;
  justify-self: center;
  align-self: center;
  height: 36px;
  min-height: 36px;
  border-left: 1px solid rgba(142, 166, 210, .19) !important;
  transform: translateX(1px);
}
.main-nav .primary-navigation-portal .primary-space-nav-button:last-child {
  grid-column: 2 / 4;
  grid-row: 2;
  justify-self: end;
  width: auto;
  min-width: 84px;
  padding-left: 12px;
  padding-right: 10px;
  justify-content: flex-end;
}
.main-nav .primary-navigation-portal .primary-space-nav-button.active {
  border-color: rgba(131, 172, 244, .15) !important;
  background: linear-gradient(180deg, rgba(107, 157, 235, .18), rgba(70, 112, 182, .08)) !important;
}
@media (max-width: 1100px) {
  .main-nav .primary-navigation-portal .primary-space-nav-button {
    font-size: 9px;
  }
}


/* Compact Commons connection hub: a small top-right header that leaves the page open for future modules. */
.home-commons-content{position:relative}
.home-connection-hub{position:relative;max-width:760px;margin:0 0 12px auto;padding:13px 15px 11px;border:1px solid rgba(111,145,193,.19);border-radius:15px;background:radial-gradient(ellipse at 100% 0%,rgba(79,126,184,.12),transparent 48%),linear-gradient(125deg,rgba(17,27,42,.92),rgba(9,15,25,.96));box-shadow:inset 0 1px 0 rgba(255,255,255,.035),0 8px 24px rgba(0,0,0,.09)}
.home-connection-heading{display:flex;align-items:center;justify-content:space-between;gap:18px}
.home-connection-title{flex:1;min-width:0}
.home-connection-heading h1{margin:3px 0 3px;color:#e5edf8;font-size:19px;line-height:1.2;letter-spacing:-.035em;font-weight:750}
.home-connection-heading p{margin:0;max-width:520px;color:#8190a5;font-size:10px;line-height:1.5}
.home-connection-kicker{display:block;color:#8da9cf;font-size:8px;font-weight:850;letter-spacing:.15em}
.home-impact-discovery-link{display:flex;align-items:center;gap:10px;flex:0 0 auto;max-width:245px;min-width:190px;padding:10px 12px;border:1px solid rgba(111,119,169,.42);border-radius:11px;background:linear-gradient(120deg,rgba(37,38,68,.96) 0%,rgba(29,40,63,.97) 58%,rgba(17,29,43,.98) 100%);box-shadow:inset 0 1px 0 rgba(210,216,255,.045),0 5px 14px rgba(0,0,0,.12);color:#edf0fb;text-align:left;font:inherit;cursor:pointer;transition:border-color .2s ease,background .2s ease,transform .2s ease,box-shadow .2s ease}
.home-impact-discovery-link:hover{border-color:rgba(137,145,202,.62);background:linear-gradient(120deg,rgba(45,45,79,.98) 0%,rgba(34,48,73,.98) 58%,rgba(20,33,48,.99) 100%);box-shadow:inset 0 1px 0 rgba(220,224,255,.07),0 6px 16px rgba(0,0,0,.16);transform:translateY(-1px)}
.home-impact-discovery-link:focus-visible{outline:2px solid rgba(255,220,132,.95);outline-offset:3px}
.home-impact-discovery-icon{display:grid;place-items:center;flex:0 0 34px;width:34px;height:34px;border:1px solid rgba(132,139,187,.42);border-radius:10px;background:linear-gradient(145deg,rgba(91,87,137,.22),rgba(44,76,106,.2));color:#d9d9f2;text-shadow:none;box-shadow:inset 0 0 8px rgba(174,164,255,.035)}
.home-impact-discovery-icon{display:grid;place-items:center;flex:0 0 31px;width:31px;height:31px;border:1px solid rgba(132,139,187,.38);border-radius:9px;background:rgba(91,87,137,.18);color:#d9d9f2;font-size:19px}
.home-impact-discovery-copy{display:flex;flex-direction:column;gap:3px;min-width:0}
.home-impact-discovery-copy .home-connection-kicker{color:#b2b3d6;font-size:7px}
.home-impact-discovery-copy strong{font-size:11px;line-height:1.3;font-weight:800}
.home-impact-discovery-copy small{color:#aeb8cd;font-size:9px;line-height:1.3}
.home-impact-discovery-copy small span{color:#c6c8e8}
.home-connection-orbit{position:relative;flex:0 0 40px;width:40px;height:40px;border:1px solid rgba(115,185,201,.26);border-radius:50%;background:radial-gradient(circle,rgba(115,185,201,.16),rgba(111,117,212,.05) 60%,transparent 70%)}
.home-connection-orbit:before,.home-connection-orbit:after{content:'';position:absolute;inset:6px;border:1px solid rgba(159,143,255,.36);border-radius:50%;transform:rotate(38deg) scaleX(.58)}
.home-connection-orbit:after{transform:rotate(-38deg) scaleX(.58);border-color:rgba(115,185,201,.35)}
.home-connection-orbit i,.home-connection-orbit b,.home-connection-orbit em{position:absolute;z-index:1;width:5px;height:5px;border-radius:50%;font-style:normal}
.home-connection-orbit i{top:5px;left:8px;background:#73b9c9}.home-connection-orbit b{right:5px;top:17px;background:#d6c96a}.home-connection-orbit em{bottom:5px;left:17px;background:#a99aff}
.home-connection-links{display:flex;flex-wrap:wrap;gap:6px;margin-top:11px}
.home-connection-link{display:inline-flex;align-items:center;gap:7px;min-height:27px;padding:5px 9px;border:1px solid rgba(135,156,186,.15);border-radius:8px;background:rgba(14,22,35,.76);color:#bac8da;font:inherit;font-size:9px;font-weight:750;cursor:pointer;transition:background .18s ease,border-color .18s ease,transform .18s ease}
.home-connection-link:hover{transform:translateY(-1px);color:#f0f5fb}
.home-connection-dot{width:6px;height:6px;border-radius:50%;background:var(--connection-color);box-shadow:0 0 8px color-mix(in srgb,var(--connection-color) 45%,transparent)}
.home-connection-chevron{margin-left:2px;color:var(--connection-color);font-size:12px;font-weight:500}
.home-connection-link.connection-mint{--connection-color:#73c9ae}.home-connection-link.connection-blue{--connection-color:#78aef5}.home-connection-link.connection-violet{--connection-color:#a99aff}.home-connection-link.connection-gold{--connection-color:#e0c477}.home-connection-link.connection-coral{--connection-color:#e49b88}.home-connection-link.connection-sky{--connection-color:#73b9c9}
/* Softened tinted backgrounds with a gentle lift of light. */
.home-connection-link.connection-mint{background:linear-gradient(145deg,rgba(66,126,109,.43),rgba(25,48,49,.9));border-color:rgba(143,218,193,.62)}
.home-connection-link.connection-blue{background:linear-gradient(145deg,rgba(70,112,163,.45),rgba(27,45,68,.91));border-color:rgba(151,192,248,.64)}
.home-connection-link.connection-violet{background:linear-gradient(145deg,rgba(112,99,157,.39),rgba(42,38,66,.91));border-color:rgba(190,180,255,.62)}
.home-connection-link.connection-gold{background:linear-gradient(145deg,rgba(139,117,69,.36),rgba(49,43,34,.91));border-color:rgba(235,213,151,.65)}
.home-connection-link.connection-coral{background:linear-gradient(145deg,rgba(145,91,85,.35),rgba(53,37,41,.91));border-color:rgba(240,180,162,.62)}
.home-connection-link.connection-sky{background:linear-gradient(145deg,rgba(68,120,137,.42),rgba(25,46,57,.91));border-color:rgba(146,210,222,.64)}
.home-connection-link.connection-mint,.home-connection-link.connection-blue,.home-connection-link.connection-violet,.home-connection-link.connection-gold,.home-connection-link.connection-coral,.home-connection-link.connection-sky{box-shadow:inset 0 1px 0 rgba(255,255,255,.055),0 0 16px color-mix(in srgb,var(--connection-color) 7%,transparent)}
.home-connection-link.connection-mint:hover,.home-connection-link.connection-blue:hover,.home-connection-link.connection-violet:hover,.home-connection-link.connection-gold:hover,.home-connection-link.connection-coral:hover,.home-connection-link.connection-sky:hover{border-color:color-mix(in srgb,var(--connection-color) 78%,rgba(220,231,247,.45));background:linear-gradient(145deg,color-mix(in srgb,var(--connection-color) 30%,rgba(35,49,68,.95)),rgba(22,35,51,.97));box-shadow:inset 0 1px 0 rgba(255,255,255,.09),0 0 20px color-mix(in srgb,var(--connection-color) 13%,transparent)}

.home-connection-link.active{border-color:color-mix(in srgb,var(--connection-color) 44%,transparent);background:color-mix(in srgb,var(--connection-color) 10%,rgba(12,19,31,.94));color:#eef5ff}
.home-connection-panel{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:9px;padding:10px 11px;border:1px solid rgba(133,157,193,.14);border-radius:10px;background:rgba(6,12,21,.58)}
.home-connection-panel-copy p{margin:4px 0 0;color:#a3b0c2;font-size:10px;line-height:1.5}
.home-connection-panel-actions{display:flex;flex-wrap:wrap;gap:6px;flex-shrink:0}
.home-connection-join,.home-connection-open{padding:6px 9px;border:1px solid rgba(115,185,201,.26);border-radius:7px;background:rgba(115,185,201,.1);color:#bfe9ed;font:inherit;font-size:9px;font-weight:800;cursor:pointer}
.home-connection-open{border-color:rgba(159,143,255,.24);background:rgba(159,143,255,.08);color:#d5ceff}
.home-view-switch{margin-bottom:10px}
@media(max-width:760px){.home-connection-hub{max-width:none;margin:0 0 10px;padding:11px}.home-connection-heading{flex-wrap:wrap;gap:12px}.home-impact-discovery-link{flex:1 1 100%;max-width:none}.home-connection-title{flex:1 1 calc(100% - 45px)}.home-connection-heading h1{font-size:17px}.home-connection-orbit{flex-basis:32px;width:32px;height:32px}.home-connection-panel{align-items:flex-start;flex-direction:column}.home-connection-panel-actions{width:100%}}
@media(prefers-reduced-motion:reduce){.home-connection-link{transition:none}}


/* Keep the original rotating Home header optional without hiding the Explore/Feed controls. */
.home-hero-control{display:flex;justify-content:flex-end;margin:0 0 5px}
.home-hero-toggle{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border:1px solid rgba(125,151,190,.2);border-radius:7px;background:rgba(13,22,36,.72);color:#93a5bd;font:inherit;font-size:9px;font-weight:750;cursor:pointer;transition:color .18s ease,border-color .18s ease,background .18s ease}
.home-hero-toggle:hover{color:#dce8f8;border-color:rgba(115,185,201,.42);background:rgba(22,37,55,.9)}
@media(prefers-reduced-motion:reduce){.home-hero-toggle{transition:none}}

/* Live Flow gets its own Commons hub, visually related to Home but focused on activity in motion. */
.live-flow-commons-hub{position:relative;margin:0 0 16px;padding:14px 16px 12px;border:1px solid rgba(111,145,193,.2);border-radius:15px;background:radial-gradient(ellipse at 100% 0%,rgba(93,133,205,.13),transparent 46%),linear-gradient(125deg,rgba(17,27,43,.94),rgba(8,15,26,.97));box-shadow:inset 0 1px 0 rgba(255,255,255,.035),0 8px 24px rgba(0,0,0,.08)}
.live-flow-commons-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}
.live-flow-commons-heading h2{margin:4px 0;color:#e6edf8;font-size:20px;line-height:1.2;letter-spacing:-.035em;font-weight:760}
.live-flow-commons-heading p{margin:0;max-width:560px;color:#8e9eb4;font-size:11px;line-height:1.5}
.live-flow-commons-orbit{position:relative;flex:0 0 44px;width:44px;height:44px;border:1px solid rgba(120,174,245,.3);border-radius:50%;background:radial-gradient(circle,rgba(120,174,245,.16),rgba(169,154,255,.05) 60%,transparent 70%);animation:live-flow-orbit-breathe 5s ease-in-out infinite}
.live-flow-commons-orbit:before,.live-flow-commons-orbit:after{content:'';position:absolute;inset:6px;border:1px solid rgba(169,154,255,.4);border-radius:50%;transform:rotate(38deg) scaleX(.58)}
.live-flow-commons-orbit:after{transform:rotate(-38deg) scaleX(.58);border-color:rgba(115,185,201,.4)}
.live-flow-commons-orbit i,.live-flow-commons-orbit b,.live-flow-commons-orbit em{position:absolute;z-index:1;width:5px;height:5px;border-radius:50%;font-style:normal}
.live-flow-commons-orbit i{top:5px;left:9px;background:#73c9ae}.live-flow-commons-orbit b{right:5px;top:19px;background:#e0c477}.live-flow-commons-orbit em{bottom:5px;left:19px;background:#a99aff}
.live-flow-commons-links{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}
.live-flow-commons-link{display:inline-flex;align-items:center;gap:7px;min-height:29px;padding:5px 10px;border:1px solid rgba(135,156,186,.15);border-radius:8px;background:rgba(14,22,35,.76);color:#bac8da;font:inherit;font-size:10px;font-weight:750;cursor:pointer;transition:background .18s ease,border-color .18s ease,transform .18s ease}
.live-flow-commons-link:hover{transform:translateY(-1px);color:#f0f5fb}
.live-flow-commons-link.flow-mint{--connection-color:#73c9ae}.live-flow-commons-link.flow-violet{--connection-color:#a99aff}.live-flow-commons-link.flow-blue{--connection-color:#78aef5}.live-flow-commons-link.flow-gold{--connection-color:#e0c477}.live-flow-commons-link.flow-coral{--connection-color:#e49b88}.live-flow-commons-link.flow-sky{--connection-color:#73b9c9}
.live-flow-commons-link.active{border-color:color-mix(in srgb,var(--connection-color) 44%,transparent);background:color-mix(in srgb,var(--connection-color) 10%,rgba(12,19,31,.94));color:#eef5ff}
.live-flow-commons-panel{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:10px;padding:11px 12px;border:1px solid rgba(133,157,193,.14);border-radius:10px;background:rgba(6,12,21,.58)}
@keyframes live-flow-orbit-breathe{0%,100%{transform:rotate(0deg);opacity:.82}50%{transform:rotate(12deg);opacity:1}}
@media(max-width:760px){.live-flow-commons-hub{padding:12px}.live-flow-commons-heading h2{font-size:18px}.live-flow-commons-orbit{flex-basis:34px;width:34px;height:34px}.live-flow-commons-panel{align-items:flex-start;flex-direction:column}.live-flow-commons-panel .home-connection-open{align-self:flex-start}}
@media(prefers-reduced-motion:reduce){.live-flow-commons-orbit{animation:none}.live-flow-commons-link{transition:none}}

/* A visible bridge connects the Live Flow activity hub to its relationship-detection section. */
.live-flow-commons-bridge{display:inline-flex;align-items:center;gap:7px;margin-top:12px;padding:6px 9px;border:1px solid rgba(120,174,245,.22);border-radius:7px;background:rgba(120,174,245,.07);color:#a9c9f7;text-decoration:none;font-size:10px;font-weight:800;transition:background .18s ease,border-color .18s ease}
.live-flow-commons-bridge:hover{background:rgba(120,174,245,.13);border-color:rgba(120,174,245,.42)}
.live-flow-connection-back{display:inline-flex;margin-top:6px;color:#8eb6ec;text-decoration:none;font-size:10px;font-weight:750}
.live-flow-connection-back:hover{color:#d2e4ff;text-decoration:underline}
#live-flow-connections{scroll-margin-top:24px}
@media(prefers-reduced-motion:reduce){.live-flow-commons-bridge{transition:none}}


/* =========================================================
   COMMONS INTERFACE SYSTEM — consistent, calm, professional
   A restrained visual layer shared across the existing views.
   Keeps existing markup, routes, and interactions intact.
   ========================================================= */
:root {
  color-scheme: dark;
  --ui-bg: #080d16;
  --ui-panel: rgba(15, 23, 36, .82);
  --ui-panel-raised: rgba(19, 29, 45, .88);
  --ui-border: rgba(145, 169, 204, .16);
  --ui-border-strong: rgba(145, 169, 204, .27);
  --ui-text: #e8eef8;
  --ui-muted: #8c9bb0;
  --ui-subtle: #65758c;
  --ui-blue: #8ebaff;
  --ui-radius: 14px;
  --ui-shadow: 0 14px 34px rgba(0, 0, 0, .14);
}
html { scroll-behavior: smooth; }
body {
  color: var(--ui-text);
  background-color: var(--ui-bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
button, input, select, textarea { font: inherit; }
button { -webkit-tap-highlight-color: transparent; }
button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
  outline: 2px solid rgba(142, 186, 255, .88);
  outline-offset: 3px;
}
.app-shell {
  background:
    radial-gradient(ellipse at 82% 0%, rgba(48, 79, 125, .075), transparent 34%),
    linear-gradient(90deg, rgba(255,255,255,.012), transparent 22%);
}
.sidebar {
  width: 244px;
  padding: 23px 15px 20px;
  border-right-color: rgba(145, 169, 204, .13);
  background: linear-gradient(180deg, rgba(9, 14, 23, .99), rgba(7, 11, 18, .99));
  box-shadow: 10px 0 34px rgba(0,0,0,.07);
  backdrop-filter: blur(18px);
}
.brand { padding: 3px 9px 25px; }
.brand strong { letter-spacing: .13em; }
.main-nav { gap: 3px; }
.main-nav button {
  min-height: 37px;
  border: 1px solid transparent;
  border-radius: 9px;
  font-size: 11px;
  transition: color .18s ease, background .18s ease, border-color .18s ease, transform .18s ease;
}
.main-nav button:hover { border-color: rgba(145,169,204,.09); }
.main-nav button.active {
  border-color: rgba(112,168,255,.14);
  box-shadow: inset 2px 0 0 rgba(112,168,255,.72);
}
.content {
  padding: 34px clamp(22px, 3.2vw, 46px) 76px;
}
.section-heading, .page-title { margin-bottom: 20px; }
.section-heading h1, .page-title h1 {
  letter-spacing: -.035em;
  line-height: 1.12;
}
.section-heading p, .page-title p { max-width: 720px; line-height: 1.7; }
.hero {
  border-color: var(--ui-border);
  border-radius: 18px;
  box-shadow: var(--ui-shadow), inset 0 1px rgba(255,255,255,.035);
}
.home-connection-hub, .live-flow-commons-hub {
  border-color: var(--ui-border);
  box-shadow: 0 12px 30px rgba(0,0,0,.12), inset 0 1px rgba(255,255,255,.035);
}
.home-connection-link, .live-flow-commons-link {
  border-radius: 9px;
}
.home-connection-link:hover, .live-flow-commons-link:hover {
  transform: translateY(-1px);
}
.goal-card, .suggestion-card, .post-card, .discover-card, .page-card,
.person-card, .event-card, .call-card, .initiative-card, .zone-card,
.proposal-card, .official-card, .network-card, .action-card {
  border-color: var(--ui-border);
  border-radius: var(--ui-radius);
  box-shadow: 0 8px 22px rgba(0,0,0,.08), inset 0 1px rgba(255,255,255,.018);
}
.goal-card, .suggestion-card {
  background: linear-gradient(145deg, rgba(18,27,41,.76), rgba(10,16,26,.76));
}
.primary-btn, .publish-btn, .home-connection-open, .primary-action,
button.primary, button[class*="primary"] {
  border-radius: 9px;
  transition: transform .18s ease, filter .18s ease, border-color .18s ease, background .18s ease;
}
.primary-btn:hover, .publish-btn:hover, .home-connection-open:hover, .primary-action:hover {
  filter: brightness(1.08);
}
input, select, textarea {
  border-color: var(--ui-border-strong);
  border-radius: 9px;
}
input::placeholder, textarea::placeholder { color: #6e7e94; }
.home-hero-toggle {
  border-color: var(--ui-border);
  border-radius: 8px;
}
.live-flow-commons-bridge { border-radius: 8px; }
a { text-underline-offset: 3px; }
@media (min-width: 1500px) {
  .content { padding-left: 52px; padding-right: 52px; }
}
@media (max-width: 900px) {
  .sidebar { width: 218px; padding-left: 12px; padding-right: 12px; }
  .content { padding-left: 24px; padding-right: 24px; }
}
@media (max-width: 760px) {
  .sidebar { backdrop-filter: none; }
  .content { padding: 24px 15px 48px; }
  .section-heading, .page-title { margin-bottom: 16px; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
  }
}



/* =========================================================
   LAYOUT REFINEMENT — align the workspace, navigation and page canvas
   ========================================================= */
:root {
  --commons-sidebar-width: 244px;
  --commons-page-gutter: clamp(20px, 3vw, 44px);
}
.app-shell { min-height: 100vh; }
.main {
  margin-left: var(--commons-sidebar-width);
  width: calc(100% - var(--commons-sidebar-width));
  min-width: 0;
  padding-left: 0;
}
.topbar {
  width: 100%;
  height: 64px;
  margin-left: 0;
  padding: 0 var(--commons-page-gutter);
  gap: 22px;
  border-bottom-color: rgba(145,169,204,.13);
  background: rgba(8,13,22,.88);
  box-shadow: 0 8px 24px rgba(0,0,0,.08);
}
.search-box {
  width: min(460px, 46vw);
  min-width: 180px;
  height: 36px;
  border-color: rgba(145,169,204,.15);
  background: rgba(255,255,255,.028);
  border-radius: 10px;
}
.top-actions { gap: 8px; }
.content {
  width: 100%;
  max-width: 1580px;
  margin: 0 auto;
  padding: 30px var(--commons-page-gutter) 72px;
}
.sidebar {
  width: var(--commons-sidebar-width);
  padding: 22px 14px 18px;
}
.brand { padding-bottom: 22px; }
.main-nav { gap: 3px; }
.main-nav button { min-height: 36px; }
.section-heading, .page-title { margin-bottom: 20px; }
.section-heading h1, .page-title h1 { margin-top: 0; }
.home-commons-content { min-width: 0; }
.home-connection-hub { width: min(100%, 920px); }
.live-flow-commons-hub { width: 100%; }
@media (min-width: 1500px) {
  .content { padding-top: 36px; }
}
@media (max-width: 1100px) {
  .topbar { gap: 14px; }
  .search-box { width: min(360px, 38vw); }
  .content { padding-top: 26px; }
}
@media (max-width: 900px) {
  :root { --commons-sidebar-width: 218px; --commons-page-gutter: 22px; }
  .sidebar { width: var(--commons-sidebar-width); }
  .main { margin-left: var(--commons-sidebar-width); width: calc(100% - var(--commons-sidebar-width)); }
  .topbar { padding-left: var(--commons-page-gutter); padding-right: var(--commons-page-gutter); }
}
@media (max-width: 760px) {
  .sidebar { display: none; }
  .main { margin-left: 0; width: 100%; padding-left: 0; padding-bottom: 90px; }
  .topbar {
    min-height: 104px;
    height: auto;
    margin-left: 0;
    padding: 11px 15px 12px;
    display: grid;
    grid-template-columns: 32px minmax(0, 1fr) auto;
    grid-template-rows: 35px 36px;
    align-content: center;
    align-items: center;
    column-gap: 12px;
    row-gap: 10px;
    background: rgba(8,13,22,.96);
    border-bottom: 1px solid rgba(145,169,204,.14);
  }
  .mobile-menu-launch {
    grid-column: 1;
    grid-row: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 4px;
    width: 31px;
    height: 31px;
    padding: 0;
    border: 1px solid rgba(126,157,201,.17);
    border-radius: 9px;
    background: linear-gradient(180deg,rgba(28,41,60,.62),rgba(18,29,45,.72));
    cursor: pointer;
  }
  .mobile-menu-launch span { display:block; width:13px; height:1.5px; border-radius:2px; background:#a8c9f2; }
  .mobile-menu-launch.active { border-color:rgba(121,173,237,.44); background:linear-gradient(180deg,rgba(47,70,101,.72),rgba(29,46,69,.82)); }
  .mobile-brand {
    grid-column: 2;
    grid-row: 1;
    display: flex;
    align-items: center;
    gap: 9px;
    min-width: 0;
    cursor: pointer;
    letter-spacing: 0;
  }
  .mobile-brand-mark {
    position: relative;
    display: grid;
    place-items: center;
    width: 31px;
    height: 31px;
    flex: 0 0 31px;
    border: 1px solid rgba(133,180,239,.42);
    border-radius: 10px;
    background: linear-gradient(145deg,rgba(37,63,95,.9),rgba(11,20,34,.96));
    box-shadow: inset 0 1px rgba(255,255,255,.08), 0 4px 13px rgba(0,0,0,.18);
  }
  .mobile-brand-mark i {
    width: 15px;
    height: 15px;
    border: 1px solid #9cc9fa;
    border-radius: 50%;
    transform: rotate(-35deg) scaleY(.68);
  }
  .mobile-brand-mark b {
    position: absolute;
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: #dcecff;
    box-shadow: 0 0 8px rgba(133,190,255,.6);
  }
  .mobile-brand-copy { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
  .mobile-brand-copy strong {
    color: #f0f5fc;
    font-size: 17px;
    line-height: 1;
    font-weight: 750;
    letter-spacing: -.045em;
  }
  .mobile-brand-copy small {
    color: #8297b3;
    font-size: 6px;
    line-height: 1;
    font-weight: 750;
    letter-spacing: .12em;
    white-space: nowrap;
  }
  .search-box {
    grid-column: 1 / -1;
    grid-row: 2;
    width: 100%;
    min-width: 0;
    height: 36px;
    box-sizing: border-box;
    gap: 9px;
    padding: 0 11px;
  }
  .search-box input { min-width: 0; font-size: 11px; }
  .search-box kbd { display: none; }
  .top-actions { grid-column: 3; grid-row: 1; gap: 5px; justify-content: flex-end; }
  .top-actions .top-icon { width: 30px; height: 30px; flex: 0 0 30px; }
  .top-actions .primary-btn { width: 31px; height: 30px; padding: 0; border-radius: 9px; }
  .mobile-network-launch {
    position: fixed;
    z-index: 60;
    right: 13px;
    bottom: 82px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    min-height: 42px;
    padding: 0 13px;
    border: 1px solid rgba(120,174,239,.45);
    border-radius: 999px;
    background: linear-gradient(120deg,rgba(24,48,76,.98),rgba(13,24,40,.98));
    color: #dcecff;
    box-shadow: 0 8px 24px rgba(0,0,0,.3), inset 0 1px rgba(255,255,255,.07);
    font-size: 10px;
    font-weight: 800;
    letter-spacing: .07em;
    cursor: pointer;
  }
  .mobile-network-launch > span:first-child { color: #9ac9ff; font-size: 16px; }
  .mobile-network-launch.active { border-color: rgba(143,193,255,.72); background: linear-gradient(120deg,rgba(36,68,105,.99),rgba(17,34,56,.99)); }
  .content {
    width: 100%;
    max-width: none;
    margin: 0;
    padding: 18px 15px 48px;
  }
  .home-connection-hub { width: 100%; }
  .home-view-switch { position: relative; z-index: 9; margin-top: 0; margin-bottom: 14px; }
}
@media (prefers-reduced-motion: reduce) {
  .topbar { backdrop-filter: none; }
}



/* Vertical hero control: collapse the large header upward and reclaim its space. */
.home-commons-content { position: relative; }
.home-hero-control {
  position: absolute;
  z-index: 8;
  top: 48px;
  right: 10px;
  margin: 0;
  justify-content: flex-end;
  pointer-events: none;
}
.home-hero-toggle {
  pointer-events: auto;
  min-height: 76px;
  width: 28px;
  padding: 9px 5px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 8px;
  border-radius: 9px;
  writing-mode: vertical-rl;
  text-orientation: mixed;
  background: rgba(10,17,28,.92);
  border-color: rgba(125,151,190,.3);
  box-shadow: 0 5px 18px rgba(0,0,0,.18);
}
.home-hero-toggle span { writing-mode: horizontal-tb; }

.home-view-switch > button.active {
  border-color: rgba(135, 164, 226, .62) !important;
  background: linear-gradient(115deg, rgba(75, 101, 157, .28), rgba(32, 48, 76, .72)) !important;
  color: #edf4ff !important;
  box-shadow: inset 0 0 0 1px rgba(157, 176, 224, .12), 0 0 12px rgba(108, 137, 207, .12) !important;
}
.home-view-switch > button:focus-visible {
  outline: 2px solid rgba(153, 184, 255, .75);
  outline-offset: 2px;
}

.home-commons-content:not(.home-hero-collapsed) .hero-stage {
  padding-right: 30px;
}
.home-commons-content.home-hero-collapsed .home-hero-control {
  top: 25px;
  right: 4px;
}
.home-commons-content.home-hero-collapsed .home-hero-toggle {
  min-height: 90px;
  background: linear-gradient(180deg, rgba(20,31,48,.98), rgba(10,17,28,.98));
}
.home-commons-content.home-hero-collapsed .home-view-switch {
  margin-top: 0;
  padding-right: 48px;
}
.home-commons-content.home-hero-collapsed .home-connection-hub {
  margin-top: 8px;
}
@media (max-width: 760px) {
  .home-hero-control { top: 30px; right: 5px; }
  .home-hero-toggle { min-height: 64px; width: 25px; font-size: 8px; }
  .home-commons-content:not(.home-hero-collapsed) .hero-stage { padding-right: 25px; }
  .home-commons-content.home-hero-collapsed .home-hero-control { top: 20px; right: 2px; }
  .home-commons-content.home-hero-collapsed .home-view-switch { padding-right: 38px; }
}



/* Keep the “something people do” headline accent blue instead of purple. */
.initiative-hero .commons-hero-copy h1 span:not(.ideas-word) {
  color: #78b5ff;
  -webkit-text-fill-color: #78b5ff;
  text-shadow: 0 2px 14px rgba(91, 157, 255, .2);
}

/* Home hero: add a subtle violet note while keeping “something people do.” blue-led. */
.hero .hero-accent-blue-home {
  color: #83baff;
  background: linear-gradient(100deg, #a5d8ff 0%, #8cafff 42%, #a18bff 76%, #8d8aff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 2px 12px rgba(91, 157, 255, .18), 0 0 13px rgba(153, 125, 255, .09);
}

/* Give “make your Zone” only a subtle hint of white. */
.hero .hero-zone-title {
  color: #f0edf8;
  text-shadow: 0 0 8px rgba(255, 255, 255, .07);
}

/* Purple-tinted Earth atmosphere behind the Zone hero. */
.hero-stage {
  position: relative;
  isolation: isolate;
}
.hero-stage::before {
  content: "";
  position: absolute;
  z-index: -1;
  pointer-events: none;
  width: min(58vw, 620px);
  aspect-ratio: 1;
  right: 4%;
  top: 50%;
  transform: translateY(-50%);
  border-radius: 50%;
  opacity: .34;
  background:
    radial-gradient(ellipse at 34% 31%, rgba(190,164,255,.48) 0 5%, transparent 22%),
    radial-gradient(ellipse at 64% 43%, rgba(122,86,190,.55) 0 9%, transparent 25%),
    radial-gradient(ellipse at 42% 64%, rgba(91,62,148,.8) 0 11%, transparent 29%),
    radial-gradient(circle at 35% 30%, #554477 0%, #292142 44%, #100f20 68%, transparent 70%);
  box-shadow: inset -22px -14px 42px rgba(4,5,16,.8), 0 0 55px rgba(135,83,214,.2);
  border: 1px solid rgba(188,158,255,.22);
  mask-image: radial-gradient(circle, #000 0 68%, transparent 72%);
}
.hero .hero-zone-title {
  color: #f1eaff;
  text-shadow: 0 0 14px rgba(157,111,255,.24);
}
.hero .hero-accent-impact,
.hero .hero-where-you-are {
  color: #c7a7ff;
  text-shadow: 0 0 12px rgba(155,105,255,.23);
}
.hero .hero-place-change {
  background: linear-gradient(105deg, #f0e7ff 0%, #c8a7ff 38%, #a783f4 68%, #e1d0ff 100%);
  background-size: 220% 100%;
}
.hero-zone-title-edit,
.hero-zone-title-editor button {
  border: 1px solid rgba(182,148,255,.35);
  border-radius: 7px;
  color: #e9dcff;
  background: rgba(93,62,145,.3);
  cursor: pointer;
}
.hero-zone-label {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 7px;
  min-height: 24px;
}
.hero-zone-label-text {
  color: #d4c1ff;
  font-size: clamp(14px, 1.25vw, 18px);
  font-weight: 650;
  letter-spacing: .045em;
  text-shadow: 0 0 14px rgba(160, 118, 255, .22);
}

@media (max-width: 760px) {
  .hero-stage::before { width: 82vw; right: -22%; top: 43%; opacity: .25; }
}

/* Add subtle motion only to “a place for change.” */
.hero-place-change {
  display: inline-block;
  background: linear-gradient(105deg, #d8e6ff 0%, #b8caff 35%, #e4d0ff 58%, #d8e6ff 78%, #b8caff 100%);
  background-size: 220% 100%;
  background-position: 0% 50%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: hero-place-change-shimmer 7s ease-in-out infinite;
}

/* Keep “Impacting” untouched; give only “where you are” a gentle pulse. */
.hero .hero-where-you-are {
  display: inline-block;
  animation: hero-where-you-are-life 4.8s ease-in-out infinite;
}

@keyframes hero-place-change-shimmer {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

@keyframes hero-where-you-are-life {
  0%, 100% { text-shadow: 0 0 0 rgba(245, 247, 251, 0); }
  50% { text-shadow: 0 0 9px rgba(245, 247, 251, .2); }
}

@media (prefers-reduced-motion: reduce) {
  .hero-place-change,
  .hero .hero-where-you-are {
    animation: none;
  }
}

/* Live Flow community video queue — collapsed until explicitly opened. */
.live-flow-space-toggle{width:100%;display:flex;align-items:center;gap:13px;margin:0 0 18px;padding:14px 17px;text-align:left;border:1px solid rgba(106,155,222,.23);border-radius:15px;background:linear-gradient(110deg,rgba(20,37,59,.95),rgba(12,22,36,.96));color:#e9f2ff;cursor:pointer;box-shadow:inset 0 1px rgba(225,238,255,.035);transition:border-color .18s ease,background .18s ease}
.live-flow-space-toggle:hover{border-color:rgba(122,177,255,.48);background:linear-gradient(110deg,rgba(25,46,73,.98),rgba(14,27,44,.98))}
.live-flow-space-toggle-icon{display:grid;place-items:center;width:37px;height:37px;flex:0 0 37px;border:1px solid rgba(115,169,245,.28);border-radius:11px;background:rgba(70,132,216,.14);color:#a9d0ff;font-size:18px}
.live-flow-space-toggle strong,.live-flow-space-toggle small{display:block}
.live-flow-space-toggle strong{font-size:12px;letter-spacing:.01em}
.live-flow-space-toggle small{margin-top:4px;color:#8ea3bf;font-size:10px}
.live-flow-space-toggle-action{margin-left:auto;color:#9bc7ff;font-size:10px;font-weight:800;white-space:nowrap}
.live-flow-video-queue{grid-column:1/-1;min-width:0;margin-top:2px;padding-top:18px;border-top:1px solid rgba(130,164,208,.13)}
.live-flow-video-queue-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}
.live-flow-video-queue-heading h3{margin:5px 0 0;color:#e5efff;font-size:16px;letter-spacing:-.025em}
.live-flow-video-queue-heading h3 span{display:inline-grid;place-items:center;min-width:22px;height:22px;margin-left:5px;padding:0 5px;border-radius:7px;background:rgba(100,155,230,.13);color:#a9ceff;font-size:10px}
.live-flow-video-queue-heading>button{padding:9px 12px;border:1px solid rgba(115,169,245,.3);border-radius:9px;background:rgba(49,105,178,.22);color:#c8e0ff;font-size:10px;font-weight:750;cursor:pointer}
.live-flow-video-queue-heading>button:disabled{opacity:.4;cursor:not-allowed}
.live-flow-queue-note{margin:10px 0 13px;color:#8599b4;font-size:10px;line-height:1.6}
.live-flow-video-queue-list{display:grid;gap:8px}
.live-flow-video-queue-item{display:flex;align-items:center;gap:11px;min-width:0;padding:11px;border:1px solid rgba(130,164,208,.13);border-radius:11px;background:rgba(5,12,22,.28)}
.live-flow-video-queue-number{display:grid;place-items:center;width:28px;height:28px;flex:0 0 28px;border-radius:8px;background:rgba(106,155,222,.1);color:#9fc6ff;font-size:11px;font-weight:800}
.live-flow-video-queue-info{display:flex;flex:1;flex-direction:column;gap:4px;min-width:0}
.live-flow-video-queue-info strong{overflow:hidden;color:#dce9fb;font-size:11px;text-overflow:ellipsis;white-space:nowrap}
.live-flow-video-queue-info small{color:#8195b0;font-size:9px}
.live-flow-video-queue-info a{color:#8dbfff;font-size:9px;text-decoration:none}
.live-flow-video-queue-item>button{flex:0 0 auto;padding:8px 10px;border:1px solid rgba(115,169,245,.25);border-radius:8px;background:rgba(54,103,167,.15);color:#b8d8ff;font-size:10px;font-weight:750;cursor:pointer}
.live-flow-video-queue-item>button.voted{border-color:rgba(96,201,169,.35);background:rgba(54,151,124,.15);color:#9ce4ca}
.live-flow-video-queue-empty{padding:16px;border:1px dashed rgba(124,163,218,.18);border-radius:11px;color:#8195b0;font-size:11px}
@media(max-width:760px){.live-flow-space-toggle{align-items:flex-start;padding:12px;gap:9px}.live-flow-space-toggle small{max-width:210px;line-height:1.5}.live-flow-space-toggle-action{font-size:9px}.live-flow-video-queue-heading{align-items:flex-start}.live-flow-video-queue-item{gap:8px;padding:9px}.live-flow-video-queue-item>button{padding:8px}}
@media(prefers-reduced-motion:reduce){.live-flow-space-toggle{transition:none}}

/* Live Flow community soundtrack */
.live-flow-music-player {
  position: relative;
  overflow: hidden;
  display: grid;
  grid-template-columns: minmax(220px, .85fr) minmax(280px, 1.15fr);
  gap: 20px 28px;
  margin: 0 0 24px;
  padding: 24px;
  border: 1px solid rgba(106, 155, 222, .2);
  border-radius: 22px;
  background: radial-gradient(ellipse at 0% 0%, rgba(76, 139, 222, .14), transparent 48%), linear-gradient(135deg, rgba(17, 29, 47, .98), rgba(13, 22, 36, .98));
  box-shadow: inset 0 1px 0 rgba(225, 238, 255, .035), 0 12px 34px rgba(0, 0, 0, .12);
}
.live-flow-music-copy h2 { margin: 9px 0 8px; color: #e9f2ff; font-size: clamp(20px, 2vw, 27px); letter-spacing: -.045em; }
.live-flow-music-copy p { max-width: 440px; margin: 0; color: #94a6bf; font-size: 12px; line-height: 1.75; }
.live-flow-music-update { align-self: center; min-width: 0; }
.live-flow-music-update label { display: block; margin-bottom: 8px; color: #b9c9de; font-size: 11px; font-weight: 700; }
.live-flow-music-input-row { display: flex; gap: 8px; }
.live-flow-music-input-row input { width: 100%; min-width: 0; padding: 12px 13px; border: 1px solid rgba(130, 164, 208, .25); border-radius: 11px; outline: none; background: rgba(5, 12, 22, .52); color: #e9f2ff; font: inherit; font-size: 12px; }
.live-flow-music-input-row input:focus { border-color: rgba(112, 174, 255, .65); box-shadow: 0 0 0 3px rgba(83, 145, 235, .1); }
.live-flow-music-input-row button { flex: 0 0 auto; padding: 0 15px; border: 1px solid rgba(115, 169, 245, .4); border-radius: 11px; background: linear-gradient(135deg, #3169b2, #3d83d9); color: #f7fbff; font: inherit; font-size: 11px; font-weight: 750; cursor: pointer; transition: filter .2s ease, transform .2s ease; }
.live-flow-music-input-row button:hover { filter: brightness(1.1); transform: translateY(-1px); }
.live-flow-music-error { margin: 7px 0 0; color: #ff9d9d; font-size: 11px; }
.live-flow-music-current { grid-column: 1 / -1; min-width: 0; padding-top: 4px; }
.live-flow-music-status { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-bottom: 11px; color: #a8caff; font-size: 9px; font-weight: 800; letter-spacing: .14em; }
.live-flow-music-status small { margin-left: auto; color: #7f91aa; font-size: 10px; font-weight: 500; letter-spacing: 0; }
.live-flow-music-live-dot { width: 7px; height: 7px; border-radius: 50%; background: #69b5ff; box-shadow: 0 0 10px rgba(105, 181, 255, .42); }
.live-flow-youtube-frame { overflow: hidden; width: 100%; max-width: 620px; aspect-ratio: 16 / 9; border: 1px solid rgba(132, 173, 229, .18); border-radius: 14px; background: #070d16; }
.live-flow-youtube-frame iframe { display: block; width: 100%; height: 100%; border: 0; }
.live-flow-music-footer { display: flex; justify-content: space-between; gap: 12px; margin-top: 10px; color: #778aa4; font-size: 10px; }
.live-flow-music-footer a { color: #8fc1ff; text-decoration: none; }
.live-flow-music-footer a:hover { color: #d1e6ff; }
.live-flow-music-empty { grid-column: 1 / -1; display: flex; align-items: center; gap: 13px; padding: 16px; border: 1px dashed rgba(124, 163, 218, .2); border-radius: 14px; color: #a6caff; background: rgba(6, 15, 28, .35); }
.live-flow-music-empty > span { display: grid; place-items: center; width: 38px; height: 38px; flex: 0 0 38px; border-radius: 12px; background: rgba(70, 132, 216, .13); font-size: 22px; }
.live-flow-music-empty strong, .live-flow-music-empty small { display: block; }
.live-flow-music-empty strong { margin-bottom: 4px; color: #dceaff; font-size: 12px; }
.live-flow-music-empty small { color: #8193ac; font-size: 11px; }
@media (max-width: 760px) {
  .live-flow-music-player { grid-template-columns: minmax(0, 1fr); gap: 18px; padding: 17px; }
  .live-flow-music-current, .live-flow-music-empty { grid-column: auto; }
  .live-flow-music-input-row { flex-direction: column; }
  .live-flow-music-input-row button { min-height: 40px; }
  .live-flow-music-status small { width: 100%; margin-left: 15px; }
}


/* Home discovery spaces: one connected family of surfaces, with color kept in each space's marker. */
.home-connection-links {
  gap: 5px;
  padding: 3px;
  border: 1px solid rgba(119, 157, 211, .13);
  border-radius: 11px;
  background: linear-gradient(105deg, rgba(21, 37, 59, .48), rgba(12, 23, 39, .58) 52%, rgba(22, 34, 53, .46));
}
.home-connection-link {
  position: relative;
  flex: 1 1 auto;
  justify-content: center;
  min-height: 30px;
  border-color: rgba(125, 157, 199, .12);
  background: linear-gradient(135deg, rgba(35, 53, 77, .74), rgba(20, 34, 53, .82));
  color: #c3d1e4;
  box-shadow: inset 0 1px 0 rgba(229, 239, 255, .035);
}
.home-connection-link:hover {
  border-color: rgba(133, 177, 238, .3);
  background: linear-gradient(135deg, rgba(49, 75, 109, .82), rgba(27, 47, 72, .9));
}
.home-connection-link.active {
  border-color: color-mix(in srgb, var(--connection-color) 42%, rgba(129, 169, 225, .2));
  background: linear-gradient(135deg, rgba(48, 75, 110, .94), rgba(28, 48, 73, .96));
  box-shadow: inset 0 1px 0 rgba(231, 241, 255, .07), 0 3px 12px rgba(0, 0, 0, .12);
}
@media (max-width: 760px) {
  .home-connection-links { gap: 5px; padding: 3px; }
  .home-connection-link { flex: 1 1 calc(33.333% - 5px); }
}


/* One connected navigation cluster: Home, Live Flow, Learn and Impact & Awareness. */
.main-nav .primary-spaces-cluster {
  position: relative;
  isolation: isolate;
  margin: 2px 0 9px;
  padding: 4px 0;
  border: 1px solid rgba(126, 153, 194, .14);
  border-radius: 14px;
  background:
    radial-gradient(ellipse at 18% 0%, rgba(89, 121, 174, .10), transparent 55%),
    linear-gradient(145deg, rgba(13, 19, 30, .96), rgba(8, 12, 20, .98) 62%, rgba(12, 18, 29, .96));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.025), 0 5px 14px rgba(0,0,0,.08);
}
.main-nav .primary-navigation-portal {
  margin: 0;
  padding: 0;
  border: 0 !important;
  border-radius: 0;
  background: transparent !important;
  box-shadow: none !important;
}
.main-nav .primary-navigation-portal .primary-space-nav-button {
  display: flex;
  justify-content: flex-start;
  width: 100%;
  margin: 0;
