.learn-topic-climate{top:15%;left:10%}.learn-topic-water{top:43%;left:37%}.learn-topic-cities{top:20%;right:8%}.learn-topic-nature{bottom:17%;left:12%}.learn-topic-energy{bottom:16%;right:8%}.learn-topic-community{top:70%;left:39%}
.learn-orbit-line{position:absolute;height:1px;background:linear-gradient(90deg,transparent,rgba(107,164,227,.28),transparent);pointer-events:none}
.learn-orbit-line-one{width:70%;left:15%;top:40%;transform:rotate(24deg)}.learn-orbit-line-two{width:68%;left:17%;top:54%;transform:rotate(-28deg)}.learn-orbit-line-three{width:55%;left:23%;top:49%;transform:rotate(77deg)}
.learn-selected-topic{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;padding:18px;border:1px solid rgba(255,255,255,.055);border-radius:13px;background:rgba(5,11,19,.35)}
.learn-selected-topic h3{margin:8px 0;color:#e7f0fb;font-size:23px;letter-spacing:-.035em}.learn-selected-topic>p{margin:0;color:#8b9db3;font-size:11px;line-height:1.8}
.learn-connected-tags{display:flex;flex-wrap:wrap;align-items:center;gap:7px;margin-top:17px}.learn-connected-tags>span{width:100%;margin-bottom:2px;color:#657991;font-size:7px;font-weight:900;letter-spacing:.12em}
.learn-connected-tags button{padding:6px 8px;border:1px solid rgba(121,170,227,.15);border-radius:7px;background:rgba(72,120,177,.08);color:#9dbfe5;font-size:9px;cursor:pointer}.learn-connected-tags button:hover{border-color:rgba(121,177,239,.42);color:#d8eaff}
.learn-feed-section{margin-bottom:22px}.learn-feed-filters{display:flex;flex-wrap:wrap;gap:7px;margin:15px 0 12px}
.learn-feed-filters button{padding:7px 10px;border:1px solid rgba(255,255,255,.075);border-radius:999px;background:rgba(12,18,28,.75);color:#71849c;font-size:8px;font-weight:800;letter-spacing:.08em;cursor:pointer}
.learn-feed-filters button.active{border-color:rgba(123,177,238,.42);background:rgba(67,116,174,.17);color:#d8eaff}
.learn-discoveries-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.learn-discovery-card{padding:16px;display:flex;flex-direction:column;min-height:190px;transition:border-color .18s ease,transform .18s ease}.learn-discovery-card:hover{transform:translateY(-2px);border-color:rgba(120,174,235,.3)}
.learn-discovery-card-top{display:flex;align-items:center;gap:8px}.learn-discovery-symbol{display:grid;place-items:center;width:27px;height:27px;border:1px solid rgba(125,177,236,.2);border-radius:9px;background:rgba(76,128,190,.1);color:#9dc9fa;font-size:13px}
.learn-discovery-card .learn-reading{margin-left:auto}.learn-discovery-card h3{margin:15px 0 7px;color:#dce8f6;font-size:14px;line-height:1.4}.learn-discovery-card p{margin:0;color:#7f91a7;font-size:10px;line-height:1.7}.learn-discovery-card .learn-mini-link{margin-top:auto;padding-top:14px}
.learn-zone-bridge{display:flex;align-items:center;gap:15px;padding:17px}.learn-zone-bridge-icon{display:grid;place-items:center;flex:0 0 40px;height:40px;border:1px solid rgba(120,194,173,.25);border-radius:50%;background:rgba(67,150,128,.09);color:#90d7c1;font-size:20px}
.learn-zone-bridge>div:nth-child(2){flex:1;min-width:0}.learn-zone-bridge h2{font-size:15px}.learn-zone-bridge p{font-size:9px}.learn-zone-bridge>.learn-discover-link{flex:0 0 auto;margin:0}
@media(max-width:800px){.learn-universe-layout{grid-template-columns:1fr}.learn-topic-orbit{min-height:250px}.learn-discoveries-grid{grid-template-columns:1fr}.learn-zone-bridge{align-items:flex-start;flex-wrap:wrap}.learn-zone-bridge>.learn-discover-link{margin-left:55px}}
@media(max-width:480px){.learn-universe-panel{padding:13px}.learn-topic-orbit{min-height:230px}.learn-topic-node{font-size:9px;padding:7px 8px}.learn-topic-water{left:35%}.learn-topic-community{left:35%}.learn-selected-topic{padding:13px}}
@media(prefers-reduced-motion:reduce){.learn-topic-node,.learn-discovery-card{transition:none}}


/* LEARN & DISCOVER — editorial-grade discovery and source cards */
.learn-feed-section{margin:0 0 24px}
.learn-feed-heading{align-items:flex-end;margin-bottom:16px}
.learn-results-count{flex:0 0 auto;padding:7px 10px;border:1px solid rgba(126,172,226,.18);border-radius:8px;background:rgba(64,111,169,.08);color:#9cb7d9;font-size:8px;font-weight:800;letter-spacing:.12em}
.learn-article-tools{display:grid;gap:12px;margin-bottom:15px}
.learn-search-field{display:flex;align-items:center;gap:10px;min-height:42px;padding:0 13px;border:1px solid rgba(133,163,204,.15);border-radius:10px;background:rgba(7,13,22,.88);color:#82a9d9}
.learn-search-field:focus-within{border-color:rgba(119,172,236,.48);box-shadow:0 0 0 3px rgba(90,146,212,.08)}
.learn-search-field>span{font-size:20px;line-height:1}
.learn-search-field input{flex:1;min-width:0;border:0;outline:0;background:transparent;color:#e3edf9;font-size:11px}
.learn-search-field input::placeholder{color:#64748a}
.learn-search-field button{border:0;background:transparent;color:#8fa4bf;font-size:19px;cursor:pointer}
.learn-feed-filters{display:flex;gap:7px;overflow-x:auto;padding:1px 0 4px;scrollbar-width:thin}
.learn-feed-filters button{flex:0 0 auto;padding:8px 11px;border:1px solid rgba(255,255,255,.075);border-radius:8px;background:rgba(12,18,28,.75);color:#8494aa;font-size:8px;font-weight:800;letter-spacing:.07em;white-space:nowrap;cursor:pointer;transition:background .18s,border-color .18s,color .18s}
.learn-feed-filters button.active{border-color:rgba(123,177,238,.42);background:rgba(67,116,174,.17);color:#d8eaff}
.learn-featured-article{display:grid;grid-template-columns:minmax(210px,.72fr) minmax(0,1.28fr);overflow:hidden;margin-bottom:14px;border:1px solid rgba(121,163,218,.2);border-radius:16px;background:linear-gradient(120deg,rgba(19,32,50,.98),rgba(9,15,24,.98) 72%);box-shadow:0 18px 40px rgba(0,0,0,.16)}
.learn-featured-visual{min-height:310px;position:relative;display:grid;place-items:center;overflow:hidden;background:radial-gradient(ellipse at 50% 48%,rgba(61,113,180,.23),transparent 48%),linear-gradient(150deg,#101f33,#080e18)}
.learn-featured-visual:before{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(119,163,217,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(119,163,217,.035) 1px,transparent 1px);background-size:30px 30px;mask-image:linear-gradient(to bottom,black,transparent)}
.learn-featured-orbit{position:absolute;left:50%;top:50%;border:1px solid rgba(132,180,239,.24);border-radius:50%;transform:translate(-50%,-50%) rotate(-25deg)}
.learn-featured-orbit.orbit-a{width:245px;height:104px}.learn-featured-orbit.orbit-b{width:175px;height:265px;transform:translate(-50%,-50%) rotate(42deg);border-color:rgba(162,136,234,.23)}.learn-featured-orbit.orbit-c{width:215px;height:215px;border-color:rgba(111,192,201,.13)}
.learn-featured-core{position:relative;z-index:1;display:grid;place-items:center;width:94px;height:94px;border:1px solid rgba(139,187,244,.42);border-radius:50%;background:radial-gradient(circle at 35% 25%,rgba(109,168,238,.28),rgba(9,18,31,.96) 72%);box-shadow:0 0 45px rgba(86,144,218,.13);color:#e1edff;text-align:center;font-size:9px;font-weight:800;line-height:1.7;letter-spacing:.16em}
.learn-featured-star{position:absolute;color:#9cc7f8;font-size:15px}.learn-featured-star.star-a{top:23%;right:22%}.learn-featured-star.star-b{bottom:24%;left:19%;color:#b9a1ed}
.learn-featured-copy{padding:25px 27px;display:flex;flex-direction:column;align-items:flex-start}
.learn-article-meta{display:flex;flex-wrap:wrap;align-items:center;gap:9px;color:#72839b;font-size:8px;font-weight:750;letter-spacing:.08em}
.learn-source-pill{padding:5px 7px;border:1px solid rgba(128,176,233,.2);border-radius:5px;background:rgba(76,128,192,.1);color:#a9c9f2;font-size:7px;letter-spacing:.09em}
.learn-featured-copy>.learn-kicker{margin-top:20px}
.learn-featured-copy h3{max-width:560px;margin:8px 0 10px;color:#edf4ff;font-size:clamp(21px,2.4vw,29px);line-height:1.16;letter-spacing:-.04em}
.learn-featured-copy>p{margin:0;color:#9aa9bd;font-size:11px;line-height:1.85}
.learn-key-takeaway{width:100%;margin-top:18px;padding:12px 14px;border-left:2px solid #78aeea;border-radius:0 8px 8px 0;background:rgba(76,125,186,.08)}
.learn-key-takeaway>span{color:#7eaee5;font-size:7px;font-weight:900;letter-spacing:.14em}
.learn-key-takeaway p{margin:6px 0 0;color:#c0ccdc;font-size:10px;line-height:1.7}
.learn-source-link{display:inline-flex;align-items:center;gap:8px;margin-top:18px;color:#9bc7fa;font-size:8px;font-weight:900;letter-spacing:.1em;text-decoration:none}
.learn-source-link span{font-size:13px;transition:transform .18s}
.learn-source-link:hover{color:#e0efff}.learn-source-link:hover span{transform:translate(2px,-2px)}
.learn-articles-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}
.learn-article-card{min-width:0;overflow:hidden;border:1px solid rgba(117,151,196,.14);border-radius:13px;background:linear-gradient(150deg,rgba(17,27,42,.94),rgba(8,13,21,.98));transition:transform .18s,border-color .18s,box-shadow .18s}
.learn-article-card:hover{transform:translateY(-2px);border-color:rgba(125,176,236,.3);box-shadow:0 13px 30px rgba(0,0,0,.15)}
.learn-article-card-art{height:105px;position:relative;display:grid;place-items:center;overflow:hidden;background:radial-gradient(circle at 50% 50%,rgba(90,149,206,.17),transparent 45%),linear-gradient(130deg,#14243a,#09111d)}
.learn-article-card-art:before,.learn-article-card-art:after{content:"";position:absolute;width:150px;height:70px;border:1px solid rgba(129,174,230,.19);border-radius:50%;transform:rotate(-25deg)}
.learn-article-card-art:after{width:75px;height:130px;transform:rotate(38deg);border-color:rgba(163,137,231,.19)}
.learn-article-card-art.art-nature{background:radial-gradient(circle at 50% 50%,rgba(84,174,139,.19),transparent 50%),linear-gradient(130deg,#102b2b,#09141b)}
.learn-article-card-art.art-climate{background:radial-gradient(circle at 50% 50%,rgba(150,126,221,.2),transparent 50%),linear-gradient(130deg,#20203b,#0a111e)}
.learn-article-card-art.art-water{background:radial-gradient(circle at 50% 50%,rgba(83,171,204,.2),transparent 50%),linear-gradient(130deg,#10283b,#08121d)}
.learn-art-orbit{position:absolute;width:185px;height:68px;border:1px solid rgba(150,192,240,.24);border-radius:50%;transform:rotate(22deg)}
.learn-art-core{position:relative;z-index:1;display:grid;place-items:center;width:42px;height:42px;border:1px solid rgba(153,194,243,.35);border-radius:50%;background:rgba(8,17,29,.78);color:#b5d6fc;font-size:20px}
.learn-art-label{position:absolute;bottom:10px;left:13px;color:rgba(197,217,243,.65);font-size:7px;font-weight:900;letter-spacing:.2em}
.learn-article-card-body{padding:15px;display:flex;flex-direction:column;align-items:flex-start}
.learn-article-card-body h3{margin:12px 0 8px;color:#e2ecf9;font-size:15px;line-height:1.4;letter-spacing:-.02em}
.learn-article-card-body>p{margin:0;color:#8999ae;font-size:10px;line-height:1.8}
.learn-article-source{margin-top:13px;color:#61748d;font-size:7px;font-weight:800;line-height:1.6;letter-spacing:.09em}
.learn-article-card-body .learn-source-link{margin-top:13px;padding-top:11px;border-top:1px solid rgba(255,255,255,.055);width:100%}
.learn-no-results{padding:42px 20px;border:1px dashed rgba(126,165,211,.2);border-radius:13px;text-align:center;background:rgba(9,15,24,.5)}
.learn-no-results>span{font-size:26px;color:#8bb8ee}.learn-no-results h3{margin:10px 0 6px;color:#dbe8f7;font-size:16px}.learn-no-results p{margin:0;color:#7c8da3;font-size:10px}
.learn-no-results button{margin-top:15px;padding:9px 12px;border:1px solid rgba(123,177,238,.25);border-radius:7px;background:rgba(67,116,174,.1);color:#a8c9ef;font-size:8px;font-weight:800;letter-spacing:.08em;cursor:pointer}
.learn-editorial-note{margin:12px 0 0;color:#596b81;font-size:8px;line-height:1.7}
@media(max-width:760px){.learn-featured-article{grid-template-columns:1fr}.learn-featured-visual{min-height:180px}.learn-featured-copy{padding:21px}.learn-articles-grid{grid-template-columns:1fr}}
@media(max-width:480px){.learn-feed-heading{align-items:flex-start;flex-direction:column}.learn-featured-copy h3{font-size:23px}.learn-article-card-art{height:90px}.learn-article-tools{gap:8px}}


/* IMPACT & AWARENESS — clearer editorial hierarchy */
.awareness-content{padding-top:12px!important}
.awareness-category-heading{align-items:center;gap:24px;margin:0 0 17px;padding:18px 0 20px;border-bottom:0}
.awareness-heading-copy{min-width:0;max-width:790px}
.awareness-heading-copy .eyebrow{display:inline-flex;align-items:center;gap:8px;color:#9ab4d3;font-size:9px;letter-spacing:.16em}
.awareness-heading-separator{color:#638b9a}
.awareness-heading-copy h1{max-width:780px;margin:13px 0 9px;color:#f0f5fc;font-size:clamp(27px,3.1vw,39px);font-weight:650;line-height:1.12;letter-spacing:-.045em}
.awareness-heading-copy h1 span{color:#a9c9f1}
.awareness-heading-copy p{max-width:710px;margin:0;color:#91a1b5;font-size:12px;line-height:1.85}
.awareness-category-heading>.awareness-submit-button{flex:0 0 auto;align-self:center;padding:11px 14px;border-color:rgba(128,177,231,.3);border-radius:9px;background:linear-gradient(135deg,rgba(66,121,184,.2),rgba(71,149,129,.1));color:#d8e8fa;font-size:9px;letter-spacing:.04em;box-shadow:inset 0 1px 0 rgba(255,255,255,.035);transition:transform .18s,border-color .18s,background .18s}
.awareness-category-heading>.awareness-submit-button:hover{transform:translateY(-1px);border-color:rgba(135,190,242,.55);background:linear-gradient(135deg,rgba(66,121,184,.3),rgba(71,149,129,.16))}
.awareness-intro-strip{display:flex;align-items:center;gap:14px;margin:0 0 20px;padding:15px 17px;border:1px solid rgba(127,163,204,.13);border-radius:13px;background:linear-gradient(110deg,rgba(22,37,54,.86),rgba(13,23,34,.9) 65%,rgba(19,37,40,.72));box-shadow:inset 0 1px 0 rgba(255,255,255,.025)}
.awareness-intro-item{display:flex;align-items:center;gap:10px;min-width:0;flex:1}
.awareness-intro-number{display:grid;place-items:center;width:30px;height:30px;flex:0 0 30px;border:1px solid rgba(128,174,223,.24);border-radius:9px;background:rgba(91,140,194,.09);color:#a9c9f1;font-size:9px;font-weight:800}
.awareness-intro-item:nth-of-type(3) .awareness-intro-number{border-color:rgba(121,199,161,.25);background:rgba(121,199,161,.07);color:#9ed9bd}
.awareness-intro-item strong,.awareness-intro-item small{display:block}
.awareness-intro-item strong{color:#d4e1f0;font-size:9px;letter-spacing:.11em}
.awareness-intro-item small{margin-top:4px;color:#75879d;font-size:9px;line-height:1.45}
.awareness-intro-arrow{color:#5f7895;font-size:15px}
.awareness-intro-count{display:flex;flex-direction:column;align-items:flex-end;justify-content:center;min-width:70px;padding-left:14px;border-left:1px solid rgba(255,255,255,.08)}
.awareness-intro-count strong{color:#e5f1ff;font-size:22px;font-weight:600;line-height:1.1}
.awareness-intro-count span{margin-top:4px;color:#7f91a7;font-size:8px;white-space:nowrap}
.awareness-category-panel{margin-bottom:22px!important;padding:17px 18px!important;border-color:rgba(132,166,205,.15)!important;border-radius:14px!important;background:linear-gradient(145deg,rgba(17,29,43,.88),rgba(9,15,23,.96))!important;box-shadow:0 12px 28px rgba(0,0,0,.1)}
.awareness-category-group>.awareness-kicker{color:#a5bad4;font-size:9px;letter-spacing:.15em}
.awareness-category-group+.awareness-category-group{padding-top:14px;border-top-color:rgba(151,176,207,.1)}
.awareness-category-compact .awareness-category-chips .awareness-filter{padding:7px 10px;border-radius:8px;font-size:9px;transition:background .16s,border-color .16s,color .16s}
.awareness-grid{align-items:stretch;gap:15px}
.awareness-content .awareness-shared-item{padding:21px!important;border-radius:15px!important;box-shadow:0 10px 28px rgba(0,0,0,.09)!important;transition:transform .18s,border-color .18s,box-shadow .18s}
.awareness-content .awareness-shared-item:hover{transform:translateY(-2px);border-color:#cbd9e8!important;box-shadow:0 15px 32px rgba(0,0,0,.12)!important}
.awareness-content .awareness-shared-item .awareness-card-head{align-items:flex-start}
.awareness-content .awareness-shared-item .awareness-kicker{font-size:8px;line-height:1.5;letter-spacing:.08em}
.awareness-content .awareness-shared-item h2{margin:14px 0 10px;font-size:20px;line-height:1.3;letter-spacing:-.025em}
.awareness-content .awareness-shared-item .awareness-source-row{margin-top:15px}
.awareness-content .awareness-shared-item .awareness-story-section{margin-top:17px;padding-top:14px}
.awareness-content .awareness-shared-item .awareness-story-section .awareness-kicker{font-size:8px;color:#54708e!important}
.awareness-content .awareness-shared-item .awareness-story-section p{font-size:11px;line-height:1.8}
.awareness-content .awareness-shared-item .awareness-item-actions{padding-top:12px;border-top:1px solid #e6ebf1;gap:13px}
.awareness-content .awareness-shared-item .awareness-link{font-size:8px;letter-spacing:.04em}
.awareness-content .awareness-principle-card{margin-top:2px;border-color:rgba(128,166,209,.14);border-radius:13px}
@media(max-width:900px){
  .awareness-intro-strip{gap:9px;padding:13px}
  .awareness-intro-item{gap:7px}
  .awareness-intro-item small{font-size:8px}
  .awareness-intro-count{min-width:58px;padding-left:10px}
}
@media(max-width:760px){
  .awareness-content{padding-top:8px!important}
  .awareness-category-heading{align-items:flex-start;flex-direction:column;gap:16px;padding:10px 0 18px}
  .awareness-category-heading>.awareness-submit-button{align-self:flex-start}
  .awareness-heading-copy h1{font-size:clamp(27px,7vw,36px)}
  .awareness-heading-copy p{font-size:11px}
  .awareness-intro-strip{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px}
  .awareness-intro-item{grid-column:1;align-items:flex-start}
  .awareness-intro-arrow{display:none}
  .awareness-intro-item small{font-size:9px}
  .awareness-intro-count{grid-column:2;grid-row:1 / span 3;align-self:stretch;min-width:66px}
  .awareness-category-panel{padding:14px!important}
}
@media(prefers-reduced-motion:reduce){.awareness-content .awareness-shared-item,.awareness-category-heading>.awareness-submit-button{transition:none}}



/* Administration shared-work folders */
.admin-shared-code{display:inline-block;padding:4px 9px;border:1px solid rgba(121,199,161,.26);border-radius:6px;background:rgba(121,199,161,.09);color:#a6e4c5;font-size:12px;letter-spacing:.1em}
.admin-collab-header h1{letter-spacing:-.035em}.admin-header-accent{color:#8db9e8;font-size:.58em;font-weight:500}
.admin-collab-header p{max-width:730px;line-height:1.8}
.admin-collab-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0 26px}
.admin-collab-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:0 0 13px}
.admin-collab-toolbar p{margin:6px 0 0;color:#7d8ea4;font-size:10px;line-height:1.6}
.admin-create-folder-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 13px;border:1px solid rgba(117,178,224,.28);border-radius:9px;background:linear-gradient(130deg,rgba(65,127,191,.2),rgba(72,155,128,.11));color:#d3e7f9;font-size:9px;font-weight:850;letter-spacing:.05em;cursor:pointer;transition:background .18s,border-color .18s,transform .18s}
.admin-create-folder-button:hover{transform:translateY(-1px);border-color:rgba(135,198,240,.52);background:linear-gradient(130deg,rgba(65,127,191,.3),rgba(72,155,128,.18))}
.admin-collab-create{display:grid;gap:12px;margin:0 0 16px;padding:19px;border:1px solid rgba(115,164,215,.18);border-radius:14px;background:linear-gradient(145deg,rgba(18,32,49,.95),rgba(10,16,25,.98))}
.admin-collab-form-heading{display:flex;align-items:center;gap:11px;margin-bottom:3px}
.admin-collab-form-heading .admin-folder-icon{display:grid;place-items:center;width:35px;height:35px;border:1px solid rgba(117,178,224,.22);border-radius:10px;color:#a8d3f2;font-size:20px}
.admin-collab-form-heading strong,.admin-collab-form-heading small{display:block}
.admin-collab-form-heading strong{color:#e0ebf8;font-size:13px}.admin-collab-form-heading small{margin-top:4px;color:#7f91a7;font-size:9px}
.admin-collab-create label{display:grid;gap:6px;color:#9eafc4;font-size:9px;font-weight:750}
.admin-collab-create input,.admin-collab-create textarea,.admin-inline-add input,.admin-note-composer textarea{width:100%;box-sizing:border-box;border:1px solid rgba(139,169,203,.15);border-radius:8px;background:rgba(4,9,16,.65);padding:10px 11px;color:#dce8f5;font:inherit;font-size:10px;outline:none}
.admin-collab-create input:focus,.admin-collab-create textarea:focus,.admin-inline-add input:focus,.admin-note-composer textarea:focus{border-color:rgba(117,178,224,.5);box-shadow:0 0 0 2px rgba(72,127,191,.09)}
.admin-collab-create textarea,.admin-note-composer textarea{resize:vertical;line-height:1.6}
.admin-collab-form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.admin-collab-form-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:2px}
.admin-collab-form-actions>span{color:#71839a;font-size:9px}
.admin-folder-feedback{margin:0 0 12px;padding:10px 12px;border:1px solid rgba(121,199,161,.15);border-radius:8px;background:rgba(67,155,111,.06);color:#a7d8bd;font-size:10px}
.admin-collab-workspace{display:grid;grid-template-columns:minmax(240px,300px) minmax(0,1fr);align-items:start;gap:14px}
.admin-collab-folder-list,.admin-collab-detail{min-width:0;border:1px solid rgba(255,255,255,.07);border-radius:15px;background:linear-gradient(145deg,rgba(14,22,33,.96),rgba(8,13,21,.98))}
.admin-collab-folder-list{padding:10px}
.admin-collab-folder{display:flex;align-items:flex-start;gap:10px;width:100%;margin-bottom:6px;padding:12px 10px;border:1px solid transparent;border-radius:10px;background:transparent;color:inherit;text-align:left;cursor:pointer;transition:background .16s,border-color .16s}
.admin-collab-folder:hover{background:rgba(255,255,255,.025);border-color:rgba(255,255,255,.06)}
.admin-collab-folder.active{background:linear-gradient(120deg,rgba(65,127,191,.15),rgba(72,155,128,.06));border-color:rgba(117,178,224,.2)}
.admin-collab-folder-icon{display:grid;place-items:center;flex:0 0 32px;height:32px;border:1px solid rgba(121,174,240,.17);border-radius:9px;background:rgba(74,120,194,.07);color:#a9c9ed;font-size:18px}
.admin-collab-folder-copy{display:grid;gap:5px;min-width:0;flex:1}
.admin-collab-folder-copy strong{color:#d9e6f4;font-size:10px;line-height:1.4;overflow-wrap:anywhere}
.admin-collab-folder-copy small{color:#778aa1;font-size:8px;line-height:1.4}
.admin-collab-folder .admin-folder-arrow{color:#7288a2;font-size:12px}
.admin-collab-local-note{margin:12px 3px 2px;padding:12px;border:1px dashed rgba(137,163,194,.14);border-radius:9px;background:rgba(255,255,255,.012)}
.admin-collab-local-note>span{color:#d5b979;font-size:8px;font-weight:850;letter-spacing:.12em}
.admin-collab-local-note p{margin:6px 0 0;color:#71839a;font-size:9px;line-height:1.65}
.admin-collab-detail{min-height:440px;padding:22px}
.admin-collab-detail-inner{min-width:0}
.admin-collab-detail-top{display:flex;align-items:center;justify-content:space-between;gap:12px}
.admin-collab-detail-top>.eyebrow{font-size:8px}
.admin-collab-detail h2{margin:13px 0 7px;color:#e4edf8;font-size:24px;line-height:1.25;letter-spacing:-.025em}
.admin-collab-description{margin:0;color:#91a1b5;font-size:11px;line-height:1.75}
.admin-collab-section{margin-top:23px;padding-top:18px;border-top:1px solid rgba(255,255,255,.065)}
.admin-collab-section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}
.admin-collab-section-heading h3{margin:5px 0 0;color:#d9e6f4;font-size:14px;font-weight:650}
.admin-collab-section-heading>span{display:grid;place-items:center;min-width:25px;height:25px;padding:0 6px;border:1px solid rgba(132,166,205,.14);border-radius:8px;color:#9bb7d5;font-size:9px}
.admin-collab-pills{display:flex;flex-wrap:wrap;gap:7px}
.admin-collab-person,.admin-collab-connection{display:inline-flex;align-items:center;gap:7px;padding:6px 9px;border:1px solid rgba(255,255,255,.07);border-radius:8px;background:rgba(255,255,255,.018);color:#b6c6d9;font-size:9px;overflow-wrap:anywhere}
.admin-collab-person i{display:grid;place-items:center;width:20px;height:20px;border-radius:50%;background:rgba(96,151,205,.14);color:#a9cff1;font-size:8px;font-style:normal;font-weight:800}
.admin-collab-connection{border-color:rgba(121,199,161,.12);background:rgba(67,155,111,.035);color:#9dcbb5}
.admin-collab-muted{color:#71839a;font-size:10px;line-height:1.6}
.admin-inline-add{display:flex;gap:7px;margin-top:11px}
.admin-inline-add input{min-width:0;flex:1}
.admin-inline-add button{flex:0 0 auto;padding:8px 10px;border:1px solid rgba(117,178,224,.2);border-radius:8px;background:rgba(74,120,194,.08);color:#b9d6f3;font-size:8px;font-weight:850;cursor:pointer}
.admin-inline-add button:hover{background:rgba(74,120,194,.16)}
.admin-note-composer{padding:12px;border:1px solid rgba(117,178,224,.12);border-radius:11px;background:rgba(61,105,155,.035)}
.admin-note-composer>div{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:9px}
.admin-note-composer small{color:#71839a;font-size:8px;line-height:1.5}
.admin-collab-notes{display:grid;gap:9px;margin-top:12px}
.admin-collab-note{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:13px;border:1px solid rgba(255,255,255,.065);border-radius:11px;background:rgba(255,255,255,.016)}
.admin-collab-note-main{display:flex;align-items:flex-start;gap:9px;min-width:0;flex:1}
.admin-collab-note-avatar{display:grid;place-items:center;flex:0 0 29px;height:29px;border:1px solid rgba(121,174,240,.16);border-radius:50%;background:rgba(74,120,194,.08);color:#a9c9ed;font-size:9px;font-weight:800}
.admin-collab-note-main>div{min-width:0}
.admin-collab-note-meta{display:flex;align-items:center;flex-wrap:wrap;gap:8px}
.admin-collab-note-meta strong{color:#d2e0ef;font-size:9px}.admin-collab-note-meta span{color:#71839a;font-size:8px}
.admin-collab-note-main p{margin:7px 0 0;color:#9aabc0;font-size:10px;line-height:1.7;overflow-wrap:anywhere}
.admin-vote-button{display:flex;flex-direction:column;align-items:center;gap:4px;flex:0 0 auto;min-width:55px;padding:8px 9px;border:1px solid rgba(121,174,240,.17);border-radius:9px;background:rgba(74,120,194,.055);color:#8faed0;cursor:pointer}
.admin-vote-button span{font-size:7px;font-weight:850;letter-spacing:.04em}.admin-vote-button strong{font-size:15px}
.admin-vote-button:hover,.admin-vote-button.voted{border-color:rgba(121,199,161,.35);background:rgba(67,155,111,.1);color:#a5e0c2}
.admin-collab-no-notes,.admin-collab-empty-list,.admin-collab-detail-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:25px 16px;text-align:center}
.admin-collab-no-notes{margin-top:12px;border:1px dashed rgba(137,163,194,.17);border-radius:10px}
.admin-collab-no-notes>span{color:#9dcbb5;font-size:20px}.admin-collab-no-notes strong,.admin-collab-empty-list strong{color:#cbd9e8;font-size:11px}
.admin-collab-no-notes p,.admin-collab-empty-list span,.admin-collab-detail-empty p{max-width:330px;margin:0;color:#788aa0;font-size:9px;line-height:1.7}
.admin-collab-empty-list{min-height:150px}
.admin-collab-detail-empty{min-height:400px}
.admin-collab-detail-empty h2{margin:0;font-size:20px}
@media(max-width:900px){.admin-collab-workspace{grid-template-columns:1fr}.admin-collab-folder-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px}.admin-collab-local-note{grid-column:1/-1}.admin-collab-detail{min-height:300px}}
@media(max-width:650px){.admin-collab-stats{grid-template-columns:1fr}.admin-collab-toolbar{align-items:flex-start;flex-direction:column}.admin-collab-form-row{grid-template-columns:1fr}.admin-collab-folder-list{grid-template-columns:1fr}.admin-collab-detail{padding:15px}.admin-collab-detail h2{font-size:21px}.admin-collab-note{gap:7px;padding:10px}.admin-vote-button{min-width:49px;padding:7px}.admin-collab-form-actions{align-items:flex-start;flex-direction:column}}


/* Home header replacement chat — occupies the hero's space and keeps its controls available. */
.home-hero-control { display:flex; align-items:center; gap:7px; }
.home-header-chat-toggle {
  pointer-events:auto; display:inline-flex; align-items:center; justify-content:center; gap:6px;
  min-height:32px; padding:6px 11px; border:1px solid rgba(105,190,220,.3); border-radius:8px;
  color:#b8e8f5; background:linear-gradient(135deg,rgba(27,71,91,.72),rgba(28,38,66,.78));
  font:inherit; font-size:10px; font-weight:750; cursor:pointer; transition:background .18s ease,border-color .18s ease;
}
.home-header-chat-toggle:hover,.home-header-chat-toggle.active {
  border-color:rgba(115,201,224,.62); background:linear-gradient(135deg,rgba(31,105,123,.72),rgba(55,62,112,.82)); color:#f1fbff;
}
.home-header-chat {
  position:relative; overflow:hidden; margin:0 0 10px; min-height:0; padding:12px 14px 10px;
  border:1px solid rgba(107,165,205,.24); border-radius:16px;
  background:radial-gradient(ellipse at 100% 0%,rgba(91,134,230,.15),transparent 42%),linear-gradient(125deg,rgba(16,29,47,.98),rgba(8,16,29,.98));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.04),0 10px 28px rgba(0,0,0,.12);
}
.home-header-chat-heading { display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:8px; }
.home-header-chat-heading h2 { margin:3px 0; color:#e8f1ff; font-size:clamp(16px,1.8vw,20px); letter-spacing:-.035em; }
.home-header-chat-heading p { margin:0; color:#91a5bd; font-size:11px; line-height:1.5; }
.home-header-chat-orbit { display:grid; place-items:center; flex:0 0 32px; width:32px; height:32px; border:1px solid rgba(111,198,218,.38); border-radius:50%; color:#9fe7ef; background:radial-gradient(circle,rgba(64,151,183,.2),rgba(25,41,65,.3)); box-shadow:0 0 24px rgba(67,164,192,.09); }
.home-header-chat-messages { display:flex; flex-direction:column; gap:6px; max-height:110px; overflow:auto; padding:1px 2px 9px; }
.home-header-chat-message { align-self:flex-start; max-width:min(88%,680px); padding:6px 9px; border:1px solid rgba(128,159,194,.15); border-radius:10px 10px 10px 3px; background:rgba(29,43,62,.76); }
.home-header-chat-message.is-you { align-self:flex-end; border-color:rgba(91,170,208,.25); background:rgba(28,70,91,.38); border-radius:10px 10px 3px 10px; }
.home-header-chat-message-meta { display:flex; align-items:center; gap:10px; color:#9dd5e6; font-size:9px; letter-spacing:.07em; }
.home-header-chat-message-meta span { color:#72869f; letter-spacing:0; }
.home-header-chat-message p { margin:4px 0 0; color:#d5e1ef; font-size:11px; line-height:1.5; overflow-wrap:anywhere; }
.home-header-chat-composer { display:flex; gap:6px; margin-top:6px; }
.home-header-chat-composer input { flex:1; min-width:0; padding:7px 10px; border:1px solid rgba(124,157,193,.24); border-radius:9px; outline:none; color:#e4eefb; background:rgba(5,12,22,.55); font:inherit; font-size:11px; }
.home-header-chat-composer input:focus { border-color:rgba(102,192,219,.62); }
.home-header-chat-composer button { padding:8px 13px; border:1px solid rgba(93,180,207,.35); border-radius:9px; color:#e9fbff; background:linear-gradient(120deg,#246e88,#485aa0); font:inherit; font-size:10px; font-weight:750; cursor:pointer; }
.home-header-chat-composer button:disabled { opacity:.45; cursor:not-allowed; }
.home-header-chat-note { margin:5px 0 0; color:#6e8199; font-size:9px; }
@media(max-width:760px) {
  .home-hero-control { gap:5px; }
  .home-header-chat-toggle { min-height:30px; padding:5px 8px; font-size:9px; }
  .home-header-chat { padding:16px 13px 12px; }
  .home-header-chat-heading h2 { font-size:18px; }
  .home-header-chat-message { max-width:96%; }
  .home-header-chat-composer { gap:6px; }
  .home-header-chat-composer button { padding:8px 10px; }
}



/* Keep the Hide/Show header control on the left, in the same spot when collapsed. */
.home-commons-content .home-hero-control {
  justify-content: flex-start;
  width: 100%;
}
.home-commons-content.home-hero-collapsed .home-hero-control {
  justify-content: flex-start;
}

/* Place Hide header on the LEFT edge of the Home header; keep its collapsed control anchored there too. */
.home-commons-content .home-hero-control {
  position:relative;
  inset:auto;
  z-index:8;
  display:flex;
  align-items:flex-start;
  justify-content:flex-start;
  gap:7px;
  margin:0 0 8px;
  padding:0;
  pointer-events:auto;
}
.home-commons-content .home-hero-toggle {
  pointer-events:auto;
  min-height:34px;
  width:auto;
  padding:7px 10px;
  display:inline-flex;
  flex-direction:row;
  align-items:center;
  justify-content:center;
  gap:7px;
  writing-mode:horizontal-tb;
  text-orientation:mixed;
  border-radius:8px;
}
.home-commons-content .home-hero-toggle span { writing-mode:horizontal-tb; }
.home-commons-content.home-hero-collapsed .home-hero-control {
  position:relative;
  inset:auto;
  justify-content:flex-start;
  margin:0 0 8px;
}
.home-commons-content.home-hero-collapsed .home-hero-toggle {
  min-height:32px;
  width:auto;
  padding:6px 10px;
  flex-direction:row;
  writing-mode:horizontal-tb;
}
.home-commons-content.home-hero-collapsed .home-view-switch { margin-top:0; padding-right:0; }
.home-commons-content:not(.home-hero-collapsed) .hero-stage { padding-right:0; }
.home-chat-rooms-heading { display:flex; align-items:center; justify-content:space-between; gap:8px; margin:0 0 8px; color:#9bb1c9; font-size:9px; font-weight:800; letter-spacing:.11em; }
.home-chat-rooms-heading small { color:#70859d; font-size:9px; font-weight:500; letter-spacing:0; }
.home-chat-rooms { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:6px; margin-bottom:8px; }
.home-chat-room { display:flex; align-items:center; gap:7px; min-width:0; padding:6px 8px; text-align:left; border:1px solid rgba(123,156,193,.17); border-radius:10px; color:#d9e6f5; background:rgba(19,32,49,.72);
}

/* A subtle moving violet orbit marks the user's current main space. */
.primary-navigation-portal .primary-space-nav-button.active {
  position: relative;
  isolation: isolate;
  z-index: 0;
}
.primary-navigation-portal .primary-space-nav-button.active::after {
  content: "";
  position: absolute;
  inset: -3px;
  padding: 1.5px;
  border-radius: 11px;
  background: conic-gradient(
    from 0deg,
    transparent 0deg,
    transparent 235deg,
    rgba(166, 113, 255, .08) 260deg,
    rgba(183, 132, 255, .96) 302deg,
    rgba(126, 83, 255, .8) 326deg,
    transparent 350deg,
    transparent 360deg
  );
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  animation: commons-active-orbit 3.2s linear infinite;
}
@keyframes commons-active-orbit {
  to { transform: rotate(360deg); }
}
@media (prefers-reduced-motion: reduce) {
  .primary-navigation-portal .primary-space-nav-button.active::after {
    animation: none;
    background: linear-gradient(135deg, transparent 10%, rgba(183,132,255,.9) 48%, transparent 88%);
  }
}

/* Live Flow: switch between What's Connecting and What's Moving in one shared space. */
.live-flow-space-pair{display:grid;grid-template-columns:76px minmax(0,1fr);align-items:stretch;gap:12px;margin:0 0 14px}
.live-flow-space-pair-content{min-width:0}
.live-flow-connecting-tab{position:sticky;top:18px;align-self:start;min-height:160px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:12px 7px;border:1px solid rgba(125,151,255,.28);border-radius:15px;background:linear-gradient(160deg,rgba(37,49,78,.97),rgba(15,23,40,.98));color:#dce7ff;cursor:pointer;text-align:center;box-shadow:inset 0 1px rgba(255,255,255,.05);transition:transform .18s ease,border-color .18s ease,background .18s ease}
.live-flow-connecting-tab:hover{transform:translateY(-2px);border-color:rgba(163,139,255,.7);background:linear-gradient(160deg,rgba(54,53,99,.98),rgba(17,25,43,.99))}
.live-flow-connecting-tab>span:first-child{display:grid;place-items:center;width:35px;height:35px;border-radius:11px;background:rgba(144,126,255,.13);border:1px solid rgba(164,147,255,.25);font-size:23px;color:#b9aaff}
.live-flow-connecting-tab strong{font-size:9px;line-height:1.55;letter-spacing:.11em}
.live-flow-connecting-tab .live-flow-connecting-tab-arrow{font-size:16px;color:#8dbdff}
.live-flow-connecting-tab-back{border-color:rgba(92,198,190,.25);background:linear-gradient(160deg,rgba(20,61,68,.96),rgba(13,27,39,.98))}
.live-flow-connecting-tab-back>span:first-child{color:#80e0d4;background:rgba(80,207,190,.1);border-color:rgba(80,207,190,.22)}
.live-flow-space-pair.is-connecting .live-flow-personal-connections{min-width:0;margin:0}
@media(max-width:700px){.live-flow-space-pair{grid-template-columns:56px minmax(0,1fr);gap:8px}.live-flow-connecting-tab{min-height:130px;padding:9px 4px}.live-flow-connecting-tab strong{font-size:8px}}

.live-flow-relationship-map{display:grid;grid-template-columns:minmax(130px,.7fr) minmax(0,1.3fr);gap:12px;align-items:stretch;margin:12px 0 16px;padding:12px;border:1px solid rgba(124,151,198,.16);border-radius:12px;background:radial-gradient(ellipse at 20% 50%,rgba(91,124,206,.1),transparent 60%),rgba(7,14,25,.4)}.live-flow-relationship-center{display:flex;flex-direction:column;justify-content:center;gap:7px;padding:14px;border:1px solid rgba(151,135,255,.28);border-radius:10px;background:linear-gradient(145deg,rgba(73,62,125,.22),rgba(20,29,46,.7));min-width:0}.live-flow-relationship-center small{font-size:8px;letter-spacing:.13em;color:#9eabce}.live-flow-relationship-center strong{font-size:14px;color:#e9e7ff;overflow-wrap:anywhere}.live-flow-relationship-center span{font-size:9px;color:#94a8c2;line-height:1.4}.live-flow-relationship-links{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.live-flow-relationship-links button{display:flex;flex-direction:column;align-items:flex-start;gap:5px;padding:10px;border:1px solid rgba(123,158,203,.17);border-radius:9px;background:rgba(255,255,255,.025);color:#d4e2f6;text-align:left;cursor:pointer}.live-flow-relationship-links button:hover,.live-flow-relationship-links button.active{border-color:rgba(142,139,255,.48);background:rgba(112,103,205,.1)}.live-flow-relationship-links button i{width:6px;height:6px;border-radius:50%;background:#7bc9cb;box-shadow:0 0 8px rgba(123,201,203,.35)}.live-flow-relationship-links button strong{font-size:10px}.live-flow-relationship-links button span{font-size:8px;color:#8299b8}@media(max-width:520px){.live-flow-relationship-map{grid-template-columns:1fr}.live-flow-relationship-links{grid-template-columns:repeat(2,minmax(0,1fr))}}
/* Clickable Live Flow objects, per-object streams and relationship links. */
.live-flow-map-node{font:inherit;cursor:pointer;appearance:none;transition:transform .18s ease,border-color .18s ease,background .18s ease}
.live-flow-map-node:hover,.live-flow-map-node.selected{transform:translateY(-2px);border-color:color-mix(in srgb,var(--node-color) 72%,white);background:rgba(24,37,57,.98);box-shadow:0 0 0 2px color-mix(in srgb,var(--node-color) 18%,transparent),0 0 18px color-mix(in srgb,var(--node-color) 12%,transparent)}
.live-flow-object-stream{margin:10px 0 14px;padding:14px;border:1px solid rgba(113,151,204,.2);border-radius:12px;background:linear-gradient(135deg,rgba(20,31,49,.9),rgba(10,17,29,.88))}
.live-flow-object-stream-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.live-flow-object-stream-head h3{margin:5px 0;color:#e4edfb;font-size:16px}.live-flow-object-stream-head p{margin:0;color:#94a8c2;font-size:11px;line-height:1.5}
.live-flow-object-close{width:27px;height:27px;border:1px solid rgba(147,169,204,.2);border-radius:8px;background:rgba(255,255,255,.04);color:#dce7f8;cursor:pointer;font-size:18px}
.live-flow-period-filters{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0 7px}.live-flow-period-filters button,.live-flow-related-object-row button{border:1px solid rgba(130,157,198,.2);border-radius:8px;background:rgba(255,255,255,.025);color:#aebed4;padding:7px 10px;font-size:10px;cursor:pointer}.live-flow-period-filters button.active{border-color:rgba(125,164,255,.52);background:rgba(85,127,210,.16);color:#e5edff}
.live-flow-stream-demo-note{margin:0 0 10px;color:#70839d;font-size:9px}.live-flow-object-stream-items{display:grid;gap:7px}.live-flow-object-stream-item{display:flex;gap:10px;padding:10px;border:1px solid rgba(255,255,255,.065);border-radius:9px;background:rgba(255,255,255,.025)}.live-flow-object-stream-item>i{display:grid;place-items:center;flex:0 0 28px;height:28px;border-radius:8px;background:color-mix(in srgb,var(--entity-color) 15%,transparent);color:var(--entity-color);font-style:normal}.live-flow-object-stream-item small{color:#8fa6c3;font-size:8px;letter-spacing:.06em}.live-flow-object-stream-item p{margin:4px 0;color:#d9e4f4;font-size:11px;line-height:1.45}.live-flow-object-stream-item span{color:#8194ad;font-size:9px}.live-flow-object-stream-empty{display:grid;gap:4px;padding:14px;border:1px dashed rgba(130,157,198,.2);border-radius:9px;color:#9eb0c7;font-size:10px}.live-flow-object-stream-empty strong{color:#d6e1f2;font-size:11px}
.live-flow-related-object-row{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin:0 0 12px;padding:12px;border:1px solid rgba(120,153,201,.14);border-radius:10px;background:rgba(255,255,255,.018)}.live-flow-related-label{margin-right:4px;color:#8197b5;font-size:8px;letter-spacing:.12em}.live-flow-related-object-row button{display:inline-flex;align-items:center;gap:6px}.live-flow-related-object-row button i{width:5px;height:5px;border-radius:50%;background:#81aaff}.live-flow-related-object-row button span{color:#7b9ac8}
@media(max-width:520px){.live-flow-object-stream{padding:10px}.live-flow-object-stream-head h3{font-size:14px}.live-flow-related-object-row{gap:5px}.live-flow-related-object-row button{padding:6px 8px}}
/* Animated Live Flow map: subtle moving signals between platform spaces. */
.live-flow-live-map{position:relative;height:112px;margin:12px 0 2px;overflow:hidden;border:1px solid rgba(105,145,193,.14);border-radius:11px;background:radial-gradient(ellipse at 48% 55%,rgba(71,117,177,.12),transparent 58%),linear-gradient(100deg,rgba(7,15,26,.66),rgba(15,24,39,.55));isolation:isolate}
.live-flow-live-lines{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.live-flow-live-lines .flow-link{fill:none;stroke:rgba(111,151,205,.28);stroke-width:1.15;vector-effect:non-scaling-stroke}
.live-flow-live-lines .flow-link-c{stroke:rgba(168,151,255,.32);stroke-dasharray:3 5}
.live-flow-live-lines .flow-particle{fill:none;stroke-width:2;stroke-linecap:round;stroke-dasharray:2 18;animation:live-flow-signal-travel 5.5s linear infinite;vector-effect:non-scaling-stroke}
.live-flow-live-lines .flow-particle-a{stroke:#7ab8ff}
.live-flow-live-lines .flow-particle-b{stroke:#a99aff;animation-delay:-2.7s;animation-duration:7s}
.live-flow-map-node{position:absolute;z-index:1;display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border:1px solid rgba(131,162,204,.22);border-radius:7px;background:rgba(12,21,35,.93);box-shadow:0 0 18px rgba(65,114,175,.07);color:#c8d8ed;font-size:9px;white-space:nowrap;animation:live-flow-node-breathe 3.6s ease-in-out infinite}
.live-flow-map-node i{width:6px;height:6px;border-radius:50%;background:var(--node-color);box-shadow:0 0 9px color-mix(in srgb,var(--node-color) 68%,transparent);animation:live-flow-node-pulse 2.1s ease-in-out infinite}
.live-flow-map-node b{font-weight:700}
.node-people{--node-color:#73c9ae;left:3%;top:44%}
.node-ideas{--node-color:#a99aff;left:20%;top:8%;animation-delay:-.8s}
.node-zones{--node-color:#78aef5;left:28%;top:62%;animation-delay:-1.4s}
.node-calls{--node-color:#e0c477;left:47%;top:32%;animation-delay:-.4s}
.node-actions{--node-color:#e49b88;left:67%;top:57%;animation-delay:-1.8s}
.node-conversations{--node-color:#73b9c9;right:2%;top:24%;animation-delay:-1.1s}
.live-flow-map-status{position:absolute;right:10px;bottom:7px;display:flex;align-items:center;gap:5px;color:#6f91b4;font-size:7px;font-weight:800;letter-spacing:.12em}
.live-flow-map-status i{width:5px;height:5px;border-radius:50%;background:#73c9ae;box-shadow:0 0 8px rgba(115,201,174,.75);animation:live-flow-node-pulse 1.7s ease-in-out infinite}
@keyframes live-flow-signal-travel{to{stroke-dashoffset:-120}}
@keyframes live-flow-node-breathe{0%,100%{transform:translateY(0);border-color:rgba(131,162,204,.2)}50%{transform:translateY(-3px);border-color:color-mix(in srgb,var(--node-color) 42%,transparent)}}
@keyframes live-flow-node-pulse{0%,100%{opacity:.65;transform:scale(.85)}50%{opacity:1;transform:scale(1.2)}}
@media(max-width:520px){.live-flow-live-map{height:126px}.live-flow-map-node{font-size:8px;padding:4px 5px;gap:4px}.node-people{left:2%;top:43%}.node-ideas{left:20%;top:8%}.node-zones{left:24%;top:66%}.node-calls{left:44%;top:35%}.node-actions{left:62%;top:61%}.node-conversations{right:1%;top:19%}.live-flow-map-status{font-size:6px;right:6px;bottom:5px}}
@media(prefers-reduced-motion:reduce){.live-flow-live-lines .flow-particle,.live-flow-map-node,.live-flow-map-node i,.live-flow-map-status i{animation:none}}



/* Local / World activity space, opened beside Chat in the Home controls. */
.home-local-world-toggle { border-color:rgba(113,173,145,.32); color:#c1efd6; background:linear-gradient(135deg,rgba(28,76,59,.62),rgba(27,46,66,.8)); }
.home-local-world-toggle:hover,.home-local-world-toggle.active { border-color:rgba(119,211,166,.65); background:linear-gradient(135deg,rgba(35,104,72,.78),rgba(36,70,91,.86)); color:#effff5; }
.home-local-world-panel { background:radial-gradient(ellipse at 100% 0%,rgba(74,170,130,.12),transparent 44%),linear-gradient(125deg,rgba(16,31,43,.98),rgba(8,16,29,.98)); }
.home-local-world-heading { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:10px; }
.home-local-world-heading h2 { margin:3px 0; color:#e8f1ff; font-size:clamp(16px,1.8vw,20px); letter-spacing:-.035em; }
.home-local-world-heading p { margin:0; color:#91a5bd; font-size:11px; line-height:1.45; }
.home-local-world-status { flex:0 0 auto; padding:5px 8px; border:1px solid rgba(105,204,151,.3); border-radius:999px; color:#a9e9c3; background:rgba(35,107,69,.18); font-size:9px; font-weight:750; }
.home-local-world-tabs { display:flex; flex-wrap:wrap; gap:6px; margin-bottom:9px; }
.home-local-world-tabs button { display:flex; align-items:center; gap:8px; padding:6px 10px; border:1px solid rgba(123,156,193,.2); border-radius:8px; color:#b8c9dc; background:rgba(19,32,49,.72); font:inherit; font-size:10px; cursor:pointer; }
.home-local-world-tabs button.active { border-color:rgba(111,204,164,.52); color:#e5fff0; background:linear-gradient(120deg,rgba(37,105,75,.55),rgba(34,72,91,.55)); }
.home-local-world-tabs button span { color:#9fdfb7; font-size:8px; }
.home-local-world-feed { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:7px; }
.home-local-world-item { display:flex; align-items:flex-start; gap:8px; min-width:0; padding:9px; border:1px solid rgba(123,156,193,.15); border-radius:10px; background:rgba(12,23,37,.58); }
.home-local-world-item-mark { display:grid; place-items:center; flex:0 0 23px; width:23px; height:23px; border-radius:7px; color:#b6e9d0; background:rgba(61,139,104,.2); font-size:12px; }
.home-local-world-item strong { color:#dce9f7; font-size:10px; }
.home-local-world-item p { margin:3px 0; color:#b1c1d4; font-size:10px; line-height:1.4; }
.home-local-world-item small { color:#71879f; font-size:8px; }
.home-local-world-note { margin:8px 0 0; color:#71879f; font-size:9px; }
@media(max-width:760px) {
  .home-hero-control { flex-wrap:wrap; }
  .home-local-world-feed { grid-template-columns:minmax(0,1fr); }
  .home-local-world-heading h2 { font-size:16px; }
}


/* Channel-first chat: show the conversation only after a channel is selected. */
.home-header-chat-heading { margin-bottom:6px; }
.home-header-chat-heading h2 { font-size:clamp(15px,1.6vw,18px); }
.home-header-chat-heading p { font-size:10px; }
.home-chat-rooms-heading { margin-bottom:5px; }
.home-chat-rooms { gap:6px; margin-bottom:6px; }
.home-chat-room { padding:7px 8px; border-radius:9px; }
.home-chat-room-copy { display:flex; flex-direction:column; gap:2px; min-width:0; }
.home-chat-room-copy strong { font-size:10px; line-height:1.2; }
.home-chat-room-copy small { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:9px; }
.home-chat-room-copy em { font-size:8px; }
.home-chat-room-join { flex:0 0 auto; font-size:9px; white-space:nowrap; }
.home-chat-select-prompt { margin:2px 0 0; padding:8px 10px; border:1px dashed rgba(123,156,193,.22); border-radius:8px; color:#8198b2; font-size:10px; text-align:center; }
.home-header-chat-active-room { margin-bottom:5px; }
.home-header-chat-messages { max-height:96px; padding-bottom:5px; }
@media(max-width:760px) {
  .home-chat-rooms { grid-template-columns:minmax(0,1fr); }
  .home-chat-room-copy small { white-space:normal; }
}


/* Unified Network workspace: chat and Local / World activity in one polished panel. */
.home-network-toggle { display:inline-flex; align-items:center; gap:8px; }
.home-network-toggle-caption { margin-left:2px; padding-left:8px; border-left:1px solid rgba(160,185,219,.2); color:#8fa8c7; font-size:9px; letter-spacing:.02em; }
.home-network-heading { margin-bottom:13px; }
.home-network-heading h2 { letter-spacing:-.035em; }
.home-network-activity { margin:0 0 15px; padding:13px; border:1px solid rgba(115,155,207,.19); border-radius:13px; background:linear-gradient(135deg,rgba(20,35,54,.76),rgba(10,20,34,.72)); }
.home-network-activity-top { display:flex; justify-content:space-between; align-items:flex-start; gap:12px; }
.home-network-activity-top strong { display:block; margin:4px 0 3px; color:#e4eefc; font-size:13px; letter-spacing:-.015em; }
.home-network-activity-top p { margin:0; color:#8fa5bf; font-size:10px; line-height:1.45; }
.home-network-section-label { color:#80a8db; font-size:8px; font-weight:800; letter-spacing:.14em; }
.home-network-activity .home-local-world-tabs { margin:10px 0 8px; }
.home-network-activity .home-local-world-feed { gap:8px; }
.home-network-activity .home-local-world-item { padding:9px 10px; transition:border-color .18s ease,background .18s ease; }
.home-network-activity .home-local-world-item:hover { border-color:rgba(112,165,225,.32); background:rgba(35,57,83,.42); }
.home-network-activity .home-local-world-item strong { font-size:10px; }
.home-network-activity .home-local-world-item p { font-size:10px; line-height:1.45; }
.home-network-activity .home-local-world-note { margin-top:8px; }
.home-header-chat .home-chat-rooms-heading { display:flex; align-items:center; justify-content:space-between; gap:10px; }
.home-header-chat .home-chat-rooms-heading span { color:#a8bdd8; font-size:8px; font-weight:800; letter-spacing:.13em; }
.home-header-chat .home-chat-rooms-heading small { color:#758ca8; font-size:9px; }
.home-header-chat .home-chat-room { transition:transform .18s ease,border-color .18s ease,background .18s ease; }
.home-header-chat .home-chat-room:hover { transform:translateY(-1px); }
.home-header-chat .home-header-chat-active-room { display:flex; align-items:center; justify-content:space-between; gap:10px; }
.home-header-chat .home-header-chat-messages { max-height:150px; overflow:auto; scrollbar-width:thin; }
@media(max-width:760px) {
  .home-network-toggle { flex-wrap:wrap; justify-content:center; }
  .home-network-toggle-caption { font-size:8px; }
  .home-network-activity { padding:10px; }
  .home-network-activity-top strong { font-size:12px; }
}


/* Restore the original coloured, softly-shining selected states for Learn and Impact. */
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-learn.active {
  color: #e5dcff !important;
  border-color: rgba(178, 139, 255, .58) !important;
  background:
    radial-gradient(ellipse at 18% 0%, rgba(184, 137, 255, .27), transparent 72%),
    linear-gradient(145deg, rgba(91, 57, 145, .58), rgba(30, 34, 66, .84) 58%, rgba(17, 24, 43, .92)) !important;
  box-shadow:
    inset 0 1px 0 rgba(239, 224, 255, .18),
    inset 0 0 0 1px rgba(188, 151, 255, .14),
    0 0 13px rgba(151, 104, 255, .19),
    0 4px 12px rgba(0, 0, 0, .16) !important;
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-learn.active .sidebar-orbit-icon {
  color: #e2ceff !important;
  border-color: rgba(195, 157, 255, .72) !important;
  background: radial-gradient(circle at 35% 25%, rgba(198, 156, 255, .42), rgba(87, 57, 142, .30) 72%) !important;
  box-shadow: 0 0 12px rgba(171, 120, 255, .22);
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-awareness.active {
  color: #d8f0ff !important;
  border-color: rgba(104, 190, 255, .62) !important;
  background:
    radial-gradient(ellipse at 18% 0%, rgba(92, 190, 255, .25), transparent 72%),
    linear-gradient(145deg, rgba(31, 99, 143, .56), rgba(22, 48, 79, .84) 58%, rgba(14, 25, 43, .93)) !important;
  box-shadow:
    inset 0 1px 0 rgba(221, 244, 255, .17),
    inset 0 0 0 1px rgba(110, 199, 255, .15),
    0 0 13px rgba(63, 166, 255, .19),
    0 4px 12px rgba(0, 0, 0, .16) !important;
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-awareness.active .sidebar-orbit-icon {
  color: #c9eaff !important;
  border-color: rgba(119, 204, 255, .72) !important;
  background: radial-gradient(circle at 35% 25%, rgba(102, 198, 255, .40), rgba(32, 94, 143, .30) 72%) !important;
  box-shadow: 0 0 12px rgba(73, 177, 255, .22);
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-learn:hover,
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-awareness:hover {
  filter: brightness(1.12);
}



/* Smooth colour build-up on selection: glow blooms in, then stays stacked while active. */
.main-nav .primary-spaces-cluster .sidebar-orbit-button {
  position: relative;
  overflow: hidden;
  transform: translateZ(0);
  transition:
    color .28s ease,
    background .42s cubic-bezier(.2,.75,.25,1),
    border-color .32s ease,
    box-shadow .42s ease,
    transform .32s cubic-bezier(.2,.75,.25,1),
    filter .25s ease;
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button::after {
  content: "";
  position: absolute;
  inset: -45% -70%;
  z-index: 0;
  pointer-events: none;
  opacity: 0;
  transform: translateX(-55%) rotate(12deg);
  transition: opacity .25s ease;
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button > * {
  position: relative;
  z-index: 1;
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-learn::after {
  background: linear-gradient(105deg, transparent 35%, rgba(216, 187, 255, .2) 49%, transparent 63%);
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-awareness::after {
  background: linear-gradient(105deg, transparent 35%, rgba(171, 225, 255, .2) 49%, transparent 63%);
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-learn.active {
  animation: learn-colour-stack .62s cubic-bezier(.18,.72,.25,1) both;
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.sidebar-orbit-awareness.active {
  animation: awareness-colour-stack .62s cubic-bezier(.18,.72,.25,1) both;
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.active::after {
  opacity: 1;
  animation: selected-colour-sweep .75s ease-out both;
}
.main-nav .primary-spaces-cluster .sidebar-orbit-button.active .sidebar-orbit-icon {
  animation: selected-icon-glow .52s ease-out both;
}
@keyframes learn-colour-stack {
  0% { background: linear-gradient(145deg, rgba(23,33,49,.42), rgba(10,15,24,.42)); box-shadow: inset 0 0 0 0 rgba(188,151,255,0); }
  55% { box-shadow: inset 0 0 0 1px rgba(188,151,255,.2), 0 0 18px rgba(151,104,255,.28); }
  100% { background: radial-gradient(ellipse at 18% 0%, rgba(184,137,255,.27), transparent 72%), linear-gradient(145deg, rgba(91,57,145,.58), rgba(30,34,66,.84) 58%, rgba(17,24,43,.92)); }
}
@keyframes awareness-colour-stack {
  0% { background: linear-gradient(150deg, rgba(23,33,49,.42), rgba(10,15,24,.42)); box-shadow: inset 0 0 0 0 rgba(110,199,255,0); }
  55% { box-shadow: inset 0 0 0 1px rgba(110,199,255,.2), 0 0 18px rgba(63,166,255,.28); }
  100% { background: radial-gradient(ellipse at 82% 78%, rgba(255, 207, 82, .22), transparent 48%), radial-gradient(ellipse at 18% 0%, rgba(92,190,255,.28), transparent 72%), linear-gradient(145deg, rgba(31,99,143,.60), rgba(22,48,79,.86) 58%, rgba(14,25,43,.93)); }
}
@keyframes selected-colour-sweep {
  0% { opacity: 0; transform: translateX(-55%) rotate(12deg); }
  35% { opacity: 1; }
  100% { opacity: 0; transform: translateX(55%) rotate(12deg); }
}
@keyframes selected-icon-glow {
  0% { transform: scale(.88); filter: brightness(.85); }
  65% { transform: scale(1.09); filter: brightness(1.3); }
  100% { transform: scale(1); filter: brightness(1); }
}
@media (prefers-reduced-motion: reduce) {
  .main-nav .primary-spaces-cluster .sidebar-orbit-button,
  .main-nav .primary-spaces-cluster .sidebar-orbit-button::after,
  .main-nav .primary-spaces-cluster .sidebar-orbit-button.active,
  .main-nav .primary-spaces-cluster .sidebar-orbit-button.active .sidebar-orbit-icon {
    animation: none !important;
    transition: none !important;
  }
}


/* Keep the four destinations visually connected without a surrounding frame or divider. */
.main-nav .primary-spaces-cluster {
  border: 0 !important;
  outline: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}
.main-nav .primary-spaces-cluster .sidebar-orbit-actions {
  border-top: 0 !important;
}
.main-nav .primary-navigation-portal {
  border: 0 !important;
  box-shadow: none !important;
}
.main-nav .primary-navigation-portal::before,
.main-nav .primary-spaces-cluster::before {
  display: none !important;
  content: none !important;
}


/* Make Impacting read as the action that leads into Zones Around and Your Zones. */
.zones-subnav .sidebar-zones-header {
  position: relative;
  margin-bottom: 4px;
}
.zones-subnav .sidebar-zones-header::after {
  content: "";
  position: absolute;
  left: 20px;
  bottom: -7px;
  width: 1px;
  height: 8px;
  background: linear-gradient(180deg, rgba(167,132,255,.72), rgba(115,185,201,.58));
  box-shadow: 0 0 7px rgba(151,124,255,.22);
  pointer-events: none;
}
.zones-subnav .sidebar-zones-main {
  position: relative;
  gap: 8px;
  min-height: 34px;
  padding: 7px 9px;
  border: 1px solid rgba(151,124,255,.24);
  border-radius: 9px;
  background: linear-gradient(105deg, rgba(103,76,165,.20), rgba(38,63,91,.28) 68%, rgba(21,32,48,.48));
  color: #d7dff0;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.045), 0 3px 10px rgba(8,12,22,.10);
  transition: background .22s ease, border-color .22s ease, box-shadow .22s ease, transform .22s ease;
}
.zones-subnav .sidebar-zones-main:hover,
.zones-subnav .sidebar-zones-main:focus-visible {
  background: linear-gradient(105deg, rgba(133,99,211,.31), rgba(44,86,121,.34) 68%, rgba(24,39,58,.62));
  border-color: rgba(177,148,255,.48);
  color: #f0eaff;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08), 0 0 13px rgba(137,104,232,.13);
}
.zones-subnav .sidebar-zones-main.active {
  background: linear-gradient(105deg, rgba(133,99,211,.30), rgba(44,86,121,.34) 68%, rgba(24,39,58,.62));
  border-color: rgba(177,148,255,.45);
  color: #f0eaff;
}
.zones-subnav .sidebar-zones-main .impact-zone-label {
  flex: 1;
}
.impacting-button-cue {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  color: #b5c5df;
  font-size: 6px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: none;
  white-space: nowrap;
  opacity: .88;
  transition: color .2s ease, transform .2s ease, opacity .2s ease;
}
.impacting-button-cue > span {
  color: #c3a8ff;
  font-size: 11px;
  line-height: 1;
}
.zones-subnav .sidebar-zones-main:hover .impacting-button-cue,
.zones-subnav .sidebar-zones-main:focus-visible .impacting-button-cue {
  color: #f0eaff;
  opacity: 1;
  transform: translateX(2px);
}
.zones-subnav .zones-connected-pair {
  margin-top: 5px;
  border-color: rgba(105,145,199,.11);
  background: linear-gradient(155deg, rgba(25,39,59,.32), rgba(13,20,33,.24));
}


/* Carry the Impacting button's violet-to-blue surface into both zone destinations. */
.zones-subnav .zones-connected-pair {
  border: 1px solid rgba(151,124,255,.18);
  background: linear-gradient(105deg, rgba(103,76,165,.15), rgba(38,63,91,.23) 68%, rgba(21,32,48,.42));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.035), 0 3px 10px rgba(8,12,22,.08);
}
.zones-subnav .zones-connected-pair .zone-space-button {
  border: 1px solid rgba(151,124,255,.13);
  background: linear-gradient(105deg, rgba(103,76,165,.14), rgba(38,63,91,.2) 68%, rgba(21,32,48,.28));
  color: #d7dff0;
  transition: background .22s ease, border-color .22s ease, box-shadow .22s ease, color .22s ease;
}
.zones-subnav .zones-connected-pair .zone-space-button-around.active,
.zones-subnav .zones-connected-pair .zone-space-button-mine.active {
  background: linear-gradient(105deg, rgba(133,99,211,.29), rgba(44,86,121,.31) 68%, rgba(24,39,58,.56));
  border-color: rgba(177,148,255,.38);
  color: #f0eaff;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.06), 0 0 11px rgba(137,104,232,.10);
}
.zones-subnav .zones-connected-pair .zone-space-button:hover,
.zones-subnav .zones-connected-pair .zone-space-button:focus-visible {
  background: linear-gradient(105deg, rgba(133,99,211,.25), rgba(44,86,121,.29) 68%, rgba(24,39,58,.52));
  border-color: rgba(177,148,255,.36);
  color: #f0eaff;
}


/* Rework the relationship as one parent branching into two destinations. */
.zones-subnav .sidebar-zones-header::after {
  left: 20px;
  bottom: -8px;
  height: 9px;
  background: linear-gradient(180deg, rgba(167,132,255,.7), rgba(115,185,201,.6));
  box-shadow: 0 0 6px rgba(151,124,255,.16);
}
.zones-subnav .zones-connected-pair {
  position: relative;
  gap: 5px;
  margin: 1px 0 5px 7px;
  padding: 4px 2px 4px 17px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.zones-subnav .zones-connected-pair::before {
  content: "";
  position: absolute;
  left: 7px;
  top: 0;
  bottom: 18px;
  width: 1px;
  background: linear-gradient(180deg, rgba(167,132,255,.62), rgba(115,185,201,.55));
  box-shadow: 0 0 6px rgba(151,124,255,.15);
  pointer-events: none;
}
.zones-subnav .zones-connected-pair .zones-pair-connection {
  display: none;
}
.zones-subnav .zones-connected-pair .zone-space-button {
  position: relative;
  min-height: 34px;
  border: 1px solid rgba(151,124,255,.16);
  border-radius: 8px;
  background: linear-gradient(105deg, rgba(103,76,165,.14), rgba(38,63,91,.19) 68%, rgba(21,32,48,.30));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.025);
}
.zones-subnav .zones-connected-pair .zone-space-button::before {
  content: "";
  position: absolute;
  left: -11px;
  top: 50%;
  width: 10px;
  height: 1px;
  background: rgba(142,167,220,.62);
  pointer-events: none;
}
.zones-subnav .zones-connected-pair .zone-space-button-around.active,
.zones-subnav .zones-connected-pair .zone-space-button-mine.active {
  border-color: rgba(177,148,255,.4);
  background: linear-gradient(105deg, rgba(133,99,211,.28), rgba(44,86,121,.30) 68%, rgba(24,39,58,.54));
  color: #f0eaff;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.055), 0 0 10px rgba(137,104,232,.09);
}
.zones-subnav .zones-connected-pair .zone-space-button:hover,
.zones-subnav .zones-connected-pair .zone-space-button:focus-visible {
  border-color: rgba(177,148,255,.36);
  background: linear-gradient(105deg, rgba(133,99,211,.23), rgba(44,86,121,.27) 68%, rgba(24,39,58,.49));
  color: #f0eaff;
}

/* Keep the branch line, but remove the horizontal connector beside Your Zones. */
.zones-subnav .zones-connected-pair .zone-space-button-mine::before {
  display: none;
  content: none;
}


/* Give Impacting a clearer violet-blue surface in both idle and selected states. */
.zones-subnav .sidebar-zones-main {
  background:
    radial-gradient(ellipse at 4% 50%, rgba(163,119,255,.18), transparent 52%),
    linear-gradient(105deg, rgba(91,69,151,.32), rgba(37,69,101,.36) 68%, rgba(19,31,49,.72));
  border-color: rgba(159,137,238,.38);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.075),
    inset 3px 0 0 rgba(157,128,255,.62),
    0 3px 12px rgba(7,12,24,.20);
}
.zones-subnav .sidebar-zones-main .icon {
  color: #bda8ff;
  filter: drop-shadow(0 0 4px rgba(166,133,255,.28));
  transition: color .22s ease, filter .22s ease, transform .22s ease;
}
.zones-subnav .sidebar-zones-main:hover,
.zones-subnav .sidebar-zones-main:focus-visible {
  background:
    radial-gradient(ellipse at 4% 50%, rgba(183,143,255,.25), transparent 54%),
    linear-gradient(105deg, rgba(118,83,191,.43), rgba(45,91,130,.43) 68%, rgba(24,40,61,.82));
  border-color: rgba(190,164,255,.64);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.11),
    inset 3px 0 0 rgba(190,157,255,.9),
    0 0 15px rgba(137,104,232,.17);
}
.zones-subnav .sidebar-zones-main:hover .icon,
.zones-subnav .sidebar-zones-main:focus-visible .icon {
  color: #e1d4ff;
  filter: drop-shadow(0 0 6px rgba(183,143,255,.48));
  transform: scale(1.06);
}
.zones-subnav .sidebar-zones-main.active {
  background:
    radial-gradient(ellipse at 4% 50%, rgba(190,151,255,.31), transparent 56%),
    linear-gradient(105deg, rgba(129,91,204,.48), rgba(48,98,137,.45) 68%, rgba(25,43,65,.86));
  border-color: rgba(199,174,255,.72);
  color: #fbf8ff;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.13),
    inset 3px 0 0 #b69aff,
    0 0 17px rgba(137,104,232,.2),
    0 4px 12px rgba(5,10,20,.18);
}
.zones-subnav .sidebar-zones-main.active .icon {
  color: #e4d7ff;
  filter: drop-shadow(0 0 7px rgba(190,151,255,.55));
}
.zones-subnav .sidebar-zones-main.active .impacting-button-cue {
  color: #f0eaff;
  opacity: 1;
}
.zones-subnav .sidebar-zones-main.active .impacting-button-cue > span {
  color: #d8c5ff;
}

/* When Impacting is selected, animate the three directional signals from the impact guide. */
.zones-subnav .sidebar-zones-main .impacting-direction-cues {
  display: none;
}
.zones-subnav .sidebar-zones-main.active .impacting-cue-label,
.zones-subnav .sidebar-zones-main.active .impacting-cue-arrow {
  display: none;
}
.zones-subnav .sidebar-zones-main.active .impacting-direction-cues {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  min-width: 39px;
}
.zones-subnav .sidebar-zones-main.active .impacting-direction-arrow {
  display: inline-block;
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
  animation: impacting-direction-pulse 2.88s linear infinite;
}
.zones-subnav .sidebar-zones-main.active .impacting-direction-arrow.up {
  color: #65d99a;
  text-shadow: 0 0 6px rgba(75, 220, 142, .35);
  animation-delay: 0s;
}
.zones-subnav .sidebar-zones-main.active .impacting-direction-arrow.right {
  color: #ffad55;
  text-shadow: 0 0 6px rgba(255, 160, 65, .38);
  animation-delay: .22s;
}
.zones-subnav .sidebar-zones-main.active .impacting-direction-arrow.down {
  color: #ff646b;
  text-shadow: 0 0 6px rgba(255, 82, 93, .42);
  animation-delay: .44s;
}
@keyframes impacting-direction-pulse {
  0%, 12% { opacity: 1; transform: translateY(-1px) scale(1.14); }
  20%, 100% { opacity: .28; transform: translateY(0) scale(.88); }
}
.zones-subnav .sidebar-zones-main.active .impacting-direction-arrow.up {
  animation-delay: 0s;
}
.zones-subnav .sidebar-zones-main.active .impacting-direction-arrow.right {
  animation-delay: .96s;
}
.zones-subnav .sidebar-zones-main.active .impacting-direction-arrow.down {
  animation-delay: 1.92s;
}
@media (prefers-reduced-motion: reduce) {
  .zones-subnav .sidebar-zones-main.active .impacting-direction-arrow {
    animation: none;
  }
}

/* Refined Anfas identity: consistent editorial wordmark across desktop and mobile. */
.brand { align-items: center; gap: 12px; padding-top: 2px; }
.brand-orbit {
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(136,181,239,.38);
  border-radius: 12px;
  background: linear-gradient(145deg,rgba(34,59,90,.9),rgba(10,18,31,.98));
  box-shadow: inset 0 1px rgba(255,255,255,.075), 0 5px 15px rgba(0,0,0,.18);
}
.brand-orbit::before {
  content: "";
  width: 20px;
  height: 20px;
  border: 1px solid rgba(156,201,250,.88);
  border-radius: 50%;
  transform: rotate(-35deg) scaleY(.68);
}
.brand-orbit span {
  position: absolute;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #e3f1ff;
  box-shadow: 0 0 10px rgba(137,193,255,.75);
}
.brand-name { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.brand-name strong {
  color: #f0f5fc;
  font-size: 23px;
  line-height: 1;
  font-weight: 760;
  letter-spacing: -.055em;
}
.brand-name small {
  color: #8297b3;
  font-size: 7px;
  line-height: 1;
  font-weight: 750;
  letter-spacing: .13em;
  white-space: nowrap;
}
.mobile-brand { display: none; }
.mobile-network-launch { display: none; }
.mobile-network-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  justify-content: flex-end;
  background: rgba(2,6,12,.62);
  backdrop-filter: blur(5px);
}
.mobile-network-drawer {
  width: min(410px, 88vw);
  height: 100%;
  overflow-y: auto;
  box-sizing: border-box;
  padding: 24px 18px calc(28px + env(safe-area-inset-bottom));
  border-left: 1px solid rgba(132,178,235,.22);
  background: linear-gradient(160deg,#101c2d 0%,#09111d 48%,#080d16 100%);
  box-shadow: -18px 0 55px rgba(0,0,0,.35);
}
.mobile-network-drawer-head { display: flex; align-items: flex-start; gap: 12px; justify-content: space-between; }
.mobile-network-drawer-head h2 { margin: 9px 0 6px; color: #edf5ff; font-size: 21px; letter-spacing: -.035em; line-height: 1.2; }
.mobile-network-drawer-head p { margin: 0; color: #91a3bb; font-size: 11px; line-height: 1.65; }
.mobile-network-drawer-close { flex: 0 0 32px; width: 32px; height: 32px; border: 1px solid rgba(143,177,220,.2); border-radius: 9px; background: rgba(255,255,255,.035); color: #d5e6fb; font-size: 22px; cursor: pointer; }
.mobile-drawer-tabs { margin-top: 22px; }
.mobile-network-drawer-stream { display: grid; gap: 9px; margin-top: 15px; }
.mobile-network-drawer-rooms { display: grid; gap: 8px; margin-top: 23px; }
.mobile-network-drawer-note { margin-top: 17px; color: #6f829b; font-size: 9px; line-height: 1.6; }
@media (max-width: 760px) {
  .brand { display: none; }
  .mobile-brand { display: flex; }
  .mobile-network-launch { display: flex; }
}


/* Keep the Circles dimension portal beside the Anfas logo, not between Home and Live Flow. */
.brand .brand-dimension-portal {
  flex: 0 0 18px;
  width: 18px !important;
  height: 34px !important;
  min-height: 34px !important;
  margin: 0 1px 0 0 !important;
  padding: 0 !important;
  align-self: center;
  background: transparent !important;
}
.brand .brand-dimension-portal .dimension-portal-line {
  height: 25px;
}
.brand .brand-dimension-portal:hover .dimension-portal-line,
.brand .brand-dimension-portal:focus-visible .dimension-portal-line {
  height: 30px;
}



/* Join the blue orbit signal to the Anfas wordmark as one continuous logo */
.sidebar .brand {
  gap: 8px;
}
.sidebar .brand-orbit {
  flex: 0 0 36px;
  overflow: visible;
  z-index: 2;
}
.sidebar .brand-orbit span::after {
  width: 30px;
  left: 5px;
  top: 3px;
  transform: rotate(-4deg);
}
.sidebar .brand-name {
  position: relative;
  z-index: 1;
}


/* Anfas signature — make the orbit, blue signal and wordmark visibly read as one mark */
.sidebar .brand { gap: 4px !important; }
.sidebar .brand-orbit { flex: 0 0 38px !important; overflow: visible !important; z-index: 2; }
.sidebar .brand-orbit span::after {
  width: 43px !important;
  height: 1.5px !important;
  left: 5px !important;
  top: 5px !important;
  transform: none !important;
  background: linear-gradient(90deg, #83bdff 0%, #5c9eff 48%, rgba(92,158,255,.12) 100%) !important;
  box-shadow: 0 0 7px rgba(91,157,255,.58), 0 0 16px rgba(91,157,255,.2) !important;
}
.sidebar .brand-name { position: relative; z-index: 1; margin-left: -2px; min-width: 0; }
.sidebar .brand-name strong {
  font-size: 18px !important;
  font-weight: 650 !important;
  letter-spacing: .17em !important;
  line-height: 1.1 !important;
  color: #f5f8ff !important;
  text-shadow: 0 0 18px rgba(103,164,255,.14) !important;
}
.sidebar .brand-name small {
  margin-top: 5px !important;
  font-size: 8px !important;
  font-weight: 650 !important;
  letter-spacing: .09em !important;
  line-height: 1.35 !important;
  white-space: nowrap !important;
  color: #a9bbd5 !important;
}


/* Mobile NetworkChat opens as a dedicated drawer, separate from the four main spaces. */
.mobile-network-launch { display:none; }
.mobile-network-close { display:none; }
@media (max-width:760px) {
  .mobile-network-launch { display:inline-flex; align-items:center; justify-content:center; color:#b8e8f5; border-color:rgba(105,190,220,.35); }
  .home-commons-content .home-view-switch { order:-1; position:relative; z-index:3; margin:0 0 12px; }
  .home-commons-content:not(.home-hero-collapsed) .home-view-switch { margin-top:0; }
  .home-header-chat {
    position:fixed !important;
    z-index:10050 !important;
    top:0 !important;
    right:0 !important;
    bottom:0 !important;
    width:min(92vw,430px) !important;
    max-width:100vw !important;
    height:100dvh !important;
    max-height:100dvh !important;
    margin:0 !important;
    padding:54px 14px 20px !important;
    overflow-y:auto !important;
    overscroll-behavior:contain;
    border-radius:18px 0 0 18px !important;
    border:1px solid rgba(111,170,224,.3) !important;
    background:linear-gradient(155deg,rgba(15,26,43,.99),rgba(7,13,23,.99) 65%) !important;
    box-shadow:-22px 0 70px rgba(0,0,0,.52),0 0 0 100vmax rgba(0,0,0,.56) !important;
    animation:network-drawer-enter .24s cubic-bezier(.2,.75,.25,1) both;
  }
  .home-header-chat-heading { position:relative; padding-right:24px; }
  .mobile-network-close {
    display:inline-flex;
    position:fixed;
    z-index:2;
    top:10px;
    right:12px;
    width:34px;
    height:34px;
    align-items:center;
    justify-content:center;
    border:1px solid rgba(132,168,211,.32);
    border-radius:10px;
    color:#e3efff;
    background:rgba(24,38,58,.95);
    font-size:23px;
    line-height:1;
    cursor:pointer;
  }
}
@keyframes network-drawer-enter {
  from { transform:translateX(22px); opacity:.65; }
  to { transform:translateX(0); opacity:1; }
}

/* Global mobile NetworkChat drawer, available from every view. */
.mobile-network-overlay { display:none; }
@media (max-width:760px) {
  .mobile-network-overlay {
    display:block; position:fixed; inset:0; z-index:12000;
    background:rgba(2,7,14,.62); backdrop-filter:blur(5px);
  }
  .mobile-network-drawer {
    position:absolute; top:0; right:0; bottom:0; display:flex; flex-direction:column;
    gap:14px; width:min(92vw,430px); max-width:100%; height:100dvh; overflow-y:auto;
    padding:18px 14px 24px; border:1px solid rgba(111,170,224,.3); border-radius:18px 0 0 18px;
    color:#dce8f8; background:radial-gradient(ellipse at 100% 0%,rgba(74,122,211,.14),transparent 42%),linear-gradient(155deg,#0f1a2b,#070d17 70%);
    box-shadow:-22px 0 70px rgba(0,0,0,.52); animation:network-drawer-enter .24s cubic-bezier(.2,.75,.25,1) both;
  }
  .mobile-network-drawer-head { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; padding:30px 2px 4px; }
  .mobile-network-drawer-head h2 { margin:5px 0; color:#e8f1ff; font-size:21px; letter-spacing:-.035em; }
  .mobile-network-drawer-head p { margin:0; color:#91a5bd; font-size:11px; line-height:1.55; }
  .mobile-network-drawer-close { flex:0 0 36px; width:36px; height:36px; border:1px solid rgba(132,168,211,.32); border-radius:10px; color:#e3efff; background:rgba(24,38,58,.95); font-size:24px; cursor:pointer; }
  .mobile-drawer-tabs { display:grid; grid-template-columns:1fr 1fr; margin:0; }
  .mobile-drawer-tabs button { justify-content:center; min-height:42px; }
  .mobile-network-drawer-stream { display:grid; gap:8px; }
  .mobile-network-drawer-stream .home-local-world-item { padding:12px; }
  .mobile-network-drawer-rooms { display:grid; gap:8px; }
  .mobile-network-drawer-rooms > .home-network-section-label { margin:3px 0; }
  .mobile-network-drawer-rooms .home-chat-room { width:100%; text-align:left; }
  .mobile-network-drawer-note { margin:auto 0 0; color:#71859f; font-size:9px; line-height:1.5; }
  /* The old Home-inline panel must not duplicate the new global drawer on phones. */
  .home-commons-content > .home-header-chat { display:none !important; }
  .home-commons-content .home-view-switch { display:flex; justify-content:flex-end; position:relative; z-index:4; order:-2; width:max-content; margin:0 0 12px auto !important; }
  .home-commons-content .home-hero-control { order:-1; }
}
@media (prefers-reduced-motion:reduce) {
