/* Impacting entry point: country-first discovery or selecting an issue linked to a Zone. */
.impacting-path-panel {
  margin: 0 0 18px;
  padding: 19px;
  border: 1px solid rgba(136,163,205,.18);
  border-radius: 15px;
  background:
    radial-gradient(ellipse at 2% 0%, rgba(119,91,190,.14), transparent 45%),
    linear-gradient(125deg, rgba(23,35,53,.86), rgba(12,20,32,.94) 58%, rgba(17,29,43,.88));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.035), 0 8px 22px rgba(0,0,0,.08);
}
.impacting-path-heading {
  display:flex; align-items:center; justify-content:space-between; gap:16px; margin-bottom:15px;
}
.impacting-path-heading h2 { margin:7px 0 5px; color:#edf4ff; font-size:clamp(17px,2vw,23px); font-weight:650; letter-spacing:-.025em; }
.impacting-path-heading p { margin:0; max-width:680px; color:#9cacc2; font-size:11px; line-height:1.65; }
.impacting-path-orbit { display:flex; flex:0 0 43px; width:43px; height:43px; align-items:center; justify-content:center; border:1px solid rgba(164,143,245,.35); border-radius:50%; color:#c2b3ff; background:radial-gradient(circle,rgba(132,104,214,.18),rgba(16,28,43,.2)); font-size:25px; box-shadow:0 0 24px rgba(111,91,190,.12); }
.impacting-path-options { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; }
.impacting-path-option { display:flex; flex-direction:column; align-items:stretch; min-width:0; padding:14px; border:1px solid rgba(132,160,202,.15); border-radius:11px; background:linear-gradient(140deg,rgba(27,43,64,.72),rgba(13,23,37,.75)); }
.impacting-path-step { margin-bottom:10px; color:#b6a3f7; font-size:8px; font-weight:850; letter-spacing:.15em; }
.impacting-path-option label { margin-bottom:8px; color:#e3ecf9; font-size:12px; font-weight:750; }
.impacting-path-option select { width:100%; min-width:0; min-height:38px; padding:8px 10px; border:1px solid rgba(135,165,208,.24); border-radius:8px; background:#101d2d; color:#e1eafa; font:inherit; font-size:11px; }
.impacting-path-option p { min-height:30px; margin:9px 0; color:#8fa1b9; font-size:10px; line-height:1.55; }
.impacting-path-count { color:#83d3b0; font-size:9px; font-weight:750; }
.impacting-focus-button { display:flex; align-items:center; justify-content:space-between; gap:8px; min-height:32px; margin-top:auto; padding:8px 10px; border:1px solid rgba(139,119,225,.32); border-radius:8px; background:linear-gradient(105deg,rgba(99,76,157,.26),rgba(35,70,101,.3)); color:#e0d8ff; font-size:9px; font-weight:800; letter-spacing:.04em; cursor:pointer; }
.impacting-focus-button:disabled { opacity:.42; cursor:not-allowed; }
.impacting-empty-note { margin:12px 0 0; color:#c4b6e7; font-size:10px; line-height:1.6; }
.awareness-shared-item.impacting-issue-selected { border-color:rgba(149,127,237,.65); box-shadow:0 0 0 1px rgba(149,127,237,.14),0 8px 25px rgba(80,58,140,.13); }
@media(max-width:680px) {
  .impacting-path-panel { padding:13px; border-radius:12px; }
  .impacting-path-options { grid-template-columns:minmax(0,1fr); }
  .impacting-path-option p { min-height:0; }
  .impacting-path-heading { align-items:flex-start; }
  .impacting-path-orbit { width:34px; height:34px; flex-basis:34px; font-size:20px; }
}


/* On phones, Home remains in the mobile top bar; hide its duplicate in the sidebar. */
@media screen and (max-width: 760px) {
  .sidebar .main-nav .primary-spaces-cluster > .primary-navigation-portal[aria-label="Home"] {
    display: none !important;
  }
}


/* Organization calls: community-authored invitations, separate from platform navigation. */
.organization-calls-strip { margin-top:16px; padding:16px; border:1px solid rgba(120,153,190,.16); border-radius:14px; background:linear-gradient(125deg,rgba(22,36,53,.76),rgba(13,22,34,.84)); }
.organization-calls-heading { display:flex; align-items:center; justify-content:space-between; gap:14px; margin-bottom:13px; }
.organization-calls-heading h2 { margin:5px 0 4px; color:#edf4ff; font-size:18px; letter-spacing:-.025em; }
.organization-calls-heading p { margin:0; color:#9aabc1; font-size:10px; line-height:1.55; }
.organization-calls-heading > button { flex:0 0 auto; padding:8px 10px; border:1px solid rgba(131,159,204,.23); border-radius:8px; color:#d7e7fa; background:rgba(44,66,93,.38); font-size:10px; font-weight:750; cursor:pointer; }
.organization-call-cards { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:11px; }
.organization-call-card { min-width:0; overflow:hidden; border:1px solid rgba(127,155,190,.17); border-radius:11px; background:rgba(9,18,29,.54); }
.organization-call-card > img { display:block; width:100%; height:112px; object-fit:cover; filter:saturate(.78) brightness(.82); }
.organization-call-card-copy { padding:12px; }
.organization-call-card-copy > span { color:#a8b9d7; font-size:8px; font-weight:850; letter-spacing:.12em; }
.organization-call-card-copy h3 { margin:7px 0 6px; color:#e9f1fc; font-size:13px; line-height:1.35; }
.organization-call-card-copy p { min-height:42px; margin:0 0 10px; color:#99aabe; font-size:10px; line-height:1.55; }
.organization-call-card-copy button { padding:0; border:0; color:#b9c9ff; background:transparent; font-size:9px; font-weight:800; cursor:pointer; text-align:left; }
.impacting-report-header { display:flex; align-items:center; justify-content:space-between; gap:14px; margin:0 0 13px; padding:11px 12px; border:1px solid rgba(105,180,167,.2); border-radius:10px; background:linear-gradient(100deg,rgba(34,105,94,.14),rgba(31,51,70,.24)); }
.impacting-report-header > div:first-child { display:flex; align-items:center; gap:10px; min-width:0; }
.impacting-report-mark { display:flex; flex:0 0 30px; width:30px; height:30px; align-items:center; justify-content:center; border:1px solid rgba(110,211,179,.28); border-radius:9px; color:#91e0c1; background:rgba(54,135,112,.14); font-size:18px; }
.impacting-report-header strong { color:#e4f4f1; font-size:11px; }
.impacting-report-header p { margin:3px 0 0; color:#91aeb0; font-size:9px; line-height:1.45; }
.impacting-report-actions { display:flex; flex-wrap:wrap; justify-content:flex-end; gap:7px; }
.impacting-report-actions button { min-height:30px; padding:6px 9px; border:1px solid rgba(131,170,193,.2); border-radius:7px; color:#c9d8e8; background:rgba(24,39,55,.72); font-size:9px; font-weight:750; cursor:pointer; }
.impacting-report-actions button.active { border-color:rgba(111,212,176,.42); color:#a6ebce; background:rgba(39,112,89,.2); }
.impacting-report-actions button.impacting-report-submit { border-color:rgba(150,132,230,.35); color:#ded5ff; background:linear-gradient(100deg,rgba(110,84,176,.25),rgba(49,91,122,.25)); }
@media(max-width:760px) { .organization-calls-strip { padding:12px; } .organization-calls-heading { align-items:flex-start; } .organization-calls-heading h2 { font-size:16px; } .organization-calls-heading > button { max-width:112px; white-space:normal; } .organization-call-cards { grid-template-columns:1fr; } .organization-call-card { display:grid; grid-template-columns:104px minmax(0,1fr); } .organization-call-card > img { height:100%; min-height:155px; } .organization-call-card-copy { padding:10px; } .organization-call-card-copy p { min-height:0; } .impacting-report-header { align-items:flex-start; flex-direction:column; } .impacting-report-actions { justify-content:flex-start; width:100%; } .impacting-report-actions button { flex:1 1 auto; } }



/* Desktop: keep issue shortcuts grouped immediately beside notifications on the right. */
@media (min-width: 761px) {
  header.topbar .top-impact-actions {
    order: 3;
    flex: 0 1 auto;
    width: auto;
    max-width: min(390px, 35vw);
    margin-left: auto;
  }
  header.topbar .top-actions {
    order: 4;
    flex: 0 0 auto;
    margin-left: 0;
  }
  header.topbar .mobile-home-space-row { order: 2; }
}

/* Quick access to issue discovery and reporting, directly below the global search. */
.top-impact-actions { display:flex; align-items:center; gap:7px; width:100%; min-width:0; }
.top-impact-action { display:flex; align-items:center; justify-content:center; gap:7px; min-height:34px; padding:6px 11px; border:1px solid rgba(133,164,195,.2); border-radius:9px; color:#d9e7f7; background:linear-gradient(110deg,rgba(31,50,73,.82),rgba(20,32,48,.88)); font-size:10px; font-weight:780; cursor:pointer; transition:border-color .18s ease, background .18s ease; }
.top-impact-action > span:first-child { color:#9fdbc9; font-size:15px; }
.top-impact-action small { color:#91a5bd; font-size:9px; font-weight:550; }
.top-impact-action:hover { border-color:rgba(121,190,177,.48); background:rgba(43,70,85,.86); }
.top-impact-action.top-impact-report { border-color:rgba(148,130,223,.3); color:#e2d9ff; background:linear-gradient(110deg,rgba(92,72,145,.25),rgba(34,54,77,.75)); }
.top-impact-action.top-impact-report > span:first-child { color:#c7b8ff; }
@media(max-width:760px) {
  .top-impact-actions { grid-column:1 / -1; display:grid; grid-template-columns:minmax(0,1fr) minmax(0,1fr); gap:6px; }
  .top-impact-action { justify-content:flex-start; min-width:0; padding:8px 9px; font-size:10px; }
  .top-impact-action small { display:none; }
}


/* Refined issue-reporting panel and shared-space actions */
.awareness-content .awareness-category-heading > .awareness-submit-button,
.awareness-content .awareness-submit-button {
  min-height: 38px;
  padding: 10px 15px;
  border: 1px solid rgba(119, 174, 222, .32);
  border-radius: 10px;
  color: #e1efff;
  background: linear-gradient(115deg, rgba(51, 105, 157, .34), rgba(42, 112, 103, .22));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.055), 0 5px 16px rgba(0,0,0,.12);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .07em;
  transition: transform .18s ease, border-color .18s ease, background .18s ease, box-shadow .18s ease;
}
.awareness-content .awareness-submit-button:hover {
  transform: translateY(-1px);
  border-color: rgba(143, 207, 232, .58);
  background: linear-gradient(115deg, rgba(57, 126, 185, .43), rgba(47, 137, 116, .3));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08), 0 8px 20px rgba(0,0,0,.2);
}
.awareness-content .awareness-submit-button:focus-visible,
.impacting-report-actions button:focus-visible,
.top-impact-action:focus-visible {
  outline: 2px solid rgba(137, 207, 221, .82);
  outline-offset: 3px;
}
.impacting-report-header {
  padding: 13px 14px;
  border-color: rgba(102, 185, 166, .25);
  border-radius: 12px;
  background: linear-gradient(105deg, rgba(28, 94, 83, .18), rgba(27, 46, 66, .3));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.025);
}
.impacting-report-actions button {
  min-height: 36px;
  padding: 8px 12px;
  border-radius: 9px;
  transition: transform .16s ease, border-color .16s ease, background .16s ease, box-shadow .16s ease;
}
.impacting-report-actions button:hover { transform: translateY(-1px); border-color: rgba(139, 181, 209, .42); }
.impacting-report-actions button.impacting-report-submit {
  border-color: rgba(158, 142, 235, .42);
  color: #eee8ff;
  background: linear-gradient(115deg, rgba(105, 79, 166, .34), rgba(47, 91, 126, .32));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.05);
}
.impacting-report-actions button.impacting-report-submit:hover {
  border-color: rgba(180, 164, 255, .68);
  background: linear-gradient(115deg, rgba(121, 91, 190, .46), rgba(53, 112, 148, .4));
}
.awareness-create-card {
  position: relative;
  overflow: hidden;
  margin: 16px 0 20px;
  padding: clamp(16px, 2.2vw, 25px);
  border: 1px solid rgba(104, 173, 195, .25);
  border-radius: 16px;
  background:
    radial-gradient(ellipse at 0% 0%, rgba(48, 125, 132, .14), transparent 48%),
    linear-gradient(145deg, rgba(20, 36, 50, .96), rgba(10, 17, 27, .98) 70%);
  box-shadow: 0 18px 42px rgba(0,0,0,.2), inset 0 1px 0 rgba(255,255,255,.035);
  animation: issue-panel-enter .24s ease-out both;
}
.awareness-create-card::before {
  content: "";
  position: absolute;
  top: 0; left: 20px; right: 20px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(116, 205, 190, .5), rgba(154, 145, 230, .42), transparent);
  pointer-events: none;
}
.awareness-create-card .awareness-card-head { align-items: center; margin-bottom: 9px; }
.awareness-create-card .awareness-kicker {
  color: #8dd6c4;
  font-size: 9px;
  letter-spacing: .16em;
}
.awareness-create-card .awareness-learn-mark {
  width: 32px; height: 32px;
  border: 1px solid rgba(112, 194, 178, .22);
  border-radius: 11px;
  color: #8fe0c6;
  background: rgba(48, 126, 109, .13);
  font-size: 15px;
}
.awareness-create-card > h2 { margin: 4px 0 8px; font-size: clamp(19px, 2.1vw, 25px); letter-spacing: -.025em; }
.awareness-create-card > p { max-width: 720px; margin-bottom: 18px; color: #a0b3c6; font-size: 11px; line-height: 1.7; }
.awareness-create-card .awareness-form-label { gap: 8px; margin: 10px 0; color: #b4c7d9; font-size: 10px; font-weight: 750; }
.awareness-create-card .awareness-form-label input,
.awareness-create-card .awareness-form-label select,
.awareness-create-card .awareness-form-label textarea {
  min-height: 40px;
  padding: 11px 12px;
  border-color: rgba(136, 169, 198, .2);
  border-radius: 9px;
  background: rgba(4, 11, 19, .66);
  color: #e5eff9;
  font-size: 11px;
  transition: border-color .16s ease, box-shadow .16s ease, background .16s ease;
}
.awareness-create-card .awareness-form-label input::placeholder,
.awareness-create-card .awareness-form-label textarea::placeholder { color: #667d93; }
.awareness-create-card .awareness-form-label input:focus,
.awareness-create-card .awareness-form-label select:focus,
.awareness-create-card .awareness-form-label textarea:focus {
  border-color: rgba(110, 196, 188, .58);
  background: rgba(6, 15, 24, .92);
  box-shadow: 0 0 0 3px rgba(65, 147, 137, .1);
}
.awareness-create-card .awareness-form-label textarea { min-height: 84px; }
.awareness-create-card .awareness-form-row { gap: 14px; align-items: flex-start; }
.awareness-create-card .awareness-form-actions {
  justify-content: flex-end;
  gap: 9px;
  margin-top: 20px;
  padding-top: 15px;
  border-top: 1px solid rgba(255,255,255,.07);
}
.awareness-create-card .awareness-form-actions .awareness-link {
  min-height: 38px;
  margin: 0;
  padding: 10px 13px;
  border: 1px solid rgba(143, 165, 190, .17);
  border-radius: 9px;
  color: #9eb1c5;
  font-size: 9px;
