/* Keep the active navigation signal below the label, never across the text. */
.primary-navigation-portal .primary-space-nav-button.active,
.sidebar .sidebar-zones-main.active,
.sidebar .sidebar-flow-main.active,
.sidebar .sidebar-subnav button.active { position: relative; }
.primary-navigation-portal .primary-space-nav-button.active::before,
.sidebar .sidebar-zones-main.active::before,
.sidebar .sidebar-flow-main.active::before,
.sidebar .sidebar-subnav button.active::before {
  content: "";
  position: absolute;
  left: 50%;
  right: auto;
  top: auto;
  bottom: 4px;
  width: 28px;
  height: 2px;
  border: 0;
  border-radius: 999px;
  opacity: .95;
  pointer-events: none;
  transform: translateX(-50%);
  background: linear-gradient(90deg, transparent, #a78bfa 28%, #79aaff 72%, transparent);
  box-shadow: 0 0 6px rgba(137, 125, 255, .55), 0 0 12px rgba(91, 155, 255, .28);
  animation: nav-label-underline-glow 2.4s ease-in-out infinite;
}
@keyframes nav-label-underline-glow {
  0%, 100% { opacity: .55; filter: brightness(.85); }
  50% { opacity: 1; filter: brightness(1.3); }
}
@media (prefers-reduced-motion: reduce) {
  .primary-navigation-portal .primary-space-nav-button.active::before,
  .sidebar .sidebar-zones-main.active::before,
  .sidebar .sidebar-flow-main.active::before,
  .sidebar .sidebar-subnav button.active::before {
    animation: none;
  }
}


/* Final fix: make Home and Live Flow fill the full mobile bar, like Impact. */
@media screen and (max-width: 760px) {
  header.topbar {
    grid-template-rows: 35px 36px 36px 36px !important;
  }
  header.topbar > .mobile-home-nav-pair {
    display: flex !important;
    grid-column: 1 / -1 !important;
    grid-row: 3 !important;
    position: relative !important;
    inset: auto !important;
    align-self: stretch !important;
    justify-self: stretch !important;
    width: 100% !important;
    min-width: 0 !important;
    height: 36px !important;
    margin: 0 !important;
    padding: 0 !important;
    gap: 6px !important;
    box-sizing: border-box !important;
  }
  header.topbar > .mobile-home-nav-pair > .mobile-home-pair-button {
    display: flex !important;
    position: relative !important;
    grid-column: auto !important;
    grid-row: auto !important;
