/* Live Flow's internal view switch keeps Feed inside Live Flow instead of Home. */
.live-flow-space-nav {
  display: flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  max-width: 100%;
  margin: 0 0 18px;
  padding: 4px;
