  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 36px;
  padding: 7px 15px;
  border: 1px solid transparent;
  border-radius: 999px;
  color: var(--muted, #aab6ca);
  background: transparent;
  font: inherit;
  font-size: .88rem;
  cursor: pointer;
  transition: color .18s ease, background .18s ease, border-color .18s ease, box-shadow .18s ease;
}
